-- ========================================================================
-- 20260905000008_user_settings.sql
-- ========================================================================

-- JLIKA Gym — user settings.
-- Created here because the nutrition targets read from it; the settings screen
-- that writes to it arrives in Phase 6.

create table if not exists public.user_settings (
  user_id uuid primary key references auth.users on delete cascade,
  training_days int[] not null default '{0,1,3,4}',   -- 0 = Monday
  default_rest_seconds int not null default 90 check (default_rest_seconds between 15 and 600),
  auto_rest boolean not null default true,
  keyboard_shortcuts boolean not null default true,
  show_e1rm boolean not null default false,
  deficit_kcal int not null default 400 check (deficit_kcal between 0 and 1200),
  protein_g_per_kg numeric(3,1) not null default 2.4 check (protein_g_per_kg between 1.0 and 4.0),
  fat_pct numeric(3,2) not null default 0.28 check (fat_pct between 0.15 and 0.60),
  refeed_day int check (refeed_day between 0 and 6),  -- null = none
  auto_adjust boolean not null default true,
  ask_before_adjust boolean not null default true,
  blur_thumbnails boolean not null default false,
  strip_exif boolean not null default true,
  notify_weighin boolean not null default true,
  notify_unpublished_week boolean not null default true,
  meals_per_day int not null default 4 check (meals_per_day between 3 and 5)
);

alter table public.user_settings enable row level security;

drop policy if exists "user_settings: own row" on public.user_settings;
create policy "user_settings: own row"
  on public.user_settings for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Give every account a settings row up front, so no screen has to cope with
-- its absence. Extends the Phase 1 trigger rather than replacing it.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (
    new.id,
    coalesce(
      nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
      nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(trim(new.raw_user_meta_data ->> 'name'), ''),
      split_part(new.email, '@', 1)
    ),
    nullif(trim(new.raw_user_meta_data ->> 'avatar_url'), '')
  )
  on conflict (id) do nothing;

  insert into public.user_settings (user_id)
  values (new.id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

insert into public.user_settings (user_id)
select id from auth.users
on conflict (user_id) do nothing;


-- ========================================================================
-- 20260905000009_crew.sql
-- ========================================================================

-- JLIKA Gym — Phase 6: crew links, invites and sharing preferences.
--
-- Friends share almost nothing. Only a display name, a program name, which days
-- had a session and a streak ever cross the boundary, and each of those is
-- gated by the owner's sharing_prefs. Weights, measurements, photos and sets
-- are never exposed — the crew view is a SECURITY DEFINER function that reads
-- each member's own rows and returns aggregates only.

create table if not exists public.sharing_prefs (
  user_id uuid primary key references auth.users on delete cascade,
  share_sessions boolean not null default true,
  share_streak boolean not null default true,
  share_program_name boolean not null default true
);

alter table public.sharing_prefs enable row level security;

drop policy if exists "sharing_prefs: own row" on public.sharing_prefs;
create policy "sharing_prefs: own row"
  on public.sharing_prefs for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create table if not exists public.crew_invites (
  code text primary key,
  inviter_id uuid not null references auth.users on delete cascade,
  uses_left int not null default 3 check (uses_left >= 0),
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index if not exists crew_invites_inviter_idx on public.crew_invites (inviter_id);

alter table public.crew_invites enable row level security;

-- You can manage your own codes. Redeeming someone else's goes through
-- redeem_crew_invite(), which is SECURITY DEFINER — a code is not readable.
drop policy if exists "crew_invites: own rows" on public.crew_invites;
create policy "crew_invites: own rows"
  on public.crew_invites for all
  using (inviter_id = (select auth.uid()))
  with check (inviter_id = (select auth.uid()));

create table if not exists public.crew_links (
  user_id uuid not null references auth.users on delete cascade,
  friend_id uuid not null references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, friend_id),
  constraint crew_links_no_self check (user_id <> friend_id)
);

alter table public.crew_links enable row level security;

drop policy if exists "crew_links: own rows" on public.crew_links;
create policy "crew_links: own rows"
  on public.crew_links for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

insert into public.sharing_prefs (user_id)
select id from auth.users
on conflict (user_id) do nothing;

-- Extend the signup trigger so sharing prefs exist from the start too.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (
    new.id,
    coalesce(
      nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
      nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(trim(new.raw_user_meta_data ->> 'name'), ''),
      split_part(new.email, '@', 1)
    ),
    nullif(trim(new.raw_user_meta_data ->> 'avatar_url'), '')
  )
  on conflict (id) do nothing;

  insert into public.user_settings (user_id) values (new.id)
  on conflict (user_id) do nothing;

  insert into public.sharing_prefs (user_id) values (new.id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

-- --------------------------------------------------------------- redemption

/**
 * Redeems an invite code, linking both people in both directions.
 * SECURITY DEFINER because the redeemer cannot select the invite row itself.
 */
create or replace function public.redeem_crew_invite(invite_code text)
returns table (friend_id uuid, friend_name text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.crew_invites%rowtype;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  select * into invite
  from public.crew_invites
  where code = upper(trim(invite_code))
  for update;

  if not found then
    raise exception 'That invite code does not exist';
  end if;
  if invite.expires_at < now() then
    raise exception 'That invite code has expired';
  end if;
  if invite.uses_left <= 0 then
    raise exception 'That invite code has been used up';
  end if;
  if invite.inviter_id = caller then
    raise exception 'You cannot use your own invite code';
  end if;

  insert into public.crew_links (user_id, friend_id)
  values (caller, invite.inviter_id), (invite.inviter_id, caller)
  on conflict do nothing;

  update public.crew_invites
  set uses_left = uses_left - 1
  where code = invite.code;

  return query
  select p.id, p.display_name
  from public.profiles p
  where p.id = invite.inviter_id;
end;
$$;

revoke all on function public.redeem_crew_invite(text) from public;
grant execute on function public.redeem_crew_invite(text) to authenticated;

-- ------------------------------------------------------------- crew overview

/**
 * What your crew is allowed to see about you.
 *
 * Reads each friend's own rows under SECURITY DEFINER and returns only
 * aggregates, each gated by that friend's sharing_prefs. No weights, no
 * measurements, no photos, no set data leaves this function.
 */
create or replace function public.crew_overview()
returns table (
  friend_id uuid,
  display_name text,
  avatar_url text,
  program_name text,
  sessions_this_week int[],
  streak int
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  week_start date := (date_trunc('week', now() at time zone 'utc'))::date;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  return query
  with friends as (
    select cl.friend_id as id
    from public.crew_links cl
    where cl.user_id = caller
    union
    select caller
  ),
  prefs as (
    select f.id,
           coalesce(sp.share_sessions, true) as share_sessions,
           coalesce(sp.share_streak, true) as share_streak,
           coalesce(sp.share_program_name, true) as share_program_name
    from friends f
    left join public.sharing_prefs sp on sp.user_id = f.id
  ),
  week as (
    select s.user_id,
           array_agg(distinct extract(isodow from s.started_at)::int - 1) as days
    from public.workout_sessions s
    join friends f on f.id = s.user_id
    where s.ended_at is not null
      and s.started_at >= week_start
    group by s.user_id
  ),
  streaks as (
    select s.user_id, count(distinct s.started_at::date)::int as days
    from public.workout_sessions s
    join friends f on f.id = s.user_id
    where s.ended_at is not null
      and s.started_at >= now() - interval '30 days'
    group by s.user_id
  ),
  programs as (
    select distinct on (w.user_id) w.user_id, w.label
    from public.program_weeks w
    join friends f on f.id = w.user_id
    where w.status = 'published'
    order by w.user_id, w.week_start desc
  )
  select
    p.id,
    pr.display_name,
    pr.avatar_url,
    case when p.share_program_name then programs.label else null end,
    case when p.share_sessions then coalesce(week.days, '{}'::int[]) else '{}'::int[] end,
    case when p.share_streak then coalesce(streaks.days, 0) else 0 end
  from prefs p
  join public.profiles pr on pr.id = p.id
  left join week on week.user_id = p.id
  left join streaks on streaks.user_id = p.id
  left join programs on programs.user_id = p.id
  order by pr.display_name;
end;
$$;

revoke all on function public.crew_overview() from public;
grant execute on function public.crew_overview() to authenticated;


-- ========================================================================
-- 20260905000010_league.sql
-- ========================================================================

-- JLIKA Gym — Phase 7: the crew league.
--
-- Only percentages and points ever cross between members. Standings come from
-- league_scores, which a nightly job computes from each member's own rows;
-- league_standings() is SECURITY DEFINER and returns aggregates only.
--
-- Every table is created first, then every policy. Several policies reference
-- league_members, so defining them inline would fail on the tables declared
-- before it.

-- ------------------------------------------------------------------ tables

create table if not exists public.league_seasons (
  id uuid primary key default gen_random_uuid(),
  crew_owner_id uuid not null references auth.users on delete cascade,
  name text not null,
  starts_on date not null,
  ends_on date not null,
  created_at timestamptz not null default now(),
  constraint league_seasons_dates check (ends_on > starts_on)
);

create table if not exists public.league_members (
  season_id uuid not null references public.league_seasons on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  -- Baseline snapshot taken when they join; everything is measured against it.
  start_weight_kg numeric(5,2),
  start_waist_cm numeric(5,1),
  start_e1rm numeric(7,2),
  joined_at timestamptz not null default now(),
  primary key (season_id, user_id)
);

create table if not exists public.league_scores (
  season_id uuid not null references public.league_seasons on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  week_index int not null check (week_index >= 0),
  consistency_pts int not null default 0,
  transformation_pts int not null default 0,
  sessions int not null default 0,
  goal_progress_pct numeric(5,2),
  computed_at timestamptz not null default now(),
  primary key (season_id, user_id, week_index)
);

create table if not exists public.challenges (
  id uuid primary key default gen_random_uuid(),
  season_id uuid references public.league_seasons on delete cascade,
  creator_id uuid not null references auth.users on delete cascade,
  kind text not null check (kind in ('crew','head_to_head','personal')),
  metric text not null check (metric in (
    'sessions','sets','waist_pct','weight_pct','protein_days','streak'
  )),
  title text not null,
  target numeric,
  stakes text,
  starts_on date not null,
  ends_on date not null,
  status text not null default 'pending'
    check (status in ('pending','live','finished','declined')),
  created_at timestamptz not null default now()
);

create table if not exists public.challenge_participants (
  challenge_id uuid not null references public.challenges on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  accepted boolean not null default false,
  progress numeric not null default 0,
  primary key (challenge_id, user_id)
);

create table if not exists public.badges (
  user_id uuid not null references auth.users on delete cascade,
  season_id uuid references public.league_seasons on delete cascade,
  slug text not null,
  earned_at timestamptz not null default now(),
  primary key (user_id, season_id, slug)
);

-- ---------------------------------------------------------------- predicates
--
-- Membership tests live in SECURITY DEFINER functions, not inline in the
-- policies. A policy on league_members that selects from league_members
-- recurses (Postgres 42P17), as does any pair of policies that read each
-- other's tables. Running the lookup as the owner sidesteps RLS re-entry.
-- Each function reads auth.uid() itself rather than taking it as an argument,
-- so it can only ever answer about the caller.

create or replace function public.is_league_member(target_season uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1 from public.league_members m
    where m.season_id = target_season and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_challenge_participant(target_challenge uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1 from public.challenge_participants cp
    where cp.challenge_id = target_challenge and cp.user_id = auth.uid()
  );
$$;

create or replace function public.is_challenge_creator(target_challenge uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1 from public.challenges c
    where c.id = target_challenge and c.creator_id = auth.uid()
  );
$$;

revoke all on function public.is_league_member(uuid) from public;
revoke all on function public.is_challenge_participant(uuid) from public;
revoke all on function public.is_challenge_creator(uuid) from public;
grant execute on function public.is_league_member(uuid) to authenticated;
grant execute on function public.is_challenge_participant(uuid) to authenticated;
grant execute on function public.is_challenge_creator(uuid) to authenticated;

-- ----------------------------------------------------------------- policies

alter table public.league_seasons enable row level security;
alter table public.league_members enable row level security;
alter table public.league_scores enable row level security;
alter table public.challenges enable row level security;
alter table public.challenge_participants enable row level security;
alter table public.badges enable row level security;

-- Readable by anyone in the season; writable only by the person who made it.
drop policy if exists "league_seasons: members read" on public.league_seasons;
create policy "league_seasons: members read"
  on public.league_seasons for select
  using (
    crew_owner_id = (select auth.uid())
    or public.is_league_member(id)
  );

drop policy if exists "league_seasons: owner writes" on public.league_seasons;
create policy "league_seasons: owner writes"
  on public.league_seasons for all
  using (crew_owner_id = (select auth.uid()))
  with check (crew_owner_id = (select auth.uid()));

-- A member can see who else is in their season, but the baselines are only
-- ever read by the scoring job, never surfaced to another member.
drop policy if exists "league_members: co-members read" on public.league_members;
create policy "league_members: co-members read"
  on public.league_members for select
  using (
    user_id = (select auth.uid())
    or public.is_league_member(season_id)
  );

drop policy if exists "league_members: manage own" on public.league_members;
create policy "league_members: manage own"
  on public.league_members for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists "league_scores: co-members read" on public.league_scores;
create policy "league_scores: co-members read"
  on public.league_scores for select
  using (public.is_league_member(season_id));

-- A personal challenge is visible only to its creator, whatever the season.
drop policy if exists "challenges: participants read" on public.challenges;
create policy "challenges: participants read"
  on public.challenges for select
  using (
    creator_id = (select auth.uid())
    or (kind <> 'personal' and public.is_challenge_participant(id))
  );

drop policy if exists "challenges: creator writes" on public.challenges;
create policy "challenges: creator writes"
  on public.challenges for all
  using (creator_id = (select auth.uid()))
  with check (creator_id = (select auth.uid()));

drop policy if exists "challenge_participants: read own challenges" on public.challenge_participants;
create policy "challenge_participants: read own challenges"
  on public.challenge_participants for select
  using (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  );

drop policy if exists "challenge_participants: manage own" on public.challenge_participants;
create policy "challenge_participants: manage own"
  on public.challenge_participants for all
  using (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  )
  with check (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  );

drop policy if exists "badges: co-members read" on public.badges;
create policy "badges: co-members read"
  on public.badges for select
  using (
    user_id = (select auth.uid())
    or public.is_league_member(season_id)
  );


-- ========================================================================
-- 20260905000011_league_functions.sql
-- ========================================================================

-- JLIKA Gym — league standings and the nightly scoring job.
--
-- The scoring rules live twice on purpose: in lib/league.ts, where they are
-- unit-tested and drive the UI, and here in SQL, where the nightly job runs
-- them across every member without a round trip. The constants below must be
-- kept in step with lib/league.ts.

/**
 * Standings for a season, computed from league_scores.
 *
 * SECURITY DEFINER so it can read every member's scores, but it returns only
 * names, points and percentages — no kilograms, centimetres or set data.
 */
create or replace function public.league_standings(target_season uuid)
returns table (
  user_id uuid,
  display_name text,
  avatar_url text,
  consistency_pts int,
  transformation_pts int,
  sessions int,
  goal_progress_pct numeric,
  week_dots int[]
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  week_start date := (date_trunc('week', now() at time zone 'utc'))::date;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  -- Only members of the season may read its standings.
  if not exists (
    select 1 from public.league_members m
    where m.season_id = target_season and m.user_id = caller
  ) then
    raise exception 'You are not in that season';
  end if;

  return query
  with totals as (
    select s.user_id,
           coalesce(sum(s.consistency_pts), 0)::int as consistency_pts,
           coalesce(sum(s.transformation_pts), 0)::int as transformation_pts,
           coalesce(sum(s.sessions), 0)::int as sessions
    from public.league_scores s
    where s.season_id = target_season
    group by s.user_id
  ),
  latest_pct as (
    select distinct on (s.user_id) s.user_id, s.goal_progress_pct
    from public.league_scores s
    where s.season_id = target_season
    order by s.user_id, s.week_index desc
  ),
  dots as (
    select ws.user_id,
           array_agg(distinct extract(isodow from ws.started_at)::int - 1) as days
    from public.workout_sessions ws
    join public.league_members m
      on m.user_id = ws.user_id and m.season_id = target_season
    where ws.ended_at is not null and ws.started_at >= week_start
    group by ws.user_id
  )
  select
    m.user_id,
    p.display_name,
    p.avatar_url,
    coalesce(t.consistency_pts, 0),
    coalesce(t.transformation_pts, 0),
    coalesce(t.sessions, 0),
    lp.goal_progress_pct,
    coalesce(d.days, '{}'::int[])
  from public.league_members m
  join public.profiles p on p.id = m.user_id
  left join totals t on t.user_id = m.user_id
  left join latest_pct lp on lp.user_id = m.user_id
  left join dots d on d.user_id = m.user_id
  where m.season_id = target_season
  order by
    coalesce(t.consistency_pts, 0) + coalesce(t.transformation_pts, 0) desc,
    p.display_name;
end;
$$;

revoke all on function public.league_standings(uuid) from public;
grant execute on function public.league_standings(uuid) to authenticated;

/**
 * Recomputes league_scores for every member of every live season.
 *
 * Mirrors lib/league.ts: 120 per session capped at five a week, 10 per
 * completed set, goal-relative bodyweight change × 200, waist centimetres lost
 * × 40, and 150 for holding the top-three estimated 1RM average. Bodyweight and
 * waist are read as 7-day averages, never a single reading.
 */
create or replace function public.recompute_league_scores()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  season record;
  member record;
  week_idx int;
  week_from date;
  week_to date;
  sessions_count int;
  sets_count int;
  consistency int;
  avg_weight numeric;
  avg_waist numeric;
  member_goal text;
  progress numeric;
  waist_lost numeric;
  current_e1rm numeric;
  transformation int;
begin
  for season in
    select * from public.league_seasons where starts_on <= current_date
  loop
    for member in
      select m.*, p.goal
      from public.league_members m
      join public.profiles p on p.id = m.user_id
      where m.season_id = season.id
    loop
      member_goal := member.goal;
      week_idx := 0;
      week_from := season.starts_on;

      while week_from <= least(current_date, season.ends_on) loop
        week_to := week_from + 7;

        select count(*)::int into sessions_count
        from public.workout_sessions ws
        where ws.user_id = member.user_id
          and ws.ended_at is not null
          and ws.started_at >= week_from
          and ws.started_at < week_to;

        select count(*)::int into sets_count
        from public.set_logs sl
        join public.workout_sessions ws on ws.id = sl.session_id
        where ws.user_id = member.user_id
          and sl.is_complete
          and ws.started_at >= week_from
          and ws.started_at < week_to;

        consistency := least(sessions_count, 5) * 120 + sets_count * 10;

        -- Seven-day averages up to the end of this week.
        select avg(bm.weight_kg), avg(bm.waist_cm)
        into avg_weight, avg_waist
        from public.body_metrics bm
        where bm.user_id = member.user_id
          and bm.measured_on < week_to
          and bm.measured_on >= week_to - 7;

        progress := 0;
        if member.start_weight_kg is not null and avg_weight is not null then
          progress := case member_goal
            when 'cut' then (member.start_weight_kg - avg_weight) / member.start_weight_kg * 100
            when 'bulk' then (avg_weight - member.start_weight_kg) / member.start_weight_kg * 100
            when 'recomp' then
              case when abs((avg_weight - member.start_weight_kg) / member.start_weight_kg * 100) < 0.5
                then 0.5
                else -abs((avg_weight - member.start_weight_kg) / member.start_weight_kg * 100)
              end
            else 0
          end;
        elsif member_goal = 'recomp' then
          progress := 0.5;
        end if;

        waist_lost := 0;
        if member.start_waist_cm is not null and avg_waist is not null then
          waist_lost := greatest(0, member.start_waist_cm - avg_waist);
        end if;

        -- Mean Epley estimate of the three heaviest movements this week.
        select avg(best) into current_e1rm
        from (
          select max(sl.weight_kg * (1 + sl.reps / 30.0)) as best
          from public.set_logs sl
          join public.workout_sessions ws on ws.id = sl.session_id
          where ws.user_id = member.user_id
            and sl.is_complete
            and sl.weight_kg is not null and sl.reps is not null
            and ws.started_at >= week_from and ws.started_at < week_to
          group by sl.exercise_id
          order by best desc
          limit 3
        ) top3;

        transformation := greatest(0, round(
          progress * 200
          + waist_lost * 40
          + case
              when member.start_e1rm is not null
                and current_e1rm is not null
                and current_e1rm >= member.start_e1rm
              then 150 else 0
            end
        ))::int;

        insert into public.league_scores (
          season_id, user_id, week_index,
          consistency_pts, transformation_pts, sessions, goal_progress_pct, computed_at
        )
        values (
          season.id, member.user_id, week_idx,
          consistency, transformation, sessions_count, round(progress, 2), now()
        )
        on conflict (season_id, user_id, week_index) do update set
          consistency_pts = excluded.consistency_pts,
          transformation_pts = excluded.transformation_pts,
          sessions = excluded.sessions,
          goal_progress_pct = excluded.goal_progress_pct,
          computed_at = now();

        week_idx := week_idx + 1;
        week_from := week_to;
      end loop;

      -- Badges awarded by the same pass.
      insert into public.badges (user_id, season_id, slug)
      select member.user_id, season.id, 'iron_waist'
      where member.start_waist_cm is not null
        and exists (
          select 1 from public.body_metrics bm
          where bm.user_id = member.user_id
            and bm.waist_cm is not null
            and member.start_waist_cm - bm.waist_cm >= 5
        )
      on conflict do nothing;

      insert into public.badges (user_id, season_id, slug)
      select member.user_id, season.id, 'volume_king'
      where exists (
        select 1
        from public.set_logs sl
        join public.workout_sessions ws on ws.id = sl.session_id
        where ws.user_id = member.user_id and sl.is_complete
        group by date_trunc('week', ws.started_at)
        having sum(sl.weight_kg * sl.reps) >= 50000
      )
      on conflict do nothing;
    end loop;
  end loop;
end;
$$;

revoke all on function public.recompute_league_scores() from public;

-- Nightly at 03:15 UTC. pg_cron may need enabling once in the dashboard:
--   Database → Extensions → pg_cron.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.unschedule('jlika-league-nightly')
    where exists (select 1 from cron.job where jobname = 'jlika-league-nightly');
    perform cron.schedule(
      'jlika-league-nightly',
      '15 3 * * *',
      $cron$select public.recompute_league_scores();$cron$
    );
  else
    raise notice 'pg_cron is not available; call recompute_league_scores() from your own scheduler.';
  end if;
end
$$;


-- ========================================================================
-- 20260907000013_target_weight.sql
-- ========================================================================

-- JLIKA Gym — planned load on a program exercise.
--
-- Until now a week said "3 × 8-12" but not at what weight; the load lived only
-- in set_logs, after the fact. That is fine when you already know what you lift
-- and useless when you do not. This column lets "copy last week" carry the load
-- forward and step it up where last week earned it.
--
-- Null means "no planned load" — pasted weeks, templates and hand-built days
-- all start that way, and the session screen simply leaves the field empty.

alter table public.program_exercises
  add column if not exists target_weight_kg numeric(6,2)
    check (target_weight_kg is null or (target_weight_kg >= 0 and target_weight_kg <= 1000));

comment on column public.program_exercises.target_weight_kg is
  'Planned working load in kg. Null when none is planned. Logged sets in set_logs remain the record of what was actually lifted.';


-- ========================================================================
-- 20260907000014_ingredient_images.sql
