-- ========================================================================
-- 20260908000015_fix_rls_recursion.sql
-- ========================================================================

-- JLIKA Gym — break two RLS recursion cycles (Postgres 42P17).
--
-- "league_members: co-members read" selected from league_members, so evaluating
-- it required evaluating itself. "challenges: participants read" and
-- "challenge_participants: read own challenges" each read the other's table,
-- which is the same fault one step removed. Both made the league page fail
-- outright with infinite_recursion.
--
-- The fix is the standard one: move the membership test into a SECURITY DEFINER
-- function. It runs as the owner, so the lookup inside it does not re-enter RLS,
-- and the policy becomes a plain boolean call. Each function still answers only
-- about the caller — auth.uid() is read inside, never passed in — so this widens
-- nothing.

create or replace function public.is_league_member(target_season uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.league_members m
    where m.season_id = target_season
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_challenge_participant(target_challenge uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.challenge_participants cp
    where cp.challenge_id = target_challenge
      and cp.user_id = auth.uid()
  );
$$;

create or replace function public.is_challenge_creator(target_challenge uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.challenges c
    where c.id = target_challenge
      and c.creator_id = auth.uid()
  );
$$;

revoke all on function public.is_league_member(uuid) from public;
revoke all on function public.is_challenge_participant(uuid) from public;
revoke all on function public.is_challenge_creator(uuid) from public;
grant execute on function public.is_league_member(uuid) to authenticated;
grant execute on function public.is_challenge_participant(uuid) to authenticated;
grant execute on function public.is_challenge_creator(uuid) to authenticated;

-- ----------------------------------------------------------------- rewrites

drop policy if exists "league_members: co-members read" on public.league_members;
create policy "league_members: co-members read"
  on public.league_members for select
  using (
    user_id = (select auth.uid())
    or public.is_league_member(season_id)
  );

drop policy if exists "league_scores: co-members read" on public.league_scores;
create policy "league_scores: co-members read"
  on public.league_scores for select
  using (public.is_league_member(season_id));

drop policy if exists "league_seasons: members read" on public.league_seasons;
create policy "league_seasons: members read"
  on public.league_seasons for select
  using (
    crew_owner_id = (select auth.uid())
    or public.is_league_member(id)
  );

drop policy if exists "badges: co-members read" on public.badges;
create policy "badges: co-members read"
  on public.badges for select
  using (
    user_id = (select auth.uid())
    or public.is_league_member(season_id)
  );

drop policy if exists "challenges: participants read" on public.challenges;
create policy "challenges: participants read"
  on public.challenges for select
  using (
    creator_id = (select auth.uid())
    -- A personal challenge stays private to its creator, whatever the season.
    or (kind <> 'personal' and public.is_challenge_participant(id))
  );

drop policy if exists "challenge_participants: read own challenges" on public.challenge_participants;
create policy "challenge_participants: read own challenges"
  on public.challenge_participants for select
  using (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  );

drop policy if exists "challenge_participants: manage own" on public.challenge_participants;
create policy "challenge_participants: manage own"
  on public.challenge_participants for all
  using (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  )
  with check (
    user_id = (select auth.uid())
    or public.is_challenge_creator(challenge_id)
  );


-- ========================================================================
-- 20260909000016_coaching.sql
-- ========================================================================

-- JLIKA Gym — coaching.
--
-- The app's premise is that every row belongs to one person and nobody else can
-- read it. A coach is the first deliberate exception, so it is built to be
-- narrow, athlete-controlled and revocable:
--
--   * The athlete opts in per category. Training is on by default; bodyweight,
--     photos and nutrition are off until the athlete turns them on.
--   * Access is checked in one SECURITY DEFINER function, so there is exactly
--     one place that decides what a coach may see.
--   * Ending the link revokes everything immediately — nothing is copied to the
--     coach's side except programs the coach wrote themselves.

alter table public.profiles
  add column if not exists coaching_enabled boolean not null default false;

comment on column public.profiles.coaching_enabled is
  'True when this account also acts as a coach. Coaching is a capability on a normal account, not a separate kind of user.';

-- ------------------------------------------------------------------- links

create table if not exists public.coach_invites (
  code text primary key,
  coach_id uuid not null references auth.users on delete cascade,
  label text,
  uses_left int not null default 10 check (uses_left >= 0),
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index if not exists coach_invites_coach_idx on public.coach_invites (coach_id);

create table if not exists public.coach_links (
  coach_id uuid not null references auth.users on delete cascade,
  athlete_id uuid not null references auth.users on delete cascade,
  status text not null default 'active' check (status in ('active','paused','ended')),
  -- Athlete-controlled. Training on, everything else off until they say so.
  share_training boolean not null default true,
  share_body_metrics boolean not null default false,
  share_photos boolean not null default false,
  share_nutrition boolean not null default false,
  created_at timestamptz not null default now(),
  primary key (coach_id, athlete_id),
  constraint coach_links_no_self check (coach_id <> athlete_id)
);

create index if not exists coach_links_athlete_idx on public.coach_links (athlete_id);

-- ------------------------------------------------------------ coach programs

create table if not exists public.coach_programs (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references auth.users on delete cascade,
  name text not null,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.coach_program_days (
  id uuid primary key default gen_random_uuid(),
  program_id uuid not null references public.coach_programs on delete cascade,
  day_index int not null check (day_index between 0 and 6),
  name text not null,
  focus_note text,
  is_rest boolean not null default false,
  unique (program_id, day_index)
);

create table if not exists public.coach_program_exercises (
  id uuid primary key default gen_random_uuid(),
  day_id uuid not null references public.coach_program_days on delete cascade,
  exercise_id uuid not null references public.exercises,
  position int not null,
  target_sets int not null check (target_sets between 1 and 20),
  rep_min int, rep_max int,
  per_side boolean not null default false,
  note text,
  target_weight_kg numeric(6,2)
);

create index if not exists coach_program_exercises_day_idx
  on public.coach_program_exercises (day_id, position);

-- A week the athlete did not write themselves is marked, so the program screen
-- can say where it came from instead of pretending they wrote it.
alter table public.program_weeks
  add column if not exists assigned_by_coach_id uuid references auth.users on delete set null;

-- --------------------------------------------------------------- predicates

/**
 * The single place that decides what a coach may read.
 *
 * SECURITY DEFINER so the lookup does not re-enter RLS (see the league
 * migration for what that costs). auth.uid() is read inside, so it can only
 * ever answer "may *I* read this athlete's <scope>".
 */
create or replace function public.coach_can_read(athlete uuid, scope text)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.coach_links cl
    where cl.coach_id = auth.uid()
      and cl.athlete_id = athlete
      and cl.status = 'active'
      and case scope
        when 'training'  then cl.share_training
        when 'body'      then cl.share_body_metrics
        when 'photos'    then cl.share_photos
        when 'nutrition' then cl.share_nutrition
        else false
      end
  );
$$;

revoke all on function public.coach_can_read(uuid, text) from public;
grant execute on function public.coach_can_read(uuid, text) to authenticated;

/** Owner of a program week, for the child-table policies. */
create or replace function public.program_week_owner(week uuid)
returns uuid
language sql
security definer
stable
set search_path = ''
as $$
  select w.user_id from public.program_weeks w where w.id = week;
$$;

create or replace function public.program_day_owner(day uuid)
returns uuid
language sql
security definer
stable
set search_path = ''
as $$
  select w.user_id
  from public.program_days d
  join public.program_weeks w on w.id = d.week_id
  where d.id = day;
$$;

create or replace function public.session_owner(session uuid)
returns uuid
language sql
security definer
stable
set search_path = ''
as $$
  select s.user_id from public.workout_sessions s where s.id = session;
$$;

revoke all on function public.program_week_owner(uuid) from public;
revoke all on function public.program_day_owner(uuid) from public;
revoke all on function public.session_owner(uuid) from public;
grant execute on function public.program_week_owner(uuid) to authenticated;
grant execute on function public.program_day_owner(uuid) to authenticated;
grant execute on function public.session_owner(uuid) to authenticated;

-- ------------------------------------------------------------------ policies

alter table public.coach_invites enable row level security;
alter table public.coach_links enable row level security;
alter table public.coach_programs enable row level security;
alter table public.coach_program_days enable row level security;
alter table public.coach_program_exercises enable row level security;

drop policy if exists "coach_invites: own rows" on public.coach_invites;
create policy "coach_invites: own rows"
  on public.coach_invites for all
  using (coach_id = (select auth.uid()))
  with check (coach_id = (select auth.uid()));

-- Both sides can see the link. Only the athlete may change what it shares;
-- either side may end it.
drop policy if exists "coach_links: both sides read" on public.coach_links;
create policy "coach_links: both sides read"
  on public.coach_links for select
  using (coach_id = (select auth.uid()) or athlete_id = (select auth.uid()));

drop policy if exists "coach_links: athlete controls" on public.coach_links;
create policy "coach_links: athlete controls"
  on public.coach_links for update
  using (athlete_id = (select auth.uid()))
  with check (athlete_id = (select auth.uid()));

drop policy if exists "coach_links: either side ends it" on public.coach_links;
create policy "coach_links: either side ends it"
  on public.coach_links for delete
  using (coach_id = (select auth.uid()) or athlete_id = (select auth.uid()));

drop policy if exists "coach_programs: own rows" on public.coach_programs;
create policy "coach_programs: own rows"
  on public.coach_programs for all
  using (coach_id = (select auth.uid()))
  with check (coach_id = (select auth.uid()));

drop policy if exists "coach_program_days: through program" on public.coach_program_days;
create policy "coach_program_days: through program"
  on public.coach_program_days for all
  using (exists (
    select 1 from public.coach_programs p
    where p.id = program_id and p.coach_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.coach_programs p
    where p.id = program_id and p.coach_id = (select auth.uid())
  ));

drop policy if exists "coach_program_exercises: through day" on public.coach_program_exercises;
create policy "coach_program_exercises: through day"
  on public.coach_program_exercises for all
  using (exists (
    select 1 from public.coach_program_days d
    join public.coach_programs p on p.id = d.program_id
    where d.id = day_id and p.coach_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.coach_program_days d
    join public.coach_programs p on p.id = d.program_id
    where d.id = day_id and p.coach_id = (select auth.uid())
  ));

-- ------------------------------------------- coach read access to athletes

drop policy if exists "program_weeks: coach reads" on public.program_weeks;
create policy "program_weeks: coach reads"
  on public.program_weeks for select
  using (public.coach_can_read(user_id, 'training'));

drop policy if exists "program_days: coach reads" on public.program_days;
create policy "program_days: coach reads"
  on public.program_days for select
  using (public.coach_can_read(public.program_week_owner(week_id), 'training'));

drop policy if exists "program_exercises: coach reads" on public.program_exercises;
create policy "program_exercises: coach reads"
  on public.program_exercises for select
  using (public.coach_can_read(public.program_day_owner(day_id), 'training'));

drop policy if exists "workout_sessions: coach reads" on public.workout_sessions;
create policy "workout_sessions: coach reads"
  on public.workout_sessions for select
  using (public.coach_can_read(user_id, 'training'));

drop policy if exists "set_logs: coach reads" on public.set_logs;
create policy "set_logs: coach reads"
  on public.set_logs for select
  using (public.coach_can_read(public.session_owner(session_id), 'training'));

drop policy if exists "body_metrics: coach reads" on public.body_metrics;
create policy "body_metrics: coach reads"
  on public.body_metrics for select
  using (public.coach_can_read(user_id, 'body'));

drop policy if exists "progress_photos: coach reads" on public.progress_photos;
create policy "progress_photos: coach reads"
  on public.progress_photos for select
  using (public.coach_can_read(user_id, 'photos'));

-- A coach may write a week for an athlete they coach — that is the point.
drop policy if exists "program_weeks: coach assigns" on public.program_weeks;
create policy "program_weeks: coach assigns"
  on public.program_weeks for insert
  with check (public.coach_can_read(user_id, 'training'));

drop policy if exists "program_days: coach assigns" on public.program_days;
create policy "program_days: coach assigns"
  on public.program_days for insert
  with check (public.coach_can_read(public.program_week_owner(week_id), 'training'));

drop policy if exists "program_exercises: coach assigns" on public.program_exercises;
create policy "program_exercises: coach assigns"
  on public.program_exercises for insert
  with check (public.coach_can_read(public.program_day_owner(day_id), 'training'));

-- Signed URLs are minted with the caller's own token, so a coach needs storage
-- read on the athlete's folder for shared photos to resolve at all.
drop policy if exists "coaches read shared progress photos" on storage.objects;
create policy "coaches read shared progress photos"
  on storage.objects for select
  using (
    bucket_id = 'progress-photos'
    and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'
    and public.coach_can_read(((storage.foldername(name))[1])::uuid, 'photos')
  );


-- ========================================================================
-- 20260909000017_redeem_coach_invite.sql
-- ========================================================================

-- JLIKA Gym — redeeming a coach invite.
--
-- SECURITY DEFINER because the athlete cannot read coach_invites; the code is
-- the credential, so it must not be enumerable. The link is created with the
-- default sharing: training on, body/photos/nutrition off.

create or replace function public.redeem_coach_invite(invite_code text)
returns table (coach_id uuid, coach_name text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.coach_invites%rowtype;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  select * into invite
  from public.coach_invites
  where code = upper(trim(invite_code))
  for update;

  if not found then
    raise exception 'That coach code does not exist';
  end if;
  if invite.expires_at < now() then
    raise exception 'That coach code has expired';
  end if;
  if invite.uses_left <= 0 then
    raise exception 'That coach code has been used up';
  end if;
  if invite.coach_id = caller then
    raise exception 'You cannot coach yourself';
  end if;

  -- Re-joining an existing link must not silently re-widen what is shared, so
  -- an existing row is only reactivated, never reset to defaults.
  insert into public.coach_links (coach_id, athlete_id)
  values (invite.coach_id, caller)
  on conflict (coach_id, athlete_id) do update set status = 'active';

  update public.coach_invites
  set uses_left = uses_left - 1
  where code = invite.code;

  return query
  select p.id, p.display_name
  from public.profiles p
  where p.id = invite.coach_id;
end;
$$;

revoke all on function public.redeem_coach_invite(text) from public;
grant execute on function public.redeem_coach_invite(text) to authenticated;

/**
 * A coach's roster with the compliance numbers the dashboard needs.
 *
 * SECURITY DEFINER so it can read each athlete's sessions, but it returns only
 * counts — never loads, weights or anything the athlete did not share. Rows
 * appear only for links that are active and sharing training.
 */
create or replace function public.coach_roster()
returns table (
  athlete_id uuid,
  display_name text,
  avatar_url text,
  goal text,
  sessions_this_week int,
  planned_this_week int,
  sets_this_week int,
  last_session_at timestamptz,
  week_dots int[],
  shares_body boolean,
  shares_photos boolean,
  shares_nutrition boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  week_start date := (date_trunc('week', now() at time zone 'utc'))::date;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  return query
  select
    a.id,
    p.display_name,
    p.avatar_url,
    p.goal,
    coalesce(s.done, 0)::int,
    coalesce(pl.planned, 0)::int,
    coalesce(s.sets, 0)::int,
    s.last_at,
    coalesce(s.dots, '{}'::int[]),
    cl.share_body_metrics,
    cl.share_photos,
    cl.share_nutrition
  from public.coach_links cl
  join auth.users a on a.id = cl.athlete_id
  join public.profiles p on p.id = cl.athlete_id
  left join lateral (
    select
      count(distinct ws.id)::int as done,
      count(sl.id) filter (where sl.is_complete)::int as sets,
      max(ws.started_at) as last_at,
      array_agg(distinct extract(isodow from ws.started_at)::int - 1) as dots
    from public.workout_sessions ws
    left join public.set_logs sl on sl.session_id = ws.id
    where ws.user_id = cl.athlete_id
      and ws.ended_at is not null
      and ws.started_at >= week_start
  ) s on true
  left join lateral (
    select count(*)::int as planned
    from public.program_days d
    join public.program_weeks w on w.id = d.week_id
    where w.user_id = cl.athlete_id
      and w.week_start = week_start
      and not d.is_rest
      and exists (select 1 from public.program_exercises pe where pe.day_id = d.id)
  ) pl on true
  where cl.coach_id = caller
    and cl.status = 'active'
    and cl.share_training
  order by p.display_name;
end;
$$;

revoke all on function public.coach_roster() from public;
grant execute on function public.coach_roster() to authenticated;


-- ========================================================================
-- 20260909000018_coach_names.sql
-- ========================================================================

-- JLIKA Gym — names for the coaches an athlete is linked to.
--
-- profiles is readable only by its owner, so an athlete cannot join to their
-- coach's row to get a name. This returns the display name and avatar for
-- coaches the caller is actually linked to, and nothing else about them.

create or replace function public.coach_names(coach_ids uuid[])
returns table (coach_id uuid, display_name text, avatar_url text)
language sql
security definer
stable
set search_path = ''
as $$
  select p.id, p.display_name, p.avatar_url
  from public.profiles p
  where p.id = any(coach_ids)
    and exists (
      select 1 from public.coach_links cl
      where cl.coach_id = p.id and cl.athlete_id = auth.uid()
    );
$$;

revoke all on function public.coach_names(uuid[]) from public;
grant execute on function public.coach_names(uuid[]) to authenticated;


-- ========================================================================
-- 20260909000019_revoke_anon_execute.sql
-- ========================================================================

-- JLIKA Gym — take EXECUTE away from anon on every SECURITY DEFINER function.
--
-- Supabase sets default privileges that grant EXECUTE on new functions to anon
-- and authenticated. `revoke all ... from public` does not undo that, because
-- the grant to anon is explicit rather than inherited — so every helper written
-- so far was callable by anyone holding the publishable key, which ships in the
-- browser.
--
-- Nothing leaked: each function reads auth.uid() itself and returns false, zero
-- rows, or raises for an anonymous caller. But two were genuinely wrong:
--
--   * recompute_league_scores rewrites every score in every season. Callable by
--     anyone, it is a free way to hammer the database.
--   * the *_owner helpers map a resource id to its owner's user id with no
--     auth check at all.
--
-- New SECURITY DEFINER functions must revoke from anon explicitly. Revoking
-- from public is not enough.

do $$
declare fn record;
begin
  for fn in
    select p.oid::regprocedure as signature
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prosecdef
  loop
    execute format('revoke all on function %s from anon', fn.signature);
    execute format('revoke all on function %s from authenticated', fn.signature);
    execute format('revoke all on function %s from public', fn.signature);
  end loop;
end
$$;

-- Grant back only what the app calls from a signed-in session.
grant execute on function public.crew_overview() to authenticated;
grant execute on function public.redeem_crew_invite(text) to authenticated;
grant execute on function public.league_standings(uuid) to authenticated;
grant execute on function public.is_league_member(uuid) to authenticated;
grant execute on function public.is_challenge_participant(uuid) to authenticated;
grant execute on function public.is_challenge_creator(uuid) to authenticated;
grant execute on function public.coach_can_read(uuid, text) to authenticated;
grant execute on function public.program_week_owner(uuid) to authenticated;
grant execute on function public.program_day_owner(uuid) to authenticated;
grant execute on function public.session_owner(uuid) to authenticated;
grant execute on function public.redeem_coach_invite(text) to authenticated;
grant execute on function public.coach_roster() to authenticated;
grant execute on function public.coach_names(uuid[]) to authenticated;

-- Deliberately not granted to anyone:
--   recompute_league_scores — rewrites every score in every season; only the
--     nightly pg_cron job, which runs as the table owner, should call it.
--   handle_new_user — a trigger function; nothing should invoke it directly.


-- ========================================================================
-- 20260910000020_coach_signup.sql
-- ========================================================================

-- JLIKA Gym — the coach's front door.
--
-- Two things are needed for a coach to sign up as a coach rather than as an
-- athlete who later finds a switch:
--   1. somewhere to put the gym or team they coach under, and
--   2. a way for an invited athlete to see who is inviting them before they
--      hand over any training data.

alter table public.profiles
  add column if not exists gym_name text;

comment on column public.profiles.gym_name is
  'Optional gym or team a coach works under. Shown to athletes on the join screen.';

/**
 * What an athlete is shown before joining a coach.
 *
 * SECURITY DEFINER because coach_invites is deliberately unreadable — the code
 * is the credential. Granted to `authenticated` only, never `anon`: an
 * anonymous caller who could test codes would have an oracle for enumerating
 * valid ones, and the reply names a real person.
 *
 * `reason` is 'ok' when the code can be redeemed. Every other value returns no
 * coach identity at all, so an unusable code reveals nothing about who wrote it.
 */
create or replace function public.coach_invite_preview(invite_code text)
returns table (
  coach_id uuid,
  coach_name text,
  avatar_url text,
  gym_name text,
  reason text
)
language plpgsql
security definer
stable
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.coach_invites%rowtype;
  verdict text;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  select * into invite
  from public.coach_invites
  where code = upper(trim(invite_code));

  if not found then
    return query select null::uuid, null::text, null::text, null::text, 'unknown'::text;
    return;
  end if;

  verdict := case
    when invite.expires_at < now() then 'expired'
    when invite.uses_left <= 0 then 'used_up'
    when invite.coach_id = caller then 'self'
    when exists (
      select 1 from public.coach_links cl
      where cl.coach_id = invite.coach_id
        and cl.athlete_id = caller
        and cl.status = 'active'
    ) then 'already'
    else 'ok'
  end;

  -- Identity is only disclosed for a code that would actually work.
  if verdict not in ('ok', 'already') then
    return query select null::uuid, null::text, null::text, null::text, verdict;
    return;
  end if;

  return query
  select p.id, p.display_name, p.avatar_url, p.gym_name, verdict
  from public.profiles p
  where p.id = invite.coach_id;
end;
$$;

revoke all on function public.coach_invite_preview(text) from public;
revoke all on function public.coach_invite_preview(text) from anon;
grant execute on function public.coach_invite_preview(text) to authenticated;


-- ========================================================================
-- 20260910000021_fix_redeem_ambiguity.sql
-- ========================================================================

-- JLIKA Gym — redeem_coach_invite could never actually run.
--
-- The function declares OUT parameters (coach_id, coach_name) via RETURNS
-- TABLE, and plpgsql substitutes those names anywhere they appear bare. In
--
--     on conflict (coach_id, athlete_id) do update ...
--
-- `coach_id` therefore resolved to the OUT parameter as readily as to the
-- column, and Postgres refused the whole call with 42702, "column reference
-- coach_id is ambiguous". Every athlete trying to join a coach hit it.
--
-- Naming the constraint instead of inferring from columns removes the bare
-- reference, and keeps the returned column names the app already reads.

create or replace function public.redeem_coach_invite(invite_code text)
returns table (coach_id uuid, coach_name text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.coach_invites%rowtype;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  select * into invite
  from public.coach_invites
  where code = upper(trim(invite_code))
  for update;

  if not found then
    raise exception 'That coach code does not exist';
  end if;
  if invite.expires_at < now() then
    raise exception 'That coach code has expired';
  end if;
  if invite.uses_left <= 0 then
    raise exception 'That coach code has been used up';
  end if;
  if invite.coach_id = caller then
    raise exception 'You cannot coach yourself';
  end if;

  -- Re-joining an existing link must not silently re-widen what is shared, so
  -- an existing row is only reactivated, never reset to defaults.
  insert into public.coach_links (coach_id, athlete_id)
  values (invite.coach_id, caller)
  on conflict on constraint coach_links_pkey do update set status = 'active';

  update public.coach_invites
  set uses_left = uses_left - 1
  where code = invite.code;

  return query
  select p.id, p.display_name
  from public.profiles p
  where p.id = invite.coach_id;
end;
$$;

revoke all on function public.redeem_coach_invite(text) from public;
revoke all on function public.redeem_coach_invite(text) from anon;
grant execute on function public.redeem_coach_invite(text) to authenticated;


-- ========================================================================
-- 20260910000022_rejoin_resets_shares.sql
-- ========================================================================

-- JLIKA Gym — rejoining a coach you removed starts from the defaults.
--
-- Reactivating an ended link used to keep whatever was shared when it ended.
-- So an athlete who had opened up progress photos, then ended the coaching,
-- handed the photos straight back the moment they used a code again — without
-- being told. Joining is joining: an ended link returns at training-only.
--
-- A link that is merely active or paused keeps its settings, which is the
-- original point: redeeming a code twice must not turn share_training back on
-- for someone who deliberately switched it off.

create or replace function public.redeem_coach_invite(invite_code text)
returns table (coach_id uuid, coach_name text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  invite public.coach_invites%rowtype;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  select * into invite
  from public.coach_invites
  where code = upper(trim(invite_code))
  for update;

  if not found then
    raise exception 'That coach code does not exist';
  end if;
  if invite.expires_at < now() then
    raise exception 'That coach code has expired';
  end if;
  if invite.uses_left <= 0 then
    raise exception 'That coach code has been used up';
  end if;
  if invite.coach_id = caller then
    raise exception 'You cannot coach yourself';
  end if;

  -- The constraint is named rather than inferred from columns: a bare
  -- `coach_id` in an inference list collides with this function's OUT
  -- parameter of the same name and Postgres refuses the call (42702).
  insert into public.coach_links (coach_id, athlete_id)
  values (invite.coach_id, caller)
  on conflict on constraint coach_links_pkey do update
  set status = 'active',
      share_training = case
        when public.coach_links.status = 'ended' then true
        else public.coach_links.share_training end,
      share_body_metrics = case
        when public.coach_links.status = 'ended' then false
        else public.coach_links.share_body_metrics end,
      share_photos = case
        when public.coach_links.status = 'ended' then false
        else public.coach_links.share_photos end,
      share_nutrition = case
        when public.coach_links.status = 'ended' then false
        else public.coach_links.share_nutrition end;

  update public.coach_invites
  set uses_left = uses_left - 1
  where code = invite.code;

  return query
  select p.id, p.display_name
  from public.profiles p
  where p.id = invite.coach_id;
end;
$$;

revoke all on function public.redeem_coach_invite(text) from public;
revoke all on function public.redeem_coach_invite(text) from anon;
grant execute on function public.redeem_coach_invite(text) to authenticated;


-- ========================================================================
-- 20260910000023_fix_roster_ambiguity.sql
-- ========================================================================

-- JLIKA Gym — the coach dashboard could not load.
--
-- coach_roster declared a local variable `week_start`, and the query it builds
-- joins program_weeks, which has a column of that name. plpgsql substitutes
-- bare identifiers, so `w.week_start = week_start` was ambiguous and Postgres
-- refused the call with 42702 — for every coach, roster or no roster. The
-- dashboard rendered its error card instead.
--
-- Renaming the variable to something no table has fixes it. Nothing about the
-- returned shape changes.

create or replace function public.coach_roster()
returns table (
  athlete_id uuid,
  display_name text,
  avatar_url text,
  goal text,
  sessions_this_week int,
  planned_this_week int,
  sets_this_week int,
  last_session_at timestamptz,
  week_dots int[],
  shares_body boolean,
  shares_photos boolean,
  shares_nutrition boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := auth.uid();
  -- Deliberately not `week_start`: that is a program_weeks column, and a bare
  -- reference to it inside the query below cannot be resolved.
  monday date := (date_trunc('week', now() at time zone 'utc'))::date;
begin
  if caller is null then
    raise exception 'Not signed in';
  end if;

  return query
  select
    a.id,
    p.display_name,
    p.avatar_url,
    p.goal,
    coalesce(s.done, 0)::int,
    coalesce(pl.planned, 0)::int,
    coalesce(s.sets, 0)::int,
    s.last_at,
    coalesce(s.dots, '{}'::int[]),
    cl.share_body_metrics,
    cl.share_photos,
    cl.share_nutrition
  from public.coach_links cl
  join auth.users a on a.id = cl.athlete_id
  join public.profiles p on p.id = cl.athlete_id
  left join lateral (
    select
      count(distinct ws.id)::int as done,
      count(sl.id) filter (where sl.is_complete)::int as sets,
      max(ws.started_at) as last_at,
      array_agg(distinct extract(isodow from ws.started_at)::int - 1) as dots
    from public.workout_sessions ws
    left join public.set_logs sl on sl.session_id = ws.id
    where ws.user_id = cl.athlete_id
      and ws.ended_at is not null
      and ws.started_at >= monday
  ) s on true
  left join lateral (
    select count(*)::int as planned
    from public.program_days d
    join public.program_weeks w on w.id = d.week_id
    where w.user_id = cl.athlete_id
      and w.week_start = monday
      and not d.is_rest
      and exists (select 1 from public.program_exercises pe where pe.day_id = d.id)
  ) pl on true
  where cl.coach_id = caller
    and cl.status = 'active'
    and cl.share_training
  order by p.display_name;
end;
$$;

revoke all on function public.coach_roster() from public;
revoke all on function public.coach_roster() from anon;
grant execute on function public.coach_roster() to authenticated;


-- ========================================================================
-- 20260922000024_league_crew_visibility.sql
-- ========================================================================

-- JLIKA Gym — you could not invite anyone to a league, and a stranger could
-- walk into one.
--
-- Two halves of the same mistake. league_seasons was readable only by its
-- owner or by someone already a member, so a crew mate saw no seasons at all
-- and the "Join the season?" screen could never render for them — the only
-- people who could join were the ones already in. Meanwhile league_members
-- allowed any signed-in user to insert their own row into *any* season, so
-- anyone who learned a season's id could join it and read the standings:
-- every member's name, sessions and body-progress percentage.
--
-- A season belongs to a crew, so crew membership is what decides both.

/**
 * Is the caller in `other`'s crew?
 *
 * SECURITY DEFINER because it is called from policies on other tables, where
 * crew_links' own policy would not apply to the row being checked. Links are
 * written in both directions by redeem_crew_invite, so one direction is enough.
 */
create or replace function public.shares_crew_with(other uuid)
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.crew_links cl
    where cl.user_id = other
      and cl.friend_id = auth.uid()
  );
$$;

/**
 * The crew that owns a season.
 *
 * Needed by the league_members policy below, which cannot simply select from
 * league_seasons: that table's own policy calls is_league_member, which reads
 * league_members, which is the table being filtered — 42P17 recursion.
 */
create or replace function public.season_crew_owner(target_season uuid)
returns uuid
language sql
security definer
stable
set search_path = ''
as $$
  select crew_owner_id from public.league_seasons where id = target_season;
$$;

revoke all on function public.shares_crew_with(uuid) from public;
revoke all on function public.shares_crew_with(uuid) from anon;
grant execute on function public.shares_crew_with(uuid) to authenticated;
revoke all on function public.season_crew_owner(uuid) from public;
revoke all on function public.season_crew_owner(uuid) from anon;
grant execute on function public.season_crew_owner(uuid) to authenticated;

-- A crew mate can now see the season, which is what makes joining possible.
drop policy if exists "league_seasons: members read" on public.league_seasons;
drop policy if exists "league_seasons: crew and members read" on public.league_seasons;
create policy "league_seasons: crew and members read"
  on public.league_seasons for select
  using (
    crew_owner_id = (select auth.uid())
    or public.is_league_member(id)
    or public.shares_crew_with(crew_owner_id)
  );

-- Splitting the old FOR ALL policy: reading, leaving and updating your own row
-- stay as they were, but joining now has to pass the crew check.
drop policy if exists "league_members: manage own" on public.league_members;

drop policy if exists "league_members: join a crew season" on public.league_members;
create policy "league_members: join a crew season"
  on public.league_members for insert
  with check (
    user_id = (select auth.uid())
    and (
      public.season_crew_owner(season_id) = (select auth.uid())
      or public.shares_crew_with(public.season_crew_owner(season_id))
    )
  );

drop policy if exists "league_members: update own" on public.league_members;
create policy "league_members: update own"
  on public.league_members for update
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists "league_members: leave own" on public.league_members;
create policy "league_members: leave own"
  on public.league_members for delete
  using (user_id = (select auth.uid()));


-- ========================================================================
-- 20261008000025_week_starts_on.sql
-- ========================================================================

-- JLIKA Gym — the training week no longer has to start on a Monday.
--
-- Weeks were Monday→Sunday everywhere: `currentWeekStart()` snapped to Monday
-- and each day was labelled by its position in a fixed Mon..Sun array. Someone
-- whose split runs Saturday→Friday could not express that at all.
--
-- 0 = Sunday … 6 = Saturday, matching date-fns' weekStartsOn, so the value can
-- be handed straight to startOfWeek without translation.

alter table public.user_settings
  add column if not exists week_starts_on smallint not null default 1
  check (week_starts_on between 0 and 6);

comment on column public.user_settings.week_starts_on is
  'Which weekday a training week begins on. 0 = Sunday … 6 = Saturday (date-fns weekStartsOn). Existing rows keep Monday.';


-- ========================================================================
-- 20261008000026_swap_program_days.sql
-- ========================================================================

-- JLIKA Gym — moving a whole training day to a different slot in the week.
--
-- Swapping two days means swapping their `day_index`: the rows themselves stay
-- put, so their exercises, and any session already logged against them, travel
-- with the day. Swapping the *contents* instead would silently relabel history
-- — a session recorded against "Monday · Push" would end up reading as whatever
-- moved into that row.
--
-- The obstacle is unique (week_id, day_index). A full week occupies every index
-- from 0 to 6, and the CHECK forbids parking a row outside that range, so there
-- is nowhere to put the first row while the second is still holding its slot.
-- Making the constraint deferrable lets both updates land and be judged
-- together at commit. Nothing uses this constraint as an ON CONFLICT target, so
-- deferring it costs nothing elsewhere.

alter table public.program_days
  drop constraint if exists program_days_week_id_day_index_key;

alter table public.program_days
  add constraint program_days_week_id_day_index_key
  unique (week_id, day_index) deferrable initially immediate;

/**
 * Swaps two days of the same week.
 *
 * SECURITY INVOKER on purpose: the caller's own row-level security decides
 * whether they may touch these rows, so this cannot be used to reorder someone
 * else's program.
 */
create or replace function public.swap_program_days(day_a uuid, day_b uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  a public.program_days%rowtype;
  b public.program_days%rowtype;
begin
  if day_a = day_b then
    return;
  end if;

  select * into a from public.program_days where id = day_a;
  if not found then
    raise exception 'That day no longer exists';
  end if;

  select * into b from public.program_days where id = day_b;
  if not found then
    raise exception 'That day no longer exists';
  end if;

  if a.week_id <> b.week_id then
    raise exception 'Those days belong to different weeks';
  end if;

  set constraints public.program_days_week_id_day_index_key deferred;
  update public.program_days set day_index = b.day_index where id = a.id;
  update public.program_days set day_index = a.day_index where id = b.id;
end;
$$;

revoke all on function public.swap_program_days(uuid, uuid) from public;
revoke all on function public.swap_program_days(uuid, uuid) from anon;
grant execute on function public.swap_program_days(uuid, uuid) to authenticated;


-- ========================================================================
-- 20261020000027_workout_preferences.sql
-- ========================================================================

-- JLIKA Gym — preferences for the workout screen, and a goal weight.
--
-- keep_awake   Hold a screen wake lock while a session is open, so a phone does
--              not lock between sets. On by default: unlocking and finding your
--              place again after every set is the most annoying part of logging.
-- rest_sound   Beep (and vibrate, where the device can) when rest runs out.
-- effort_scale Which scale the effort column asks in. Stored values are always
--              RPE in set_logs.rpe; RIR is RPE read the other way (RIR = 10 − RPE),
--              so switching scale never rewrites a logged set. 'off' hides the
--              column. Defaults to 'rpe' because that column already exists.
--
-- goal_weight_kg draws a target line on the weight chart and colours each change
-- by whether it moved toward it. Null = no goal, and nothing is coloured.
--
-- body_figure picks the figure the muscle map is drawn on. It is a drawing
-- preference only and is not read for anything else.

alter table public.user_settings
  add column if not exists keep_awake boolean not null default true,
  add column if not exists rest_sound boolean not null default true,
  add column if not exists effort_scale text not null default 'rpe';

alter table public.user_settings
  drop constraint if exists user_settings_effort_scale_check;
alter table public.user_settings
  add constraint user_settings_effort_scale_check
  check (effort_scale in ('off', 'rpe', 'rir'));

alter table public.profiles
  add column if not exists goal_weight_kg numeric(5,2),
  add column if not exists body_figure text not null default 'male';

alter table public.profiles
  drop constraint if exists profiles_goal_weight_kg_check;
alter table public.profiles
  add constraint profiles_goal_weight_kg_check
  check (goal_weight_kg is null or (goal_weight_kg > 20 and goal_weight_kg < 400));

alter table public.profiles
  drop constraint if exists profiles_body_figure_check;
alter table public.profiles
  add constraint profiles_body_figure_check
  check (body_figure in ('male', 'female'));


-- ========================================================================
-- 20261020000028_tracking_supersets_progression.sql
-- ========================================================================

-- JLIKA Gym — how a movement is logged, supersets, and progression rules.
--
-- Until now every set was weight × reps. A plank has no reps, a treadmill has
-- neither, and logging either as "1 rep" made every number derived from it
-- (volume, PRs, the progression hint) quietly wrong. Each movement now says how
-- it is logged:
--
--   reps    weight × reps, as before
--   time    held for a duration (planks, hangs, carries); may carry a load
--   cardio  duration plus an optional distance
--
-- set_logs gains the two columns the new modes need. reps and weight_kg were
-- already nullable, so nothing about existing rows changes.

-- ------------------------------------------------------------- exercises

alter table public.exercises
  add column if not exists tracking text not null default 'reps';

alter table public.exercises
  drop constraint if exists exercises_tracking_check;
alter table public.exercises
  add constraint exercises_tracking_check
  check (tracking in ('reps', 'time', 'cardio'));

-- ------------------------------------------------------------- set logs

alter table public.set_logs
  add column if not exists duration_s int,
  add column if not exists distance_m numeric(9,1);

alter table public.set_logs
  drop constraint if exists set_logs_duration_s_check;
alter table public.set_logs
  add constraint set_logs_duration_s_check
  check (duration_s is null or (duration_s >= 0 and duration_s <= 86400));

alter table public.set_logs
  drop constraint if exists set_logs_distance_m_check;
alter table public.set_logs
  add constraint set_logs_distance_m_check
  check (distance_m is null or distance_m >= 0);

-- --------------------------------------------------- program: the plan side
--
-- superset_group  Exercises of one day that share a number are done back to
--                 back, with rest only after the last of them. Null = alone.
-- target_seconds  Hold time per set for a timed movement; session length for
--                 cardio. Ignored for reps movements.
-- progression     The rule that moves this exercise's load forward. Null means
--                 "whatever the day says", so a day can switch everything to
--                 linear while one accessory stays on double progression.
-- increment_kg    The step that rule adds. Null = the default for the movement
--                 (5 kg for big lower-body lifts, 2.5 kg for the rest).

alter table public.program_days
  add column if not exists progression text not null default 'double';

alter table public.program_days
  drop constraint if exists program_days_progression_check;
alter table public.program_days
  add constraint program_days_progression_check
  check (progression in ('off', 'double', 'linear', 'greyskull'));

alter table public.program_exercises
  add column if not exists superset_group smallint,
  add column if not exists target_seconds int,
  add column if not exists progression text,
  add column if not exists increment_kg numeric(5,2);

alter table public.program_exercises
  drop constraint if exists program_exercises_superset_group_check;
alter table public.program_exercises
  add constraint program_exercises_superset_group_check
  check (superset_group is null or superset_group between 1 and 9);

alter table public.program_exercises
  drop constraint if exists program_exercises_target_seconds_check;
alter table public.program_exercises
  add constraint program_exercises_target_seconds_check
  check (target_seconds is null or target_seconds between 1 and 14400);

alter table public.program_exercises
  drop constraint if exists program_exercises_progression_check;
alter table public.program_exercises
  add constraint program_exercises_progression_check
  check (progression is null or progression in ('off', 'double', 'linear', 'greyskull', 'time'));

alter table public.program_exercises
  drop constraint if exists program_exercises_increment_kg_check;
alter table public.program_exercises
  add constraint program_exercises_increment_kg_check
  check (increment_kg is null or (increment_kg > 0 and increment_kg <= 50));

-- ------------------------------------------------- how a session felt
--
-- One tap on the finish summary: 1 = too easy, 2 = about right, 3 = brutal.
-- The free-text half goes in workout_sessions.notes, which already exists.

alter table public.workout_sessions
  add column if not exists rating smallint;

alter table public.workout_sessions
  drop constraint if exists workout_sessions_rating_check;
alter table public.workout_sessions
  add constraint workout_sessions_rating_check
  check (rating is null or rating between 1 and 3);

-- ------------------------------------------- movements the new modes need
--
-- From free-exercise-db (public domain), like the rest of the library.

