-- ========================================================================
-- 20261020000029_push.sql
-- ========================================================================

-- JLIKA Gym — web push: rest-timer alerts and workout-day reminders.
--
-- push_subscriptions  One row per browser that agreed to notifications. The
--                     endpoint is the push service's address for that browser.
--                     It is unique because a browser holds one subscription per
--                     site, whoever happens to be signed in.
-- rest_alerts         The rest-timer alert a session is waiting on, at most one
--                     per person. The server sleeps until ends_at and sends only
--                     if the row still carries the token it wrote, so starting a
--                     new rest replaces the pending alert and skipping one
--                     deletes it. A row is gone the moment its alert is sent.
--
-- user_settings gains the reminder preferences. "18:00" and "today" only mean
-- something in the lifter's own time zone, so the browser's zone is saved when a
-- device subscribes and the hourly reminder job reads it.

-- ------------------------------------------------------ push subscriptions

create table if not exists public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  endpoint text not null unique
    check (endpoint like 'https://%' and char_length(endpoint) <= 2048),
  -- The two keys the browser hands over with its subscription. Payloads are
  -- encrypted to them, so the push service never sees what a notification says.
  p256dh text not null check (char_length(p256dh) <= 200),
  auth text not null check (char_length(auth) <= 100),
  user_agent text check (user_agent is null or char_length(user_agent) <= 300),
  created_at timestamptz not null default now()
);

create index if not exists push_subscriptions_user_idx
  on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;

drop policy if exists "push_subscriptions: own rows" on public.push_subscriptions;
create policy "push_subscriptions: own rows"
  on public.push_subscriptions for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

/**
 * Saves this browser's subscription for the signed-in account.
 *
 * A browser keeps its subscription across sign-outs, so on a shared phone the
 * same endpoint can arrive from a second account. RLS hides the first account's
 * row, and the unique endpoint would then reject the insert with nothing the
 * caller can do about it. This hands the endpoint to whoever is signed in now,
 * which is who should hear from that device. Knowing an endpoint means holding
 * the browser it belongs to, so this cannot be used to take over someone else's.
 */
create or replace function public.save_push_subscription(
  sub_endpoint text,
  sub_p256dh text,
  sub_auth text,
  sub_user_agent text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'Not signed in.';
  end if;

  delete from public.push_subscriptions
  where endpoint = sub_endpoint and user_id <> me;

  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
  values (me, sub_endpoint, sub_p256dh, sub_auth, left(sub_user_agent, 300))
  on conflict (endpoint) do update set
    p256dh = excluded.p256dh,
    auth = excluded.auth,
    user_agent = excluded.user_agent;
end;
$$;

revoke all on function public.save_push_subscription(text, text, text, text) from public;
revoke all on function public.save_push_subscription(text, text, text, text) from anon;
revoke all on function public.save_push_subscription(text, text, text, text) from authenticated;
grant execute on function public.save_push_subscription(text, text, text, text) to authenticated;

-- ------------------------------------------------------------ rest alerts

create table if not exists public.rest_alerts (
  user_id uuid primary key references auth.users on delete cascade,
  -- Rewritten on every schedule. The sleeping sender compares it before
  -- sending, which is what makes a replaced or cancelled alert stay silent.
  token uuid not null,
  -- Only the device that started the rest hears about it; a laptop left open
  -- at home should not beep because a set ended at the gym.
  endpoint text not null,
  -- Where tapping the notification lands: the session it came from.
  url text not null default '/' check (url like '/%' and char_length(url) <= 300),
  ends_at timestamptz not null,
  created_at timestamptz not null default now()
);

alter table public.rest_alerts enable row level security;

drop policy if exists "rest_alerts: own row" on public.rest_alerts;
create policy "rest_alerts: own row"
  on public.rest_alerts for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------- user settings
--
-- notify_workout_day  Push on a training day of the published week if no
--                     session has started by reminder_hour. Off by default: it
--                     only works once a device has subscribed anyway.
-- reminder_hour       Local hour, 0–23, the reminder goes out at.
-- timezone            IANA name from the browser (Intl), e.g. Europe/Paris.
-- rest_push           Push when rest runs out while the app is in the
--                     background. On by default; it does nothing until a
--                     device subscribes.

alter table public.user_settings
  add column if not exists notify_workout_day boolean not null default false,
  add column if not exists reminder_hour smallint not null default 18,
  add column if not exists timezone text not null default 'UTC',
  add column if not exists rest_push boolean not null default true;

alter table public.user_settings
  drop constraint if exists user_settings_reminder_hour_check;
alter table public.user_settings
  add constraint user_settings_reminder_hour_check
  check (reminder_hour between 0 and 23);

alter table public.user_settings
  drop constraint if exists user_settings_timezone_check;
alter table public.user_settings
  add constraint user_settings_timezone_check
  check (char_length(timezone) between 1 and 64);


-- ========================================================================
-- 20261020000031_ai_coach.sql
-- ========================================================================

-- JLIKA Gym — the AI Coach: an optional model that drafts a week and reviews
-- what you logged, with nothing changing until you approve it.
--
-- It exists only when the server has ANTHROPIC_API_KEY, and only for accounts
-- that opted in. Everything here is the paper trail that keeps that promise:
--
--   profiles.ai_coach_consented_at  When this account agreed to send its data.
--                                   Null = never, or withdrawn. The app checks it
--                                   before every request, not just on the page.
--   ai_coach_intakes                The answers the plan is designed from.
--   ai_coach_runs                   Every request to the model: what kind, which
--                                   model, tokens, and why it failed if it did.
--                                   Also what the daily cap counts.
--   ai_coach_proposals              What came back: a drafted week, or a review.
--   ai_coach_changes                A review's discrete changes, and what you
--                                   decided about each. Rejected ones go back
--                                   into the next review so they are not
--                                   proposed again without new evidence.
--   ai_coach_snapshots              The week exactly as it stood before an
--                                   apply, so Revert can put it back.
--
-- Reverting rewrites program_days and program_exercises only. workout_sessions
-- and set_logs are never touched: the log is what happened.

-- ------------------------------------------------------------------ consent

alter table public.profiles
  add column if not exists ai_coach_consented_at timestamptz;

comment on column public.profiles.ai_coach_consented_at is
  'When this account opted in to the AI Coach. Null = not opted in (or withdrawn); nothing is sent to the model provider.';

-- ------------------------------------------------------------------- intake

create table if not exists public.ai_coach_intakes (
  user_id uuid primary key references auth.users on delete cascade,
  -- Validated by the app (lib/ai-coach/schemas.ts) before it is written.
  answers jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.ai_coach_intakes enable row level security;

drop policy if exists "ai_coach_intakes: own rows" on public.ai_coach_intakes;
create policy "ai_coach_intakes: own rows"
  on public.ai_coach_intakes for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- --------------------------------------------------------------------- runs
--
-- Readable by their owner, writable only through the two functions below.
-- The daily cap counts these rows, so a direct insert/update/delete policy
-- would let anyone with the publishable key reset their own cap.

create table if not exists public.ai_coach_runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  kind text not null check (kind in ('plan', 'refine', 'review')),
  status text not null default 'running' check (status in ('running', 'succeeded', 'failed')),
  model text not null,
  input_tokens int check (input_tokens is null or input_tokens >= 0),
  output_tokens int check (output_tokens is null or output_tokens >= 0),
  cache_read_tokens int check (cache_read_tokens is null or cache_read_tokens >= 0),
  -- Shown to the account owner as-is, so it never carries a stack trace.
  error text,
  created_at timestamptz not null default now(),
  finished_at timestamptz
);

create index if not exists ai_coach_runs_user_created_idx
  on public.ai_coach_runs (user_id, created_at desc);

alter table public.ai_coach_runs enable row level security;

drop policy if exists "ai_coach_runs: read own" on public.ai_coach_runs;
create policy "ai_coach_runs: read own"
  on public.ai_coach_runs for select
  using (user_id = (select auth.uid()));

/**
 * Opens a run if the caller is under the cap, and returns its id.
 *
 * SECURITY DEFINER because runs have no insert policy (see above). It only
 * ever writes a row for auth.uid(). The cap comes from the server's
 * AI_COACH_DAILY_LIMIT; calling this directly with a bigger number gains
 * nothing, because only the server holds the key that makes a run cost money.
 *
 * Counts every run in the last 24 hours, failed ones included — a failure
 * may still have been billed. A per-user advisory lock makes the count and
 * the insert one step, so parallel requests cannot all slip under the cap.
 */
create or replace function public.ai_coach_start_run(p_kind text, p_model text, p_daily_limit int)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_used int;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Not signed in.';
  end if;
  if p_kind not in ('plan', 'refine', 'review') then
    raise exception 'Unknown run kind.';
  end if;
  if p_daily_limit is null or p_daily_limit < 1 then
    raise exception 'ai_coach_daily_limit';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ai_coach_runs:' || v_uid::text, 0));

  -- A run the server never finished (killed at its time limit, say) would sit
  -- at "running" forever. Close those out so the log tells the truth.
  update public.ai_coach_runs
     set status = 'failed',
         error = 'Stopped before it finished.',
         finished_at = now()
   where user_id = v_uid
     and status = 'running'
     and created_at < now() - interval '10 minutes';

  select count(*) into v_used
    from public.ai_coach_runs
   where user_id = v_uid
     and created_at > now() - interval '24 hours';

  if v_used >= p_daily_limit then
    raise exception 'ai_coach_daily_limit';
  end if;

  insert into public.ai_coach_runs (user_id, kind, model)
  values (v_uid, p_kind, left(coalesce(p_model, 'unknown'), 80))
  returning id into v_id;

  return v_id;
end;
$$;

/**
 * Closes one of the caller's own open runs. A closed run cannot be reopened or
 * rewritten, and nothing here changes what the cap counts.
 */
create or replace function public.ai_coach_finish_run(
  p_run uuid,
  p_status text,
  p_input_tokens int,
  p_output_tokens int,
  p_cache_read_tokens int,
  p_error text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in.';
  end if;
  if p_status not in ('succeeded', 'failed') then
    raise exception 'A run finishes as succeeded or failed.';
  end if;

  update public.ai_coach_runs
     set status = p_status,
         input_tokens = greatest(p_input_tokens, 0),
         output_tokens = greatest(p_output_tokens, 0),
         cache_read_tokens = greatest(p_cache_read_tokens, 0),
         error = left(p_error, 500),
         finished_at = now()
   where id = p_run
     and user_id = auth.uid()
     and status = 'running';
end;
$$;

-- README rule: Supabase's default privileges grant EXECUTE to anon and
-- authenticated; revoking from public does not undo that.
revoke all on function public.ai_coach_start_run(text, text, int) from public;
revoke all on function public.ai_coach_start_run(text, text, int) from anon;
revoke all on function public.ai_coach_start_run(text, text, int) from authenticated;
grant execute on function public.ai_coach_start_run(text, text, int) to authenticated;

revoke all on function public.ai_coach_finish_run(uuid, text, int, int, int, text) from public;
revoke all on function public.ai_coach_finish_run(uuid, text, int, int, int, text) from anon;
revoke all on function public.ai_coach_finish_run(uuid, text, int, int, int, text) from authenticated;
grant execute on function public.ai_coach_finish_run(uuid, text, int, int, int, text) to authenticated;

-- ---------------------------------------------------------------- proposals

create table if not exists public.ai_coach_proposals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  run_id uuid references public.ai_coach_runs on delete set null,
  kind text not null check (kind in ('plan', 'review')),
  status text not null default 'pending'
    check (status in ('pending', 'applied', 'dismissed', 'superseded', 'reverted')),
  summary text,
  -- plan: the validated week. review: the advice notes and the fingerprint of
  -- the week the changes were written against, to catch a plan edited since.
  payload jsonb not null,
  -- review: the week whose plan was read.
  base_week_start date,
  -- Where an accepted proposal was written.
  applied_week_start date,
  -- A refined plan points at the draft it replaced.
  parent_id uuid references public.ai_coach_proposals on delete set null,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);

create index if not exists ai_coach_proposals_user_created_idx
  on public.ai_coach_proposals (user_id, created_at desc);

alter table public.ai_coach_proposals enable row level security;

drop policy if exists "ai_coach_proposals: own rows" on public.ai_coach_proposals;
create policy "ai_coach_proposals: own rows"
  on public.ai_coach_proposals for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ------------------------------------------------------------------ changes

create table if not exists public.ai_coach_changes (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid not null references public.ai_coach_proposals on delete cascade,
  position smallint not null check (position >= 0),
  type text not null check (type in (
    'swap_exercise', 'add_exercise', 'remove_exercise',
    'set_sets', 'set_rep_range', 'set_target_seconds', 'set_load',
    'set_progression', 'set_superset', 'rename_day'
  )),
  -- The validated change, as the model proposed it.
  change jsonb not null,
  -- Rendered from the plan by the app, not taken from the model, so the
  -- before → after the person ticks is the one that gets applied.
  target_text text not null,
  before_text text not null,
  after_text text not null,
  rationale text not null,
  decision text not null default 'pending' check (decision in ('pending', 'accepted', 'rejected')),
  decided_at timestamptz,
  unique (proposal_id, position)
);

alter table public.ai_coach_changes enable row level security;

-- Ownership through the proposal, like program_days through program_weeks.
drop policy if exists "ai_coach_changes: through proposal" on public.ai_coach_changes;
create policy "ai_coach_changes: through proposal"
  on public.ai_coach_changes for all
  using (exists (
    select 1 from public.ai_coach_proposals p
    where p.id = proposal_id and p.user_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.ai_coach_proposals p
    where p.id = proposal_id and p.user_id = (select auth.uid())
  ));

-- ---------------------------------------------------------------- snapshots

create table if not exists public.ai_coach_snapshots (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  proposal_id uuid references public.ai_coach_proposals on delete set null,
  week_start date not null,
  -- {"week": null, "days": []} when there was no week yet; Revert then
  -- removes the one the apply created.
  snapshot jsonb not null,
  created_at timestamptz not null default now(),
  reverted_at timestamptz
);

create index if not exists ai_coach_snapshots_user_created_idx
  on public.ai_coach_snapshots (user_id, created_at desc);

alter table public.ai_coach_snapshots enable row level security;

drop policy if exists "ai_coach_snapshots: own rows" on public.ai_coach_snapshots;
create policy "ai_coach_snapshots: own rows"
  on public.ai_coach_snapshots for all
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));


-- ========================================================================
-- 20261020000032_exercise_library.sql
-- ========================================================================

-- JLIKA Gym — the full exercise library: featured movements and archiving.
--
-- featured     The hand-picked movements (0003's seed and 0028's timed and
--              cardio rows). 0033 adds the rest of free-exercise-db with
--              featured = false, and the builder, the paste matcher and the
--              AI Coach lead with the featured ones so ~700 extra rows do not
--              bury them. Only global rows can be featured.
--
-- archived_at  Set when someone removes one of their own movements that has
--              logged sets. It leaves the library and the pickers, but the row
--              stays, so history, summaries and charts still have its name.
--              A movement with no logs is deleted outright instead. Only your
--              own movements can be archived; the global ones are not yours to
--              remove.

-- Every global row at the moment the column appears is a curated one, so they
-- are marked featured then and only then. Re-running this file after 0033 must
-- not promote the long tail, which is why it is keyed on the column's absence
-- rather than on owner_id alone.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'exercises' and column_name = 'featured'
  ) then
    alter table public.exercises add column featured boolean not null default false;
    update public.exercises set featured = true where owner_id is null;
  end if;
end
$$;

alter table public.exercises
  drop constraint if exists exercises_featured_global_check;
alter table public.exercises
  add constraint exercises_featured_global_check
  check (not featured or owner_id is null);

alter table public.exercises
  add column if not exists archived_at timestamptz;

alter table public.exercises
  drop constraint if exists exercises_archived_own_check;
alter table public.exercises
  add constraint exercises_archived_own_check
  check (archived_at is null or owner_id is not null);


-- ========================================================================
-- 20261020000033_seed_full_library.sql
-- ========================================================================

-- JLIKA Gym — the rest of the exercise library.
--
-- GENERATED by `node scripts/generate-exercise-seed.mjs --full` from
-- free-exercise-db (https://github.com/yuhonas/free-exercise-db), public
-- domain like the curated seed. Do not edit by hand.
--
-- 675 movements, all featured = false: the Exercises page and search
-- reach them, while the builder, the paste matcher and the AI Coach lead with
-- the curated rows. Of the dataset's 876 entries:
--   78 are curated rows already (0003, 0028) and are left untouched;
--   123 are stretches, left out because nothing here logs a stretch;
--   unmappable onto our muscles or equipment: none.
-- Every dataset muscle is one of our 17, and an entry with no equipment is
-- bodyweight. 7 are logged as cardio (the dataset's cardio category)
-- and 12 as time (static holds, carries and sled work); the rest as reps.
--
-- Photos are hotlinked like the curated seed's, built from each entry's folder
-- to keep this file small. on conflict (slug) do nothing: a curated row, its
-- aliases and anyone's own movement are never overwritten, and re-running is
-- harmless.

insert into public.exercises
  (slug, name, primary_muscle, secondary_muscles, equipment, tracking,
   image_start_url, image_end_url, how_to, featured)
select
  v.slug, v.name, v.primary_muscle, v.secondary_muscles::text[], v.equipment, v.tracking,
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/' || v.photos || '/0.jpg',
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/' || v.photos || '/1.jpg',
  v.how_to, false
from (values
  ('3-4-sit-up', '3/4 Sit-Up', 'abdominals', '{}', 'body_only', 'reps', '3_4_Sit-Up', array['Lie down on the floor and secure your feet. Your legs should be bent at the knees.','Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.','Flex your hips and spine to raise your torso toward your knees.','At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.','Repeat for the recommended amount of repetitions.']::text[]),
  ('ab-crunch-machine', 'Ab Crunch Machine', 'abdominals', '{}', 'machine', 'reps', 'Ab_Crunch_Machine', array['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.','After a second pause, slowly return to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('advanced-kettlebell-windmill', 'Advanced Kettlebell Windmill', 'abdominals', '{glutes,hamstrings,shoulders}', 'kettlebells', 'reps', 'Advanced_Kettlebell_Windmill', array['Clean and press a kettlebell overhead with one arm.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.','Lower yourself as far as possible.','Pause for a second and reverse the motion back to the starting position.']::text[]),
  ('air-bike', 'Air Bike', 'abdominals', '{}', 'body_only', 'reps', 'Air_Bike', array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','Go back to the initial position as you breathe in.','Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[]),
  ('alternate-hammer-curl', 'Alternate Hammer Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Alternate_Hammer_Curl', array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
  ('alternate-heel-touchers', 'Alternate Heel Touchers', 'abdominals', '{}', 'body_only', 'reps', 'Alternate_Heel_Touchers', array['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','Now go back slowly to the starting position as you inhale.','Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','Continue alternating sides in this manner until all prescribed repetitions are done.']::text[]),
  ('alternate-incline-dumbbell-curl', 'Alternate Incline Dumbbell Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Alternate_Incline_Dumbbell_Curl', array['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
  ('alternate-leg-diagonal-bound', 'Alternate Leg Diagonal Bound', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'body_only', 'reps', 'Alternate_Leg_Diagonal_Bound', array['Assume a comfortable stance with one foot slightly in front of the other.','Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.','It may help to use a line on the ground to guage distance from side to side.','Repeat the sequence with the other leg.']::text[]),
  ('alternating-cable-shoulder-press', 'Alternating Cable Shoulder Press', 'shoulders', '{triceps}', 'cable', 'reps', 'Alternating_Cable_Shoulder_Press', array['Move the cables to the bottom of the tower and select an appropriate weight.','Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press one side directly over head.','After pausing at the top, return to the starting position and repeat on the opposite side.']::text[]),
  ('alternating-deltoid-raise', 'Alternating Deltoid Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Alternating_Deltoid_Raise', array['In a standing position, hold a pair of dumbbells at your side.','Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.','Return the weights to your side.','On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.','Return the weights to the starting position and continue alternating to the front and side.']::text[]),
  ('alternating-floor-press', 'Alternating Floor Press', 'chest', '{abdominals,shoulders,triceps}', 'kettlebells', 'reps', 'Alternating_Floor_Press', array['Lie on the floor with two kettlebells next to your shoulders.','Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.','Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.','Raise the kettlebell and repeat on the opposite side.']::text[]),
  ('alternating-hang-clean', 'Alternating Hang Clean', 'hamstrings', '{biceps,calves,forearms,glutes,lower_back,traps}', 'kettlebells', 'reps', 'Alternating_Hang_Clean', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.','Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[]),
  ('alternating-kettlebell-press', 'Alternating Kettlebell Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'Alternating_Kettlebell_Press', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.','Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .','Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[]),
  ('alternating-kettlebell-row', 'Alternating Kettlebell Row', 'middle_back', '{biceps,lats}', 'kettlebells', 'reps', 'Alternating_Kettlebell_Row', array['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.','Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.','Lower the kettlebell in the working arm and repeat with your other arm.']::text[]),
  ('alternating-renegade-row', 'Alternating Renegade Row', 'middle_back', '{abdominals,biceps,chest,lats,triceps}', 'kettlebells', 'reps', 'Alternating_Renegade_Row', array['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.','Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.','Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[]),
  ('anti-gravity-press', 'Anti-Gravity Press', 'shoulders', '{middle_back,traps,triceps}', 'barbell', 'reps', 'Anti-Gravity_Press', array['Place a bar on the ground behind the head of an incline bench.','Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.','To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.','Return to the starting position and repeat to complete the set.']::text[]),
  ('around-the-worlds', 'Around The Worlds', 'chest', '{shoulders}', 'dumbbell', 'reps', 'Around_The_Worlds', array['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.','Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.','Reverse the movement to return the weight to the starting position as you exhale.']::text[]),
  ('atlas-stone-trainer', 'Atlas Stone Trainer', 'lower_back', '{biceps,forearms,glutes,hamstrings,quadriceps}', 'other', 'reps', 'Atlas_Stone_Trainer', array['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.','Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.','Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.','Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[]),
  ('atlas-stones', 'Atlas Stones', 'lower_back', '{abdominals,adductors,biceps,calves,forearms,glutes,hamstrings,middle_back,quadriceps,traps}', 'other', 'reps', 'Atlas_Stones', array['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.','Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.','As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.','Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[]),
  ('axle-deadlift', 'Axle Deadlift', 'lower_back', '{forearms,glutes,hamstrings,middle_back,quadriceps,traps}', 'other', 'reps', 'Axle_Deadlift', array['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.','With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
  ('back-flyes-with-bands', 'Back Flyes - With Bands', 'shoulders', '{middle_back,triceps}', 'bands', 'reps', 'Back_Flyes_-_With_Bands', array['Run a band around a stationary post like that of a squat rack.','Grab the band by the handles and stand back so that the tension in the band rises.','Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.','As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.','After a pause, go back to the original position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('backward-drag', 'Backward Drag', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back}', 'other', 'time', 'Backward_Drag', array['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.','Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.']::text[]),
  ('backward-medicine-ball-throw', 'Backward Medicine Ball Throw', 'shoulders', '{}', 'medicine_ball', 'reps', 'Backward_Medicine_Ball_Throw', array['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.','Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.','Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.','Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.']::text[]),
  ('balance-board', 'Balance Board', 'calves', '{hamstrings,quadriceps}', 'other', 'reps', 'Balance_Board', array['Place a balance board in front of you.','Stand up on it and try to balance yourself.','Hold the balance for as long as desired.']::text[]),
  ('ball-leg-curl', 'Ball Leg Curl', 'hamstrings', '{calves,glutes}', 'exercise_ball', 'reps', 'Ball_Leg_Curl', array['Begin on the floor laying on your back with your feet on top of the ball.','Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.','Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.','Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.','After a brief pause, return to the starting position.']::text[]),
  ('band-assisted-pull-up', 'Band Assisted Pull-Up', 'lats', '{abdominals,forearms,middle_back}', 'other', 'reps', 'Band_Assisted_Pull-Up', array['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.','Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.','Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.','After a brief pause, return to the starting position.']::text[]),
  ('band-good-morning', 'Band Good Morning', 'hamstrings', '{glutes,lower_back}', 'bands', 'reps', 'Band_Good_Morning', array['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.','Keeping your legs straight, extend through the hips to come to a near vertical position.','Ensure that you do not round your back as you go down back to the starting position.']::text[]),
  ('band-good-morning-pull-through', 'Band Good Morning (Pull Through)', 'hamstrings', '{glutes,lower_back}', 'bands', 'reps', 'Band_Good_Morning_Pull_Through', array['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.','Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.','Return to the starting position be driving through with the hips to come back to a standing position.']::text[]),
  ('band-hip-adductions', 'Band Hip Adductions', 'adductors', '{}', 'bands', 'reps', 'Band_Hip_Adductions', array['Anchor a band around a solid post or other object.','Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.','Stand up straight and hold onto the post if needed. This will be your starting position.','Keeping the knee straight, raise your right legs out to the side as far as you can.','Return to the starting position and repeat for the desired rep count.','Switch sides.']::text[]),
  ('band-pull-apart', 'Band Pull Apart', 'shoulders', '{middle_back,traps}', 'bands', 'reps', 'Band_Pull_Apart', array['Begin with your arms extended straight out in front of you, holding the band with both hands.','Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.','Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.','Pause as you complete the movement, returning to the starting position under control.']::text[]),
  ('band-skull-crusher', 'Band Skull Crusher', 'triceps', '{}', 'bands', 'reps', 'Band_Skull_Crusher', array['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.','Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.','Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[]),
  ('barbell-ab-rollout', 'Barbell Ab Rollout', 'abdominals', '{lower_back,shoulders}', 'barbell', 'reps', 'Barbell_Ab_Rollout', array['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.','While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.','After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-ab-rollout-on-knees', 'Barbell Ab Rollout - On Knees', 'abdominals', '{lower_back,shoulders}', 'barbell', 'reps', 'Barbell_Ab_Rollout_-_On_Knees', array['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[]),
  ('barbell-curls-lying-against-an-incline', 'Barbell Curls Lying Against An Incline', 'biceps', '{}', 'barbell', 'reps', 'Barbell_Curls_Lying_Against_An_Incline', array['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.','While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.','After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-full-squat', 'Barbell Full Squat', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Barbell_Full_Squat', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.','Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.','Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-guillotine-bench-press', 'Barbell Guillotine Bench Press', 'chest', '{shoulders,triceps}', 'barbell', 'reps', 'Barbell_Guillotine_Bench_Press', array['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('barbell-hack-squat', 'Barbell Hack Squat', 'quadriceps', '{calves,forearms,hamstrings}', 'barbell', 'reps', 'Barbell_Hack_Squat', array['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.','Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'glutes', '{calves,hamstrings}', 'barbell', 'reps', 'Barbell_Hip_Thrust', array['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.','Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[]),
  ('barbell-incline-shoulder-raise', 'Barbell Incline Shoulder Raise', 'shoulders', '{chest}', 'barbell', 'reps', 'Barbell_Incline_Shoulder_Raise', array['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.','While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.','Bring back the bar to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-lunge', 'Barbell Lunge', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Barbell_Lunge', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>','Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[]),
  ('barbell-rollout-from-bench', 'Barbell Rollout from Bench', 'abdominals', '{glutes,hamstrings,lats,shoulders}', 'barbell', 'reps', 'Barbell_Rollout_from_Bench', array['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.','To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.','When the bar has been moved as far forward as possible, return to the starting position.']::text[]),
  ('barbell-seated-calf-raise', 'Barbell Seated Calf Raise', 'calves', '{}', 'barbell', 'reps', 'Barbell_Seated_Calf_Raise', array['Place a block about 12 inches in front of a flat bench.','Sit on the bench and place the ball of your feet on the block.','Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.','Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.','After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-shoulder-press', 'Barbell Shoulder Press', 'shoulders', '{chest,triceps}', 'barbell', 'reps', 'Barbell_Shoulder_Press', array['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).','Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the shoulders slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-shrug', 'Barbell Shrug', 'traps', '{}', 'barbell', 'reps', 'Barbell_Shrug', array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-shrug-behind-the-back', 'Barbell Shrug Behind The Back', 'traps', '{forearms,middle_back}', 'barbell', 'reps', 'Barbell_Shrug_Behind_The_Back', array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.','Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.','Slowly return to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-side-bend', 'Barbell Side Bend', 'abdominals', '{lower_back}', 'barbell', 'reps', 'Barbell_Side_Bend', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('barbell-side-split-squat', 'Barbell Side Split Squat', 'quadriceps', '{calves,hamstrings,lower_back}', 'barbell', 'reps', 'Barbell_Side_Split_Squat', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.','Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.','Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.','After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[]),
  ('barbell-squat-to-a-bench', 'Barbell Squat To A Bench', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Barbell_Squat_To_A_Bench', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.','Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.']::text[]),
  ('barbell-step-ups', 'Barbell Step Ups', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Barbell_Step_Ups', array['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[]),
  ('battling-ropes', 'Battling Ropes', 'shoulders', '{chest,forearms}', 'other', 'reps', 'Battling_Ropes', array['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.','Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.','As you let that arm drop to the starting position, raise the opposite side.','Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.']::text[]),
  ('bear-crawl-sled-drags', 'Bear Crawl Sled Drags', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'time', 'Bear_Crawl_Sled_Drags', array['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.','Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.']::text[]),
  ('bench-dips', 'Bench Dips', 'triceps', '{chest,shoulders}', 'body_only', 'reps', 'Bench_Dips', array['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('bench-jump', 'Bench Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Bench_Jump', array['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.','Perform a short squat in preparation for the jump; swing your arms behind you.','Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','Jump over the bench, landing with the knees bent, absorbing the impact through the legs.','Turn around and face the opposite direction, then jump back over the bench.']::text[]),
  ('bench-press-powerlifting', 'Bench Press - Powerlifting', 'triceps', '{chest,forearms,lats,shoulders}', 'barbell', 'reps', 'Bench_Press_-_Powerlifting', array['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
  ('bench-press-with-bands', 'Bench Press - With Bands', 'chest', '{shoulders,triceps}', 'bands', 'reps', 'Bench_Press_-_With_Bands', array['Using a flat bench secure a band under the leg of the bench that is nearest to your head.','Once the band is secure, grab it by both handles and lie down on the bench.','Extend your arms so that you are holding the band handles in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.','As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.']::text[]),
  ('bench-press-with-chains', 'Bench Press with Chains', 'triceps', '{chest,lats,shoulders}', 'barbell', 'reps', 'Bench_Press_with_Chains', array['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.','Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
  ('bench-sprint', 'Bench Sprint', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'reps', 'Bench_Sprint', array['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.','Push off with your foot on top of the bench, extending through the hip and knee.','Land with the opposite foot on top of the box, returning your other foot back to the start position.','Continue alternating from one foot to another to complete the set.']::text[]),
  ('bent-arm-barbell-pullover', 'Bent-Arm Barbell Pullover', 'lats', '{chest,shoulders,triceps}', 'barbell', 'reps', 'Bent-Arm_Barbell_Pullover', array['Lie on a flat bench with a barbell using a shoulder grip width.','Hold the bar straight over your chest with a bend in your arms. This will be your starting position.','While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
  ('bent-arm-dumbbell-pullover', 'Bent-Arm Dumbbell Pullover', 'chest', '{lats,shoulders,triceps}', 'dumbbell', 'reps', 'Bent-Arm_Dumbbell_Pullover', array['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
  ('bent-knee-hip-raise', 'Bent-Knee Hip Raise', 'abdominals', '{}', 'body_only', 'reps', 'Bent-Knee_Hip_Raise', array['Lay flat on the floor with your arms next to your sides.','Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.','Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.','Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.','Repeat for the recommended amount of repetitions.']::text[]),
  ('bent-over-dumbbell-rear-delt-raise-with-head-on-bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'shoulders', '{}', 'dumbbell', 'reps', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', array['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.','While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.','Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.','After a one second contraction at the top, slowly lower the dumbbells back to the starting position.','Repeat the recommended amount of repetitions.']::text[]),
  ('bent-over-low-pulley-side-lateral', 'Bent Over Low-Pulley Side Lateral', 'shoulders', '{lower_back,middle_back,traps}', 'cable', 'reps', 'Bent_Over_Low-Pulley_Side_Lateral', array['Select a weight and hold the handle of the low pulley with your right hand.','Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.','Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.','Slowly lower the weight back to the starting position as you breathe in.','Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[]),
  ('bent-over-one-arm-long-bar-row', 'Bent Over One-Arm Long Bar Row', 'middle_back', '{biceps,lats,lower_back,traps}', 'barbell', 'reps', 'Bent_Over_One-Arm_Long_Bar_Row', array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions and switch arms.']::text[]),
  ('bent-over-two-arm-long-bar-row', 'Bent Over Two-Arm Long Bar Row', 'middle_back', '{biceps,lats}', 'barbell', 'reps', 'Bent_Over_Two-Arm_Long_Bar_Row', array['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.','Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.','Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.','Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.','Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).','Repeat for the recommended amount of repetitions.']::text[]),
  ('bent-over-two-dumbbell-row', 'Bent Over Two-Dumbbell Row', 'middle_back', '{biceps,lats,shoulders}', 'dumbbell', 'reps', 'Bent_Over_Two-Dumbbell_Row', array['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('bent-over-two-dumbbell-row-with-palms-in', 'Bent Over Two-Dumbbell Row With Palms In', 'middle_back', '{biceps,lats}', 'dumbbell', 'reps', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', array['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('bent-press', 'Bent Press', 'abdominals', '{glutes,hamstrings,lower_back,quadriceps,shoulders,triceps}', 'kettlebells', 'reps', 'Bent_Press', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.','Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.','Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[]),
  ('bicycling', 'Bicycling', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'cardio', 'Bicycling', array['To begin, seat yourself on the bike and adjust the seat to your height.']::text[]),
  ('board-press', 'Board Press', 'triceps', '{chest,forearms,lats,shoulders}', 'barbell', 'reps', 'Board_Press', array['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.','Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
  ('body-up', 'Body-Up', 'triceps', '{abdominals,forearms}', 'body_only', 'reps', 'Body-Up', array['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.','Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.','Slowly lower your forearms back to the ground by allowing the elbows to flex.','Repeat.']::text[]),
  ('body-tricep-press', 'Body Tricep Press', 'triceps', '{}', 'body_only', 'reps', 'Body_Tricep_Press', array['Position a bar in a rack at chest height.','Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.','Begin by flexing the elbow, lowering yourself towards the bar.','Pause, and then reverse the motion by extending the elbows.','Progress from bodyweight by adding chains over your shoulders.']::text[]),
  ('bodyweight-flyes', 'Bodyweight Flyes', 'chest', '{abdominals,shoulders,triceps}', 'ez_curl_bar', 'reps', 'Bodyweight_Flyes', array['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.','Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.','Place your hands on the bars. This will be your starting position.','Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.','After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.']::text[]),
  ('bodyweight-mid-row', 'Bodyweight Mid Row', 'middle_back', '{biceps,lats}', 'other', 'reps', 'Bodyweight_Mid_Row', array['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.','Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.','After a brief pause, return to the starting position.']::text[]),
  ('bodyweight-squat', 'Bodyweight Squat', 'quadriceps', '{glutes,hamstrings}', 'body_only', 'reps', 'Bodyweight_Squat', array['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.','Begin the movement by flexing your knees and hips, sitting back with your hips.','Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[]),
  ('bodyweight-walking-lunge', 'Bodyweight Walking Lunge', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Bodyweight_Walking_Lunge', array['Begin standing with your feet shoulder width apart and your hands on your hips.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[]),
  ('bosu-ball-cable-crunch-with-side-bends', 'Bosu Ball Cable Crunch With Side Bends', 'abdominals', '{}', 'cable', 'reps', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', array['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.','Grab a Bosu Ball and position it in front and center of the cable machine.','Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.','With both hands, reach back and grab the handle of each cable.','With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.','Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.']::text[]),
  ('bottoms-up-clean-from-the-hang-position', 'Bottoms-Up Clean From The Hang Position', 'forearms', '{biceps,shoulders}', 'kettlebells', 'reps', 'Bottoms-Up_Clean_From_The_Hang_Position', array['Initiate the exercise by standing upright with a kettlebell in one hand.','Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[]),
  ('bottoms-up', 'Bottoms Up', 'abdominals', '{}', 'body_only', 'reps', 'Bottoms_Up', array['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.','To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.','After a brief pause, return to the starting position.']::text[]),
  ('box-jump-multiple-response', 'Box Jump (Multiple Response)', 'hamstrings', '{abductors,adductors,calves,glutes,quadriceps}', 'other', 'reps', 'Box_Jump_Multiple_Response', array['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.','Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.','Immediately drop or jump back down to the original starting place; then repeat the sequence.']::text[]),
  ('box-skip', 'Box Skip', 'hamstrings', '{abductors,adductors,calves,glutes,quadriceps}', 'other', 'reps', 'Box_Skip', array['You will need several boxes lined up about 8 feet apart.','Begin facing the first box with one leg slightly behind the other.','Drive off the back leg, attempting to gain as much height with the hips as possible.','Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.','Then, step to the next box and repeat.']::text[]),
  ('box-squat', 'Box Squat', 'quadriceps', '{adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Box_Squat', array['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[]),
  ('box-squat-with-bands', 'Box Squat with Bands', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Box_Squat_with_Bands', array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[]),
  ('box-squat-with-chains', 'Box Squat with Chains', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Box_Squat_with_Chains', array['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.','To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[]),
  ('bradford-rocky-presses', 'Bradford/Rocky Presses', 'shoulders', '{triceps}', 'barbell', 'reps', 'Bradford_Rocky_Presses', array['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.','Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.','Now lower the bar down to the back of the head slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Lower the bar down to the starting position slowly as you inhale. This is one repetition.','Alternate in this manner until you complete the recommended amount of repetitions.']::text[]),
  ('butt-ups', 'Butt-Ups', 'abdominals', '{}', 'body_only', 'reps', 'Butt-Ups', array['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.','Arch your back slightly out rather than keeping your back completely straight.','Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.','Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.','Repeat for the recommended amount of repetitions.']::text[]),
  ('butt-lift-bridge', 'Butt Lift (Bridge)', 'glutes', '{hamstrings}', 'body_only', 'reps', 'Butt_Lift_Bridge', array['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.','Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.','Slowly go back to the starting position as you breathe in.']::text[]),
  ('cable-chest-press', 'Cable Chest Press', 'chest', '{shoulders,triceps}', 'cable', 'reps', 'Cable_Chest_Press', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.','After pausing at full extension, return to th starting position, keeping tension on the cables.','You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[]),
  ('cable-deadlifts', 'Cable Deadlifts', 'quadriceps', '{forearms,glutes,hamstrings,lower_back}', 'cable', 'reps', 'Cable_Deadlifts', array['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.','To begin, squat down be flexing your hips and knees until you can reach the handles.','After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.','After reaching a full standing position, Return to the starting position and repeat.']::text[]),
  ('cable-hammer-curls-rope-attachment', 'Cable Hammer Curls - Rope Attachment', 'biceps', '{}', 'cable', 'reps', 'Cable_Hammer_Curls_-_Rope_Attachment', array['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.','Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.','After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-hip-adduction', 'Cable Hip Adduction', 'quadriceps', '{}', 'cable', 'reps', 'Cable_Hip_Adduction', array['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.','Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.','Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.','Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.','Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.','Slowly return to the starting position as you breathe in.']::text[]),
  ('cable-incline-pushdown', 'Cable Incline Pushdown', 'lats', '{}', 'cable', 'reps', 'Cable_Incline_Pushdown', array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.','Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.','Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-incline-triceps-extension', 'Cable Incline Triceps Extension', 'triceps', '{}', 'cable', 'reps', 'Cable_Incline_Triceps_Extension', array['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.','Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.','Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.','Slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-internal-rotation', 'Cable Internal Rotation', 'shoulders', '{}', 'cable', 'reps', 'Cable_Internal_Rotation', array['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.','Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.','Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.','Slowly go back to the initial position.','Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[]),
  ('cable-iron-cross', 'Cable Iron Cross', 'chest', '{}', 'cable', 'reps', 'Cable_Iron_Cross', array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.','Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.','Keeping the elbows extended, pull your arms straight to your sides.','Return your arms back to the starting position after a pause at the peak contraction.','Continue the movement for the prescribed number of repetitions.']::text[]),
  ('cable-judo-flip', 'Cable Judo Flip', 'abdominals', '{}', 'cable', 'reps', 'Cable_Judo_Flip', array['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.','Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.','Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.','Return to the starting position and repeat until failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
  ('cable-lying-triceps-extension', 'Cable Lying Triceps Extension', 'triceps', '{}', 'cable', 'reps', 'Cable_Lying_Triceps_Extension', array['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.','With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.','Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.','Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.','Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
  ('cable-one-arm-tricep-extension', 'Cable One Arm Tricep Extension', 'triceps', '{}', 'cable', 'reps', 'Cable_One_Arm_Tricep_Extension', array['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.','Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.','As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.','Squeeze the triceps and hold for a second in this contracted position.','Slowly return the handle to the starting position.','Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[]),
  ('cable-preacher-curl', 'Cable Preacher Curl', 'biceps', '{forearms}', 'cable', 'reps', 'Cable_Preacher_Curl', array['Place a preacher bench about 2 feet in front of a pulley machine.','Attach a straight bar to the low pulley.','Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.','Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.','Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.','Now slowly lower the weight to the starting position.']::text[]),
  ('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'shoulders', '{}', 'cable', 'reps', 'Cable_Rear_Delt_Fly', array['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.','Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.','Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.','Pause at the end of the motion before returning the handles to the start position.']::text[]),
  ('cable-reverse-crunch', 'Cable Reverse Crunch', 'abdominals', '{}', 'cable', 'reps', 'Cable_Reverse_Crunch', array['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.','Sit down with your feet toward the pulley and attach the cable to your ankles.','Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.','With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.','Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.','Repeat the same movement to failure.']::text[]),
  ('cable-rope-rear-delt-rows', 'Cable Rope Rear-Delt Rows', 'shoulders', '{biceps,middle_back}', 'cable', 'reps', 'Cable_Rope_Rear-Delt_Rows', array['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.','Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.','Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.','Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.','Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-russian-twists', 'Cable Russian Twists', 'abdominals', '{}', 'cable', 'reps', 'Cable_Russian_Twists', array['Connect a standard handle attachment, and position the cable to a middle pulley position.','Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.','Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.','Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.','Repeat the same movement to failure.']::text[]),
  ('cable-seated-crunch', 'Cable Seated Crunch', 'abdominals', '{}', 'cable', 'reps', 'Cable_Seated_Crunch', array['Seat on a flat bench with your back facing a high pulley.','Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.','With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.','As you inhale, go back to the initial position slowly.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-shoulder-press', 'Cable Shoulder Press', 'shoulders', '{triceps}', 'cable', 'reps', 'Cable_Shoulder_Press', array['Move the cables to the bottom of the towers and select an appropriate weight.','Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.','Keeping your head and chest up, extend through the elbow to press the handles directly over head.','After pausing at the top, return to the starting position and repeat.']::text[]),
  ('cable-shrugs', 'Cable Shrugs', 'traps', '{}', 'cable', 'reps', 'Cable_Shrugs', array['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.','Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.','Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.','Lower the bar back to the original position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cable-wrist-curl', 'Cable Wrist Curl', 'forearms', '{}', 'cable', 'reps', 'Cable_Wrist_Curl', array['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.','Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.','Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
  ('calf-machine-shoulder-shrug', 'Calf-Machine Shoulder Shrug', 'traps', '{}', 'machine', 'reps', 'Calf-Machine_Shoulder_Shrug', array['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.','Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.','Slowly return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('calf-press', 'Calf Press', 'calves', '{}', 'machine', 'reps', 'Calf_Press', array['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.','Select an appropriate weight, and grasp the handles. This will be your starting position.','Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.','After a brief pause, reverse the motion and repeat.']::text[]),
  ('calf-press-on-the-leg-press-machine', 'Calf Press On The Leg Press Machine', 'calves', '{}', 'machine', 'reps', 'Calf_Press_On_The_Leg_Press_Machine', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[]),
  ('calf-raise-on-a-dumbbell', 'Calf Raise On A Dumbbell', 'calves', '{}', 'dumbbell', 'reps', 'Calf_Raise_On_A_Dumbbell', array['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.','Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.','Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.','Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.','Repeat for the recommended amount of repetitions.']::text[]),
  ('calf-raises-with-bands', 'Calf Raises - With Bands', 'calves', '{}', 'bands', 'reps', 'Calf_Raises_-_With_Bands', array['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.','While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.','Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.','After a one second contraction, slowly go back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('car-deadlift', 'Car Deadlift', 'quadriceps', '{forearms,glutes,hamstrings,lower_back,traps}', 'other', 'reps', 'Car_Deadlift', array['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.','Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.','Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.','Lower the weight by bending at the hips and guiding it to the floor.']::text[]),
  ('car-drivers', 'Car Drivers', 'shoulders', '{forearms}', 'barbell', 'reps', 'Car_Drivers', array['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.','Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.','Reverse the motion, turning it all the way to the opposite side.','Repeat for the recommended amount of repetitions.']::text[]),
  ('carioca-quick-step', 'Carioca Quick Step', 'adductors', '{abdominals,abductors,calves,glutes,hamstrings,quadriceps}', 'body_only', 'reps', 'Carioca_Quick_Step', array['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.','With your right foot, quick step behind and pull the knee up.','Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.']::text[]),
  ('catch-and-overhead-throw', 'Catch and Overhead Throw', 'lats', '{abdominals,chest,shoulders}', 'medicine_ball', 'reps', 'Catch_and_Overhead_Throw', array['Begin standing while facing a wall or a partner.','Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.','Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.']::text[]),
  ('chain-handle-extension', 'Chain Handle Extension', 'triceps', '{}', 'other', 'reps', 'Chain_Handle_Extension', array['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.','Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.','Pause at the lockout, and reverse the motion to return to the starting position.']::text[]),
  ('chain-press', 'Chain Press', 'chest', '{shoulders,triceps}', 'other', 'reps', 'Chain_Press', array['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.','Lower the chains by flexing the elbows, unloading some of the chain onto the floor.','Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.']::text[]),
  ('chair-squat', 'Chair Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Chair_Squat', array['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.','Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.','Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.','Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.','Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('chest-push-from-3-point-stance', 'Chest Push from 3 point stance', 'chest', '{abdominals,shoulders,triceps}', 'medicine_ball', 'reps', 'Chest_Push_from_3_point_stance', array['Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.','To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.','As you execute the second step, explosively release the ball forward as hard as possible.']::text[]),
  ('chest-push-multiple-response', 'Chest Push (multiple response)', 'chest', '{abdominals,shoulders,triceps}', 'medicine_ball', 'reps', 'Chest_Push_multiple_response', array['Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.','Follow through by falling forward, catching yourself with your hands.','Immediately return to an upright position. Repeat for the desired number of repetitions.']::text[]),
  ('chest-push-single-response', 'Chest Push (single response)', 'chest', '{abdominals,shoulders,triceps}', 'medicine_ball', 'reps', 'Chest_Push_single_response', array['Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.','Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.','Follow through by falling forward, catching yourself with your hands.']::text[]),
  ('chest-push-with-run-release', 'Chest Push with Run Release', 'chest', '{abdominals,shoulders,triceps}', 'medicine_ball', 'reps', 'Chest_Push_with_Run_Release', array['Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.','While taking your first step draw the medicine ball into your chest.','As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!']::text[]),
  ('circus-bell', 'Circus Bell', 'shoulders', '{forearms,glutes,hamstrings,lower_back,traps,triceps}', 'other', 'reps', 'Circus_Bell', array['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.','Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.','Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.','Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.']::text[]),
  ('clean', 'Clean', 'hamstrings', '{calves,forearms,glutes,lower_back,quadriceps,shoulders,traps}', 'barbell', 'reps', 'Clean', array['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
  ('clean-deadlift', 'Clean Deadlift', 'hamstrings', '{forearms,glutes,lower_back,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Clean_Deadlift', array['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.','Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.','After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[]),
  ('clean-pull', 'Clean Pull', 'quadriceps', '{forearms,glutes,hamstrings,lower_back,traps}', 'barbell', 'reps', 'Clean_Pull', array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[]),
  ('clean-shrug', 'Clean Shrug', 'traps', '{forearms,shoulders}', 'barbell', 'reps', 'Clean_Shrug', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.','Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[]),
  ('clean-and-jerk', 'Clean and Jerk', 'shoulders', '{abdominals,glutes,hamstrings,lower_back,quadriceps,traps,triceps}', 'barbell', 'reps', 'Clean_and_Jerk', array['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.','The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.']::text[]),
  ('clean-and-press', 'Clean and Press', 'shoulders', '{abdominals,calves,glutes,hamstrings,lower_back,middle_back,quadriceps,traps,triceps}', 'barbell', 'reps', 'Clean_and_Press', array['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.','Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.','As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.','At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.','As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.','Stand to full height, holding the bar in the clean position.']::text[]),
  ('clean-from-blocks', 'Clean from Blocks', 'quadriceps', '{calves,glutes,hamstrings,shoulders,traps}', 'barbell', 'reps', 'Clean_from_Blocks', array['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.','As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.']::text[]),
  ('clock-push-up', 'Clock Push-Up', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Clock_Push-Up', array['Move into a prone position on the floor, supporting your weight on your hands and toes.','Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','Descend by flexing at the elbow, lowering your chest toward the ground.','At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.','As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.','Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[]),
  ('close-grip-barbell-bench-press', 'Close-Grip Barbell Bench Press', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'Close-Grip_Barbell_Bench_Press', array['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('close-grip-dumbbell-press', 'Close-Grip Dumbbell Press', 'triceps', '{chest,shoulders}', 'dumbbell', 'reps', 'Close-Grip_Dumbbell_Press', array['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.','Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.','Initiate the movement by lowering the dumbbell to your chest.','Return to the starting position by extending the elbows.']::text[]),
  ('close-grip-ez-bar-curl-with-band', 'Close-Grip EZ-Bar Curl with Band', 'biceps', '{forearms}', 'ez_curl_bar', 'reps', 'Close-Grip_EZ-Bar_Curl_with_Band', array['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.','While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('close-grip-ez-bar-press', 'Close-Grip EZ-Bar Press', 'triceps', '{chest,shoulders}', 'ez_curl_bar', 'reps', 'Close-Grip_EZ-Bar_Press', array['Lie on a flat bench with an EZ bar loaded to an appropriate weight.','Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.','Repeat.']::text[]),
  ('close-grip-ez-bar-curl', 'Close-Grip EZ Bar Curl', 'biceps', '{forearms}', 'barbell', 'reps', 'Close-Grip_EZ_Bar_Curl', array['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('close-grip-push-up-off-of-a-dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'triceps', '{abdominals,chest,shoulders}', 'body_only', 'reps', 'Close-Grip_Push-Up_off_of_a_Dumbbell', array['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.','Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.','Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.','After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('close-grip-standing-barbell-curl', 'Close-Grip Standing Barbell Curl', 'biceps', '{forearms}', 'barbell', 'reps', 'Close-Grip_Standing_Barbell_Curl', array['Hold a barbell with both hands, palms up and a few inches apart.','Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.','Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('cocoons', 'Cocoons', 'abdominals', '{}', 'body_only', 'reps', 'Cocoons', array['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.','To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','After a brief pause, return to the starting position.']::text[]),
  ('conans-wheel', 'Conan''s Wheel', 'quadriceps', '{abdominals,biceps,calves,forearms,lower_back,shoulders,traps}', 'other', 'reps', 'Conans_Wheel', array['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.','Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.']::text[]),
  ('cross-body-crunch', 'Cross-Body Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Cross-Body_Crunch', array['Lie flat on your back and bend your knees about 60 degrees.','Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.','Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.','Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.','Continue alternating in this manner until all prescribed repetitions are done.']::text[]),
  ('cross-body-hammer-curl', 'Cross Body Hammer Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Cross_Body_Hammer_Curl', array['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.','While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.','Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.','Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[]),
  ('cross-over-with-bands', 'Cross Over - With Bands', 'chest', '{biceps,shoulders}', 'bands', 'reps', 'Cross_Over_-_With_Bands', array['Secure an exercise band around a stationary post.','While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.','Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.','While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.','Slowly return to the starting position as you inhale.','Perform for the recommended amount of repetitions.']::text[]),
  ('crucifix', 'Crucifix', 'shoulders', '{forearms}', 'other', 'time', 'Crucifix', array['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.','Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[]),
  ('crunch-hands-overhead', 'Crunch - Hands Overhead', 'abdominals', '{}', 'body_only', 'reps', 'Crunch_-_Hands_Overhead', array['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.','Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.','Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.','Slowly lower down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('crunch-legs-on-exercise-ball', 'Crunch - Legs On Exercise Ball', 'abdominals', '{}', 'body_only', 'reps', 'Crunch_-_Legs_On_Exercise_Ball', array['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.','Place your feet three to four inches apart and point your toes inward so they touch.','Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.','Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.','Slowly go back down to the starting position as you inhale.']::text[]),
  ('cuban-press', 'Cuban Press', 'shoulders', '{traps}', 'dumbbell', 'reps', 'Cuban_Press', array['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.','To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.','Now press the dumbbells by extending at the elbows, straightening your arms overhead.','Return to the starting position as you breathe in by reversing the steps.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dead-bug', 'Dead Bug', 'abdominals', '{}', 'body_only', 'reps', 'Dead_Bug', array['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','Stay tight and return the working leg to the starting position.']::text[]),
  ('deadlift-with-bands', 'Deadlift with Bands', 'lower_back', '{forearms,glutes,hamstrings,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Deadlift_with_Bands', array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
  ('deadlift-with-chains', 'Deadlift with Chains', 'lower_back', '{forearms,glutes,hamstrings,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Deadlift_with_Chains', array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.','Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.','Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
  ('decline-close-grip-bench-to-skull-crusher', 'Decline Close-Grip Bench To Skull Crusher', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'Decline_Close-Grip_Bench_To_Skull_Crusher', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','Using the triceps to push the bar back up, press it back to the starting position as you exhale.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.']::text[]),
  ('decline-crunch', 'Decline Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Decline_Crunch', array['Secure your legs at the end of the decline bench and lie down.','Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.','While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.','Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.','After the one second contraction, begin to come down slowly again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('decline-dumbbell-bench-press', 'Decline Dumbbell Bench Press', 'chest', '{shoulders,triceps}', 'dumbbell', 'reps', 'Decline_Dumbbell_Bench_Press', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
  ('decline-dumbbell-flyes', 'Decline Dumbbell Flyes', 'chest', '{}', 'dumbbell', 'reps', 'Decline_Dumbbell_Flyes', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('decline-dumbbell-triceps-extension', 'Decline Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Decline_Dumbbell_Triceps_Extension', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.','As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.','Lift the dumbbells back to the starting position by contracting the triceps and exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('decline-ez-bar-triceps-extension', 'Decline EZ Bar Triceps Extension', 'triceps', '{}', 'barbell', 'reps', 'Decline_EZ_Bar_Triceps_Extension', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.','As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.','Lift the bar back to the starting position by contracting the triceps and exhaling.','Repeat until the recommended amount of repetitions is performed.']::text[]),
  ('decline-oblique-crunch', 'Decline Oblique Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Decline_Oblique_Crunch', array['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.','Put one hand beside your head and the other on your thigh. This will be your starting position.','Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.','Lower your body back down slowly to the starting position as you inhale.','After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[]),
  ('decline-push-up', 'Decline Push-Up', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Decline_Push-Up', array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[]),
  ('decline-reverse-crunch', 'Decline Reverse Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Decline_Reverse_Crunch', array['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.','Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.','While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('decline-smith-press', 'Decline Smith Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Decline_Smith_Press', array['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.','As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.','After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.','Repeat the movement for the prescribed amount of repetitions.','When the set is complete, lock the bar back in the rack.']::text[]),
  ('deficit-deadlift', 'Deficit Deadlift', 'lower_back', '{forearms,glutes,hamstrings,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Deficit_Deadlift', array['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
  ('depth-jump-leap', 'Depth Jump Leap', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'other', 'reps', 'Depth_Jump_Leap', array['For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.','Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.','Begin by dropping off the initial box, landing and simultaneously taking off with both feet.','Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.']::text[]),
  ('dip-machine', 'Dip Machine', 'triceps', '{chest,shoulders}', 'machine', 'reps', 'Dip_Machine', array['Sit securely in a dip machine, select the weight and firmly grasp the handles.','Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.','As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.','Now slowly let your arms come back up to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dips-chest-version', 'Dips - Chest Version', 'chest', '{shoulders,triceps}', 'other', 'reps', 'Dips_-_Chest_Version', array['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.','While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.','Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('double-kettlebell-alternating-hang-clean', 'Double Kettlebell Alternating Hang Clean', 'hamstrings', '{biceps,calves,forearms,glutes,lower_back,quadriceps,traps}', 'kettlebells', 'reps', 'Double_Kettlebell_Alternating_Hang_Clean', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean one kettlebell to your shoulder and hold on to the other kettlebell.','With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.']::text[]),
  ('double-kettlebell-jerk', 'Double Kettlebell Jerk', 'shoulders', '{calves,quadriceps,triceps}', 'kettlebells', 'reps', 'Double_Kettlebell_Jerk', array['Hold a kettlebell by the handle in each hand.','Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum.','As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.','Return your feet to the ground in a split fashion, with one foot forward and one foot back.']::text[]),
  ('double-kettlebell-push-press', 'Double Kettlebell Push Press', 'shoulders', '{calves,quadriceps,triceps}', 'kettlebells', 'reps', 'Double_Kettlebell_Push_Press', array['Clean two kettlebells to your shoulders.','Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.','Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.']::text[]),
  ('double-kettlebell-snatch', 'Double Kettlebell Snatch', 'shoulders', '{glutes,hamstrings,quadriceps}', 'kettlebells', 'reps', 'Double_Kettlebell_Snatch', array['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.','Swing the kettlebells between your legs forcefully and reverse the direction.','Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[]),
  ('double-kettlebell-windmill', 'Double Kettlebell Windmill', 'abdominals', '{glutes,hamstrings,shoulders,triceps}', 'kettlebells', 'reps', 'Double_Kettlebell_Windmill', array['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.','Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[]),
  ('double-leg-butt-kick', 'Double Leg Butt Kick', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'body_only', 'reps', 'Double_Leg_Butt_Kick', array['Begin standing with your knees slightly bent.','Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.','As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.','Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.']::text[]),
  ('downward-facing-balance', 'Downward Facing Balance', 'glutes', '{abdominals,hamstrings}', 'exercise_ball', 'reps', 'Downward_Facing_Balance', array['Lie facedown on top of an exercise ball.','While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.']::text[]),
  ('drag-curl', 'Drag Curl', 'biceps', '{forearms}', 'barbell', 'reps', 'Drag_Curl', array['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.','As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.','Slowly go back to the starting position as you keep the bar in contact with the torso at all times.','Repeat for the recommended amount of repetitions.']::text[]),
  ('drop-push', 'Drop Push', 'chest', '{shoulders,triceps}', 'other', 'reps', 'Drop_Push', array['Position low boxes or other platforms 2-3 feet apart.','Move to a pushup position between them, supporting yourself by placing your hands on the boxes.','With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.']::text[]),
  ('dumbbell-alternate-bicep-curl', 'Dumbbell Alternate Bicep Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Dumbbell_Alternate_Bicep_Curl', array['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
  ('dumbbell-bench-press-with-neutral-grip', 'Dumbbell Bench Press with Neutral Grip', 'chest', '{shoulders,triceps}', 'dumbbell', 'reps', 'Dumbbell_Bench_Press_with_Neutral_Grip', array['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.','Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.','Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.','Pause, then extend the elbow and return to the starting position.']::text[]),
  ('dumbbell-clean', 'Dumbbell Clean', 'hamstrings', '{calves,forearms,glutes,lower_back,quadriceps,shoulders,traps}', 'dumbbell', 'reps', 'Dumbbell_Clean', array['Begin standing with a dumbbell in each hand with your feet shoulder width apart.','Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.','To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.','After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.','Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[]),
  ('dumbbell-floor-press', 'Dumbbell Floor Press', 'triceps', '{chest,shoulders}', 'dumbbell', 'reps', 'Dumbbell_Floor_Press', array['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.','Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.','Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[]),
  ('dumbbell-incline-row', 'Dumbbell Incline Row', 'middle_back', '{biceps,forearms,lats,shoulders}', 'dumbbell', 'reps', 'Dumbbell_Incline_Row', array['Using a neutral grip, lean into an incline bench.','Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.','Retract the shoulder blades and flex the elbows to row the dumbbells to your side.','Pause at the top of the motion, and then return to the starting position.']::text[]),
  ('dumbbell-incline-shoulder-raise', 'Dumbbell Incline Shoulder Raise', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Dumbbell_Incline_Shoulder_Raise', array['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.','Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.','While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.','Bring back the dumbbells to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-lying-one-arm-rear-lateral-raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'shoulders', '{middle_back}', 'dumbbell', 'reps', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', array['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.','Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.','Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbell to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-lying-pronation', 'Dumbbell Lying Pronation', 'forearms', '{}', 'dumbbell', 'reps', 'Dumbbell_Lying_Pronation', array['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-lying-rear-lateral-raise', 'Dumbbell Lying Rear Lateral Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Dumbbell_Lying_Rear_Lateral_Raise', array['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.','Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.','Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbells to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
  ('dumbbell-lying-supination', 'Dumbbell Lying Supination', 'forearms', '{}', 'dumbbell', 'reps', 'Dumbbell_Lying_Supination', array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
  ('dumbbell-one-arm-shoulder-press', 'Dumbbell One-Arm Shoulder Press', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Dumbbell_One-Arm_Shoulder_Press', array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.','As you exhale, push the dumbbell up until your arm is fully extended.','After a second pause, slowly come down back to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch arms.']::text[]),
  ('dumbbell-one-arm-triceps-extension', 'Dumbbell One-Arm Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Dumbbell_One-Arm_Triceps_Extension', array['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.','Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.','Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.','Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.','Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.','Repeat for the recommended amount of repetitions and switch arms.']::text[]),
  ('dumbbell-one-arm-upright-row', 'Dumbbell One-Arm Upright Row', 'shoulders', '{biceps,traps}', 'dumbbell', 'reps', 'Dumbbell_One-Arm_Upright_Row', array['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.','Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.','Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions and switch arms.']::text[]),
  ('dumbbell-prone-incline-curl', 'Dumbbell Prone Incline Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Dumbbell_Prone_Incline_Curl', array['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).','Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.','Now keep your elbows in by your side and face the palms forward. This will be your starting position.','Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.','Lower the dumbbells until your arms are fully extended.','Repeat for the recommended amount of times.']::text[]),
  ('dumbbell-raise', 'Dumbbell Raise', 'shoulders', '{biceps}', 'dumbbell', 'reps', 'Dumbbell_Raise', array['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.','Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-rear-lunge', 'Dumbbell Rear Lunge', 'quadriceps', '{calves,glutes,hamstrings}', 'dumbbell', 'reps', 'Dumbbell_Rear_Lunge', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.','Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.','Now repeat with the opposite leg.']::text[]),
  ('dumbbell-scaption', 'Dumbbell Scaption', 'shoulders', '{traps}', 'dumbbell', 'reps', 'Dumbbell_Scaption', array['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.','Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.','Continue until your arms are parallel to the ground, and then return to the starting position.']::text[]),
  ('dumbbell-seated-box-jump', 'Dumbbell Seated Box Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'dumbbell', 'reps', 'Dumbbell_Seated_Box_Jump', array['Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.','Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.','Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.','Step down and return to the starting position.']::text[]),
  ('dumbbell-seated-one-leg-calf-raise', 'Dumbbell Seated One-Leg Calf Raise', 'calves', '{}', 'dumbbell', 'reps', 'Dumbbell_Seated_One-Leg_Calf_Raise', array['Place a block on the floor about 12 inches from a flat bench.','Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.','Now place the ball of your left foot on the block. This will be your starting position.','Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.','Slowly return to the starting position, stretching as far down as possible.','Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[]),
  ('dumbbell-shrug', 'Dumbbell Shrug', 'traps', '{}', 'dumbbell', 'reps', 'Dumbbell_Shrug', array['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.','Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.','Lower the dumbbells back to the original position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-side-bend', 'Dumbbell Side Bend', 'abdominals', '{}', 'dumbbell', 'reps', 'Dumbbell_Side_Bend', array['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions and then change hands.']::text[]),
  ('dumbbell-squat', 'Dumbbell Squat', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'dumbbell', 'reps', 'Dumbbell_Squat', array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-squat-to-a-bench', 'Dumbbell Squat To A Bench', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'dumbbell', 'reps', 'Dumbbell_Squat_To_A_Bench', array['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.','Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('dumbbell-step-ups', 'Dumbbell Step Ups', 'quadriceps', '{calves,glutes,hamstrings}', 'dumbbell', 'reps', 'Dumbbell_Step_Ups', array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[]),
  ('dumbbell-tricep-extension-pronated-grip', 'Dumbbell Tricep Extension -Pronated Grip', 'triceps', '{}', 'dumbbell', 'reps', 'Dumbbell_Tricep_Extension_-Pronated_Grip', array['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.','The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.','Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.','Then, exhale and use your triceps to return the weight to the starting position.']::text[]),
  ('ez-bar-skullcrusher', 'EZ-Bar Skullcrusher', 'triceps', '{forearms}', 'ez_curl_bar', 'reps', 'EZ-Bar_Skullcrusher', array['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','Lift the bar back to the starting position by extending the elbow and exhaling.','Repeat.']::text[]),
  ('elbow-to-knee', 'Elbow to Knee', 'abdominals', '{}', 'body_only', 'reps', 'Elbow_to_Knee', array['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.','Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.','Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[]),
  ('elevated-back-lunge', 'Elevated Back Lunge', 'quadriceps', '{glutes,hamstrings}', 'barbell', 'reps', 'Elevated_Back_Lunge', array['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.','Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.','Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.','Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.']::text[]),
  ('elevated-cable-rows', 'Elevated Cable Rows', 'lats', '{middle_back,traps}', 'cable', 'reps', 'Elevated_Cable_Rows', array['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.','Place it on the seat of the cable row machine.','Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the V-bar handles.','With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.']::text[]),
  ('exercise-ball-crunch', 'Exercise Ball Crunch', 'abdominals', '{}', 'exercise_ball', 'reps', 'Exercise_Ball_Crunch', array['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).','Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.','With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.','As you inhale, go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('exercise-ball-pull-in', 'Exercise Ball Pull-In', 'abdominals', '{}', 'exercise_ball', 'reps', 'Exercise_Ball_Pull-In', array['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.','Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.','While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.','Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('extended-range-one-arm-kettlebell-floor-press', 'Extended Range One-Arm Kettlebell Floor Press', 'chest', '{shoulders,triceps}', 'kettlebells', 'reps', 'Extended_Range_One-Arm_Kettlebell_Floor_Press', array['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.','Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.']::text[]),
  ('external-rotation', 'External Rotation', 'shoulders', '{}', 'dumbbell', 'reps', 'External_Rotation', array['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.','Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
  ('external-rotation-with-band', 'External Rotation with Band', 'shoulders', '{}', 'bands', 'reps', 'External_Rotation_with_Band', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.','Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.','Continue as far as you are able, pause, and then return to the starting position.']::text[]),
  ('external-rotation-with-cable', 'External Rotation with Cable', 'shoulders', '{}', 'cable', 'reps', 'External_Rotation_with_Cable', array['Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.','Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.','Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.']::text[]),
  ('fast-skipping', 'Fast Skipping', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'body_only', 'reps', 'Fast_Skipping', array['Start in a relaxed position with one leg slightly forward. This will be your starting position.','Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.','Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.']::text[]),
  ('finger-curls', 'Finger Curls', 'forearms', '{}', 'barbell', 'reps', 'Finger_Curls', array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.','Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.','Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[]),
  ('flat-bench-cable-flyes', 'Flat Bench Cable Flyes', 'chest', '{}', 'cable', 'reps', 'Flat_Bench_Cable_Flyes', array['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.','Lay flat on the bench and keep your feet on the ground.','Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.','Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.','Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.','Slowly come back to the starting position.']::text[]),
  ('flat-bench-leg-pull-in', 'Flat Bench Leg Pull-In', 'abdominals', '{}', 'body_only', 'reps', 'Flat_Bench_Leg_Pull-In', array['Lie on an exercise mat or a flat bench with your legs off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.','As you breathe in, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('flat-bench-lying-leg-raise', 'Flat Bench Lying Leg Raise', 'abdominals', '{}', 'body_only', 'reps', 'Flat_Bench_Lying_Leg_Raise', array['Lie with your back flat on a bench and your legs extended in front of you off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.','As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.','Now, as you inhale, slowly lower your legs back down to the starting position.']::text[]),
  ('flexor-incline-dumbbell-curls', 'Flexor Incline Dumbbell Curls', 'biceps', '{}', 'dumbbell', 'reps', 'Flexor_Incline_Dumbbell_Curls', array['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.','Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.','Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.','Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.','As you inhale, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('floor-glute-ham-raise', 'Floor Glute-Ham Raise', 'hamstrings', '{calves,glutes}', 'body_only', 'reps', 'Floor_Glute-Ham_Raise', array['You can use a partner for this exercise or brace your feet under something stable.','Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.','Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.','Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[]),
  ('floor-press', 'Floor Press', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'Floor_Press', array['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[]),
  ('floor-press-with-chains', 'Floor Press with Chains', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'Floor_Press_with_Chains', array['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.','Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.','Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.','Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[]),
  ('flutter-kicks', 'Flutter Kicks', 'glutes', '{hamstrings}', 'body_only', 'reps', 'Flutter_Kicks', array['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.','Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.','Start the movement by lifting the left leg higher than the right leg.','Then lower the left leg as you lift the right leg.','Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.']::text[]),
  ('forward-drag-with-press', 'Forward Drag with Press', 'chest', '{calves,glutes,hamstrings,quadriceps,shoulders,triceps}', 'other', 'reps', 'Forward_Drag_with_Press', array['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.','Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.']::text[]),
  ('frankenstein-squat', 'Frankenstein Squat', 'quadriceps', '{abdominals,calves,glutes,hamstrings}', 'barbell', 'reps', 'Frankenstein_Squat', array['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.','Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.','Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.','Return to the upright position by driving through the front of the heel and extending the knees and hips.']::text[]),
  ('freehand-jump-squat', 'Freehand Jump Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Freehand_Jump_Squat', array['Cross your arms over your chest.','With your head up and your back straight, position your feet at shoulder width.','Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.','Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.','When you touch the floor again, immediately squat down and jump again.','Repeat for the recommended amount of repetitions.']::text[]),
  ('frog-sit-ups', 'Frog Sit-Ups', 'abdominals', '{}', 'body_only', 'reps', 'Frog_Sit-Ups', array['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.','Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.','Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.','Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.','As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.','As you inhale, slowly lower back to the starting position.']::text[]),
  ('front-barbell-squat-to-a-bench', 'Front Barbell Squat To A Bench', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Front_Barbell_Squat_To_A_Bench', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('front-box-jump', 'Front Box Jump', 'hamstrings', '{abductors,adductors,calves,glutes,quadriceps}', 'other', 'reps', 'Front_Box_Jump', array['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.','Perform a short squat in preparation for jumping, swinging your arms behind you.','Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.']::text[]),
  ('front-cable-raise', 'Front Cable Raise', 'shoulders', '{}', 'cable', 'reps', 'Front_Cable_Raise', array['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.','Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.','Now as you inhale lower the arm back down slowly to the starting position.','Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.']::text[]),
  ('front-cone-hops-or-hurdle-hops', 'Front Cone Hops (or hurdle hops)', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'other', 'reps', 'Front_Cone_Hops_or_hurdle_hops', array['Set up a row of cones or other small barriers, placing them a few feet apart.','Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.','Begin by jumping with both feet over the first cone, swinging both arms as you jump.','Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.','Continue until you have jumped over all of the cones.']::text[]),
  ('front-dumbbell-raise', 'Front Dumbbell Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Front_Dumbbell_Raise', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.','Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.','Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[]),
  ('front-incline-dumbbell-raise', 'Front Incline Dumbbell Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Front_Incline_Dumbbell_Raise', array['Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.','Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.','Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.','Lower the arms back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('front-plate-raise', 'Front Plate Raise', 'shoulders', '{}', 'other', 'reps', 'Front_Plate_Raise', array['While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.','Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.','As you inhale, slowly lower the plate back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('front-raise-and-pullover', 'Front Raise And Pullover', 'chest', '{lats,shoulders,triceps}', 'barbell', 'reps', 'Front_Raise_And_Pullover', array['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.','Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.','Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.','Now return the barbell to the starting position by reversing the motion as you exhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('front-squat-clean-grip', 'Front Squat (Clean Grip)', 'quadriceps', '{abdominals,glutes,hamstrings}', 'barbell', 'reps', 'Front_Squat_Clean_Grip', array['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.','Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.','Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.','Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[]),
  ('front-squats-with-two-kettlebells', 'Front Squats With Two Kettlebells', 'quadriceps', '{calves,glutes}', 'kettlebells', 'reps', 'Front_Squats_With_Two_Kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.','Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.','Rise back up by driving through your heels and repeat.']::text[]),
  ('front-two-dumbbell-raise', 'Front Two-Dumbbell Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Front_Two-Dumbbell_Raise', array['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.','As you inhale, lower the dumbbells back down slowly to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('full-range-of-motion-lat-pulldown', 'Full Range-Of-Motion Lat Pulldown', 'lats', '{biceps,middle_back,shoulders}', 'cable', 'reps', 'Full_Range-Of-Motion_Lat_Pulldown', array['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.','Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.']::text[]),
  ('gironda-sternum-chins', 'Gironda Sternum Chins', 'lats', '{biceps,middle_back}', 'other', 'reps', 'Gironda_Sternum_Chins', array['Grasp the pull-up bar with a shoulder width underhand grip.','Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.','Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.','Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.','Slowly start going back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('glute-ham-raise', 'Glute Ham Raise', 'hamstrings', '{calves,glutes}', 'machine', 'reps', 'Glute_Ham_Raise', array['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.','Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.','Return to the starting position, keeping your descent under control.']::text[]),
  ('glute-kickback', 'Glute Kickback', 'glutes', '{hamstrings}', 'body_only', 'reps', 'Glute_Kickback', array['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.','As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.','Go back to the initial position as you inhale and now repeat with the left leg.','Continue to alternate legs until all of the recommended repetitions have been performed.']::text[]),
  ('goblet-squat', 'Goblet Squat', 'quadriceps', '{calves,glutes,hamstrings,shoulders}', 'kettlebells', 'reps', 'Goblet_Squat', array['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.','Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.','At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[]),
  ('good-morning-off-pins', 'Good Morning off Pins', 'hamstrings', '{abdominals,glutes,lower_back}', 'barbell', 'reps', 'Good_Morning_off_Pins', array['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.','Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.']::text[]),
  ('gorilla-chin-crunch', 'Gorilla Chin/Crunch', 'abdominals', '{biceps,lats}', 'body_only', 'reps', 'Gorilla_Chin_Crunch', array['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.','Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.','As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.','Slowly start to inhale as you return to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('hammer-grip-incline-db-bench-press', 'Hammer Grip Incline DB Bench Press', 'chest', '{shoulders,triceps}', 'dumbbell', 'reps', 'Hammer_Grip_Incline_DB_Bench_Press', array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.','Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.','Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('handstand-push-ups', 'Handstand Push-Ups', 'shoulders', '{triceps}', 'body_only', 'reps', 'Handstand_Push-Ups', array['With your back to the wall bend at the waist and place both hands on the floor at shoulder width.','Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.','Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.','Push yourself back up slowly as you exhale until your elbows are nearly locked.','Repeat for the recommended amount of repetitions.']::text[]),
  ('hang-clean', 'Hang Clean', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back,shoulders,traps}', 'barbell', 'reps', 'Hang_Clean', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.','Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
  ('hang-clean-below-the-knees', 'Hang Clean - Below the Knees', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back,shoulders,traps}', 'barbell', 'reps', 'Hang_Clean_-_Below_the_Knees', array['Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.','Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.','At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[]),
  ('hang-snatch', 'Hang Snatch', 'hamstrings', '{abdominals,calves,forearms,glutes,lower_back,quadriceps,shoulders,traps}', 'barbell', 'reps', 'Hang_Snatch', array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.','Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.','Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.']::text[]),
  ('hang-snatch-below-knees', 'Hang Snatch - Below Knees', 'hamstrings', '{abdominals,calves,forearms,glutes,lower_back,quadriceps,shoulders,traps}', 'barbell', 'reps', 'Hang_Snatch_-_Below_Knees', array['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.','Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.','Return to a standing position with the weight overhead, and then return the weight to the floor under control.']::text[]),
  ('hanging-bar-good-morning', 'Hanging Bar Good Morning', 'hamstrings', '{abdominals,glutes,lower_back}', 'barbell', 'reps', 'Hanging_Bar_Good_Morning', array['Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.','Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.','Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.','Slowly lower the weight back to the starting position, where it is supported by the chains.']::text[]),
  ('hanging-pike', 'Hanging Pike', 'abdominals', '{}', 'body_only', 'reps', 'Hanging_Pike', array['Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.','Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.','Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.','Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.','Repeat for the recommended amount of repetitions.']::text[]),
  ('heaving-snatch-balance', 'Heaving Snatch Balance', 'quadriceps', '{abdominals,forearms,glutes,hamstrings,shoulders,triceps}', 'barbell', 'reps', 'Heaving_Snatch_Balance', array['This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.','Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.','Return to a standing position.']::text[]),
  ('heavy-bag-thrust', 'Heavy Bag Thrust', 'chest', '{abdominals,shoulders,triceps}', 'other', 'reps', 'Heavy_Bag_Thrust', array['Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.','Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.','Receive the bag as it swings back by reversing these steps.']::text[]),
  ('high-cable-curls', 'High Cable Curls', 'biceps', '{}', 'cable', 'reps', 'High_Cable_Curls', array['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.','Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.','Slowly bring back the arms to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('hip-extension-with-bands', 'Hip Extension with Bands', 'glutes', '{hamstrings}', 'bands', 'reps', 'Hip_Extension_with_Bands', array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.','Facing the attachment point of the band, hold on to the column to stabilize yourself.','Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.','Return the leg to the starting position.']::text[]),
  ('hip-flexion-with-band', 'Hip Flexion with Band', 'quadriceps', '{}', 'bands', 'reps', 'Hip_Flexion_with_Band', array['Secure one end of the band to the lower portion of a post and attach the other to one ankle.','Face away from the attachment point of the band.','Keeping your head and your chest up, raise your knee up to 90 degrees and pause.','Return the leg to the starting position.']::text[]),
  ('hip-lift-with-band', 'Hip Lift with Band', 'glutes', '{calves,hamstrings}', 'bands', 'reps', 'Hip_Lift_with_Band', array['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.','Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.','Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.','Pause at the top of the motion, and return to the starting position.']::text[]),
  ('hurdle-hops', 'Hurdle Hops', 'hamstrings', '{abductors,adductors,calves,glutes}', 'other', 'reps', 'Hurdle_Hops', array['Set up a row of hurdles or other small barriers, placing them a few feet apart.','Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.','Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.','Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.']::text[]),
  ('hyperextensions-back-extensions', 'Hyperextensions (Back Extensions)', 'lower_back', '{glutes,hamstrings}', 'other', 'reps', 'Hyperextensions_Back_Extensions', array['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.','Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.','With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.','Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.','Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.','Repeat for the recommended amount of repetitions.']::text[]),
  ('hyperextensions-with-no-hyperextension-bench', 'Hyperextensions With No Hyperextension Bench', 'lower_back', '{glutes,hamstrings}', 'body_only', 'reps', 'Hyperextensions_With_No_Hyperextension_Bench', array['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.','With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.','Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.','Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.','Repeat for the recommended amount of repetitions.']::text[]),
  ('incline-barbell-triceps-extension', 'Incline Barbell Triceps Extension', 'triceps', '{forearms}', 'barbell', 'reps', 'Incline_Barbell_Triceps_Extension', array['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.','Lie back on an incline bench set at any angle between 45-75-degrees.','Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.','Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.','Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.','Repeat for the recommended amount of repetitions.']::text[]),
  ('incline-bench-pull', 'Incline Bench Pull', 'middle_back', '{lats,shoulders}', 'barbell', 'reps', 'Incline_Bench_Pull', array['Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.','Let the arms hang to your sides fully extended as they point to the floor.','Turn the wrists until your hands have a pronated (palms down) grip.','Now flare the elbows out. This will be your starting position.','As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter "T" at the top of the movement. Hold the contraction at the top for a second.','Slowly go back down to the starting position as you breathe in.']::text[]),
  ('incline-cable-chest-press', 'Incline Cable Chest Press', 'chest', '{shoulders,triceps}', 'cable', 'reps', 'Incline_Cable_Chest_Press', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.','After pausing at full extension, return to the starting position, keeping tension on the cables.']::text[]),
  ('incline-cable-flye', 'Incline Cable Flye', 'chest', '{shoulders}', 'cable', 'reps', 'Incline_Cable_Flye', array['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).','Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.','With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.','With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('incline-dumbbell-bench-with-palms-facing-in', 'Incline Dumbbell Bench With Palms Facing In', 'chest', '{shoulders,triceps}', 'dumbbell', 'reps', 'Incline_Dumbbell_Bench_With_Palms_Facing_In', array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.','Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.','Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('incline-dumbbell-flyes', 'Incline Dumbbell Flyes', 'chest', '{shoulders}', 'dumbbell', 'reps', 'Incline_Dumbbell_Flyes', array['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.','Extend your arms above you with a slight bend at the elbows.','Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.','As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.','As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.','Repeat for the recommended amount of repetitions.']::text[]),
  ('incline-dumbbell-flyes-with-a-twist', 'Incline Dumbbell Flyes - With A Twist', 'chest', '{shoulders}', 'dumbbell', 'reps', 'Incline_Dumbbell_Flyes_-_With_A_Twist', array['Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.','Extend your arms above you with a slight bend at the elbows.','Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.','As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.','As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.','Repeat for the recommended amount of repetitions.']::text[]),
  ('incline-hammer-curls', 'Incline Hammer Curls', 'biceps', '{}', 'dumbbell', 'reps', 'Incline_Hammer_Curls', array['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.','Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.','Continue to the top of the movement and pause, then slowly return to the start position.']::text[]),
  ('incline-inner-biceps-curl', 'Incline Inner Biceps Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Incline_Inner_Biceps_Curl', array['Hold a dumbbell in each hand and lie back on an incline bench.','The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.','Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.','After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.','Repeat for the recommended amount of repetitions.']::text[]),
  ('incline-push-up', 'Incline Push-Up', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Incline_Push-Up', array['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.','Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.','Push body up until arms are extended. Repeat.']::text[]),
  ('incline-push-up-close-grip', 'Incline Push-Up Close-Grip', 'triceps', '{chest,shoulders}', 'body_only', 'reps', 'Incline_Push-Up_Close-Grip', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands next to one another on the bar.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('incline-push-up-depth-jump', 'Incline Push-Up Depth Jump', 'chest', '{shoulders,triceps}', 'other', 'reps', 'Incline_Push-Up_Depth_Jump', array['For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.','Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.','Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.','Repeat the motion to return to the starting position.']::text[]),
  ('incline-push-up-medium', 'Incline Push-Up Medium', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Incline_Push-Up_Medium', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar, with your hands about shoulder width apart.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('incline-push-up-reverse-grip', 'Incline Push-Up Reverse Grip', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Incline_Push-Up_Reverse_Grip', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar palms up, with your hands about shoulder width apart.','Position your feet back from the bar with arms and body straight. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('incline-push-up-wide', 'Incline Push-Up Wide', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Incline_Push-Up_Wide', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.','Place your hands on the bar, with your hands wider than shoulder width.','Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.','Keeping your body straight, lower your chest to the bar by bending the arms.','Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('internal-rotation-with-band', 'Internal Rotation with Band', 'shoulders', '{}', 'bands', 'reps', 'Internal_Rotation_with_Band', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.','Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.','With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.','Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.','Continue as far as you are able, pause, and then return to the starting position.']::text[]),
  ('inverted-row', 'Inverted Row', 'middle_back', '{lats}', 'body_only', 'reps', 'Inverted_Row', array['Position a bar in a rack to about waist height. You can also use a smith machine.','Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.','Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.','Pause at the top of the motion, and return yourself to the start position.','Repeat for the desired number of repetitions.']::text[]),
  ('inverted-row-with-straps', 'Inverted Row with Straps', 'middle_back', '{biceps,lats}', 'other', 'reps', 'Inverted_Row_with_Straps', array['Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.','Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.','Pause at the top of the motion, and return yourself to the start position.','Repeat for the desired number of repetitions.']::text[]),
  ('iron-cross', 'Iron Cross', 'shoulders', '{chest,glutes,hamstrings,lower_back,quadriceps,traps}', 'dumbbell', 'reps', 'Iron_Cross', '{}'::text[]),
  ('isometric-chest-squeezes', 'Isometric Chest Squeezes', 'chest', '{shoulders,triceps}', 'body_only', 'time', 'Isometric_Chest_Squeezes', array['While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).','Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.','Hold for the recommended number of seconds.','Now release the tension slowly.','Rest for the recommended amount of time and repeat.']::text[]),
  ('isometric-neck-exercise-front-and-back', 'Isometric Neck Exercise - Front And Back', 'neck', '{}', 'body_only', 'time', 'Isometric_Neck_Exercise_-_Front_And_Back', array['With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.','Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.','Hold for the recommended number of seconds.','Now release the tension slowly.','Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.']::text[]),
  ('isometric-neck-exercise-sides', 'Isometric Neck Exercise - Sides', 'neck', '{}', 'body_only', 'time', 'Isometric_Neck_Exercise_-_Sides', array['With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.','Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.','Hold for the recommended number of seconds.','Now release the tension slowly.','Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head.']::text[]),
  ('isometric-wipers', 'Isometric Wipers', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Isometric_Wipers', array['Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.','Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.','Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.','Repeat for the desired number of repetitions.']::text[]),
  ('jm-press', 'JM Press', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'JM_Press', array['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.','Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.','As you exhale, press the bar back up by using the triceps to perform a close grip bench press.','Now go back to the starting position and start over.','Repeat for the recommended amount of repetitions.']::text[]),
  ('jackknife-sit-up', 'Jackknife Sit-Up', 'abdominals', '{}', 'body_only', 'reps', 'Jackknife_Sit-Up', array['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.','As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.','While inhaling, lower your arms and legs back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('janda-sit-up', 'Janda Sit-Up', 'abdominals', '{}', 'body_only', 'reps', 'Janda_Sit-Up', array['Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.','As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.','As you inhale, slowly go back in a controlled manner to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('jefferson-squats', 'Jefferson Squats', 'quadriceps', '{calves,glutes,hamstrings,lower_back,traps}', 'barbell', 'reps', 'Jefferson_Squats', array['Place a barbell on the floor.','Stand in the middle of the bar length wise.','Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.','Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).','Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.','Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.']::text[]),
  ('jerk-balance', 'Jerk Balance', 'shoulders', '{glutes,hamstrings,quadriceps,triceps}', 'barbell', 'reps', 'Jerk_Balance', array['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.','Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.','Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.']::text[]),
  ('jerk-dip-squat', 'Jerk Dip Squat', 'quadriceps', '{abdominals,calves}', 'barbell', 'reps', 'Jerk_Dip_Squat', array['This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.','Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.']::text[]),
  ('jogging-treadmill', 'Jogging, Treadmill', 'quadriceps', '{glutes,hamstrings}', 'machine', 'cardio', 'Jogging_Treadmill', array['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.','Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[]),
  ('keg-load', 'Keg Load', 'lower_back', '{abdominals,biceps,calves,forearms,glutes,hamstrings,middle_back,quadriceps,shoulders,traps}', 'other', 'reps', 'Keg_Load', array['To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.','Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.','The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.','Return to the starting position to retrieve the next keg, and repeat until the event is completed.']::text[]),
  ('kettlebell-arnold-press', 'Kettlebell Arnold Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'Kettlebell_Arnold_Press', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.','Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.','Return the kettlebell to the starting position, with the palm facing in.']::text[]),
  ('kettlebell-dead-clean', 'Kettlebell Dead Clean', 'hamstrings', '{calves,glutes,lower_back,quadriceps,traps}', 'kettlebells', 'reps', 'Kettlebell_Dead_Clean', array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.','Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.']::text[]),
  ('kettlebell-figure-8', 'Kettlebell Figure 8', 'abdominals', '{hamstrings,shoulders}', 'kettlebells', 'reps', 'Kettlebell_Figure_8', array['Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.','Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.']::text[]),
  ('kettlebell-halo', 'Kettlebell Halo', 'shoulders', '{traps,middle_back,abdominals,triceps}', 'kettlebells', 'reps', null, array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.','Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.','Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.','Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.','Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.']::text[]),
  ('kettlebell-halo-with-overhead-extension', 'Kettlebell Halo with Overhead Extension', 'shoulders', '{triceps,traps,middle_back,abdominals}', 'kettlebells', 'reps', null, array['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.','Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.','From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.','Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.','Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.','Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.']::text[]),
  ('kettlebell-hang-clean', 'Kettlebell Hang Clean', 'hamstrings', '{calves,glutes,lower_back,shoulders,traps}', 'kettlebells', 'reps', 'Kettlebell_Hang_Clean', array['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.','Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.']::text[]),
  ('kettlebell-one-legged-deadlift', 'Kettlebell One-Legged Deadlift', 'hamstrings', '{glutes,lower_back}', 'kettlebells', 'reps', 'Kettlebell_One-Legged_Deadlift', array['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.','Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.','Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.']::text[]),
  ('kettlebell-overhead-triceps-extension', 'Kettlebell Overhead Triceps Extension', 'triceps', '{shoulders,abdominals}', 'kettlebells', 'reps', null, array['Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.','Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.','Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.','Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.','Keep your ribcage down and avoid arching your lower back as you extend.']::text[]),
  ('kettlebell-pass-between-the-legs', 'Kettlebell Pass Between The Legs', 'abdominals', '{glutes,hamstrings,shoulders}', 'kettlebells', 'reps', 'Kettlebell_Pass_Between_The_Legs', array['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.','Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[]),
  ('kettlebell-pirate-ships', 'Kettlebell Pirate Ships', 'shoulders', '{abdominals}', 'kettlebells', 'reps', 'Kettlebell_Pirate_Ships', array['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.','Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.','Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.','Repeat for the desired amount of repetitions.']::text[]),
  ('kettlebell-pistol-squat', 'Kettlebell Pistol Squat', 'quadriceps', '{calves,glutes,hamstrings,shoulders}', 'kettlebells', 'reps', 'Kettlebell_Pistol_Squat', array['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.','Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.','Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.','Lower yourself again and repeat.']::text[]),
  ('kettlebell-seated-press', 'Kettlebell Seated Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'Kettlebell_Seated_Press', array['Sit on the floor and spread your legs out comfortably.','Clean one kettlebell to your shoulder.','Press the kettlebell up and out until it is locked out overhead. Return to the starting position.']::text[]),
  ('kettlebell-seesaw-press', 'Kettlebell Seesaw Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'Kettlebell_Seesaw_Press', array['Clean two kettlebells two your shoulders.','Press one kettlebell.','Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.']::text[]),
  ('kettlebell-sumo-high-pull', 'Kettlebell Sumo High Pull', 'traps', '{adductors,glutes,hamstrings,quadriceps,shoulders}', 'kettlebells', 'reps', 'Kettlebell_Sumo_High_Pull', array['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.','Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.']::text[]),
  ('kettlebell-thruster', 'Kettlebell Thruster', 'shoulders', '{quadriceps,triceps}', 'kettlebells', 'reps', 'Kettlebell_Thruster', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.','Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.','At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.','As you begin the next repetition, return the weights to the shoulders.']::text[]),
  ('kettlebell-turkish-get-up-lunge-style', 'Kettlebell Turkish Get-Up (Lunge style)', 'shoulders', '{abdominals,hamstrings,quadriceps,triceps}', 'kettlebells', 'reps', 'Kettlebell_Turkish_Get-Up_Lunge_style', array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.','Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.','While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[]),
  ('kettlebell-turkish-get-up-squat-style', 'Kettlebell Turkish Get-Up (Squat style)', 'shoulders', '{abdominals,calves,hamstrings,quadriceps,triceps}', 'kettlebells', 'reps', 'Kettlebell_Turkish_Get-Up_Squat_style', array['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.','Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.','Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[]),
  ('kettlebell-windmill', 'Kettlebell Windmill', 'abdominals', '{glutes,hamstrings,shoulders,triceps}', 'kettlebells', 'reps', 'Kettlebell_Windmill', array['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after reaching the ground and reverse the motion back to the starting position.']::text[]),
  ('kipping-muscle-up', 'Kipping Muscle Up', 'lats', '{abdominals,biceps,forearms,middle_back,shoulders,traps,triceps}', 'other', 'reps', 'Kipping_Muscle_Up', array['Grip the rings using a false grip, with the base of your palms on top of the rings.','Begin with a movement swinging your legs backward slightly.','Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.','Maintaining control and stability, extend through the elbow to complete the motion.','Use care when lowering yourself to the ground.']::text[]),
  ('knee-hip-raise-on-parallel-bars', 'Knee/Hip Raise On Parallel Bars', 'abdominals', '{}', 'other', 'reps', 'Knee_Hip_Raise_On_Parallel_Bars', array['Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.','The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.','Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.','Slowly go back to the starting position as you breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('knee-tuck-jump', 'Knee Tuck Jump', 'hamstrings', '{abductors,adductors,calves,glutes,quadriceps}', 'body_only', 'reps', 'Knee_Tuck_Jump', array['Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.','Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.','Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.']::text[]),
  ('kneeling-arm-drill', 'Kneeling Arm Drill', 'shoulders', '{abdominals}', 'body_only', 'reps', 'Kneeling_Arm_Drill', array['This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.','Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.','As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.','Switch knees and repeat.']::text[]),
  ('kneeling-cable-crunch-with-alternating-oblique-twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'abdominals', '{}', 'cable', 'reps', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', array['Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.','Grab the rope with both hands and kneel approximately two feet back from the tower.','Position the rope behind your head with your hands by your ears.','Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.','Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.','Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.']::text[]),
  ('kneeling-cable-triceps-extension', 'Kneeling Cable Triceps Extension', 'triceps', '{}', 'cable', 'reps', 'Kneeling_Cable_Triceps_Extension', array['Place a bench sideways in front of a high pulley machine.','Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.','Face away from the machine and kneel.','Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.','While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.','Slowly return to the starting position as you breathe in.']::text[]),
  ('kneeling-high-pulley-row', 'Kneeling High Pulley Row', 'lats', '{biceps,middle_back}', 'cable', 'reps', 'Kneeling_High_Pulley_Row', array['Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.','Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.','After pausing briefly, slowly return to the starting position.']::text[]),
  ('kneeling-jump-squat', 'Kneeling Jump Squat', 'glutes', '{calves,hamstrings,quadriceps}', 'barbell', 'reps', 'Kneeling_Jump_Squat', array['Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.','Sit back with your hips until your glutes touch your feet, keeping your head and chest up.','Explode up with your hips, generating enough power to land with your feet flat on the floor.','Continue with the squat by driving through your heels and extending the knees to come to a standing position.']::text[]),
  ('kneeling-single-arm-high-pulley-row', 'Kneeling Single-Arm High Pulley Row', 'lats', '{biceps,middle_back}', 'cable', 'reps', 'Kneeling_Single-Arm_High_Pulley_Row', array['Attach a single handle to a high pulley and make your weight selection.','Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.','Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.','After a brief pause, return to the starting position.']::text[]),
  ('kneeling-squat', 'Kneeling Squat', 'glutes', '{abdominals,hamstrings,lower_back}', 'barbell', 'reps', 'Kneeling_Squat', array['Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.','With your head looking forward, sit back with your butt until you touch your calves.','Reverse the motion, returning the torso to an upright position.']::text[]),
  ('landmine-180s', 'Landmine 180''s', 'abdominals', '{glutes,lower_back,shoulders}', 'barbell', 'reps', 'Landmine_180s', array['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.','Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.','Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.','Reverse the motion to swing the weight all the way to the opposite side.','Continue alternating the movement until the set is complete.']::text[]),
  ('landmine-linear-jammer', 'Landmine Linear Jammer', 'shoulders', '{abdominals,calves,chest,hamstrings,quadriceps,triceps}', 'barbell', 'reps', 'Landmine_Linear_Jammer', array['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.','Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.','In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.','Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.','Return to the starting position.']::text[]),
  ('lateral-bound', 'Lateral Bound', 'adductors', '{abductors,calves,glutes,hamstrings,quadriceps}', 'body_only', 'reps', 'Lateral_Bound', array['Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.','Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.','Immediately push off and extend, attempting to bound to the side as far as possible.','Upon landing, immediately push off in the opposite direction, returning to your original start position.','Continue back and forth for several repetitions.']::text[]),
  ('lateral-box-jump', 'Lateral Box Jump', 'adductors', '{abductors,calves,glutes,hamstrings,quadriceps}', 'other', 'reps', 'Lateral_Box_Jump', array['Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.','Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.','Bring your knees high enough to ensure your feet have good clearance over the box.','Land on the center of the box, using your legs to absorb the impact.','Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.']::text[]),
  ('lateral-cone-hops', 'Lateral Cone Hops', 'adductors', '{abductors,calves,glutes,hamstrings,quadriceps}', 'other', 'reps', 'Lateral_Cone_Hops', array['Position a number of cones in a row several feet apart.','Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.','Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.','Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.']::text[]),
  ('lateral-raise-with-bands', 'Lateral Raise - With Bands', 'shoulders', '{}', 'bands', 'reps', 'Lateral_Raise_-_With_Bands', array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('leg-over-floor-press', 'Leg-Over Floor Press', 'chest', '{shoulders,triceps}', 'kettlebells', 'reps', 'Leg-Over_Floor_Press', array['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.','Press the kettlebll into a locked out position.','Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.']::text[]),
  ('leg-lift', 'Leg Lift', 'glutes', '{hamstrings}', 'body_only', 'reps', 'Leg_Lift', array['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.','With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.','Slowly bring the raised leg back to the floor as you breathe in.','Repeat for the recommended amount of repetitions.','Repeat the movement with the opposite leg.']::text[]),
  ('leg-pull-in', 'Leg Pull-In', 'abdominals', '{}', 'body_only', 'reps', 'Leg_Pull-In', array['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.','Return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('leverage-deadlift', 'Leverage Deadlift', 'quadriceps', '{glutes,hamstrings}', 'machine', 'reps', 'Leverage_Deadlift', array['Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.','Return the weight to the starting position.']::text[]),
  ('leverage-decline-chest-press', 'Leverage Decline Chest Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Leverage_Decline_Chest_Press', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
  ('leverage-high-row', 'Leverage High Row', 'middle_back', '{lats}', 'machine', 'reps', 'Leverage_High_Row', array['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.','Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handles to the starting position.','For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[]),
  ('leverage-incline-chest-press', 'Leverage Incline Chest Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Leverage_Incline_Chest_Press', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.','Press the handles forward by extending through the elbow.','After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
  ('leverage-shoulder-press', 'Leverage Shoulder Press', 'shoulders', '{triceps}', 'machine', 'reps', 'Leverage_Shoulder_Press', array['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.','Press the handles upward by extending through the elbow.','After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[]),
  ('leverage-shrug', 'Leverage Shrug', 'traps', '{forearms}', 'machine', 'reps', 'Leverage_Shrug', array['Load the pins to an appropriate weight. Position yourself directly between the handles.','Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.','Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.','Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.','Pause at the top of the motion, and then return the weight to the starting position.']::text[]),
  ('linear-3-part-start-technique', 'Linear 3-Part Start Technique', 'hamstrings', '{calves,quadriceps}', 'body_only', 'reps', 'Linear_3-Part_Start_Technique', array['This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.','Place your right hand onto the line, and thing bring your nose close to your left knee.','Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.','Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.']::text[]),
  ('linear-acceleration-wall-drill', 'Linear Acceleration Wall Drill', 'hamstrings', '{calves,glutes,quadriceps}', 'body_only', 'reps', 'Linear_Acceleration_Wall_Drill', array['Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.','Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.','Switch legs, raising the opposite knee, and then attacking the ground straight down.','Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.']::text[]),
  ('linear-depth-jump', 'Linear Depth Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'reps', 'Linear_Depth_Jump', array['You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.','To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.','Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.','Land softly, asborbing the impact through the legs.']::text[]),
  ('log-lift', 'Log Lift', 'shoulders', '{abdominals,chest,glutes,hamstrings,lower_back,middle_back,quadriceps,traps,triceps}', 'other', 'reps', 'Log_Lift', array['Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.','Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.','Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground.']::text[]),
  ('london-bridges', 'London Bridges', 'lats', '{biceps,forearms,middle_back}', 'other', 'reps', 'London_Bridges', array['Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.','Stand on the bar, using the rope to balance yourself. This will be your starting position.','Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.','Keeping your body straight, reverse the motion, going hand over hand back to the starting position.']::text[]),
  ('low-cable-crossover', 'Low Cable Crossover', 'chest', '{shoulders}', 'cable', 'reps', 'Low_Cable_Crossover', array['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.','Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.','With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.','Return your arms back to the starting position after a brief pause.']::text[]),
  ('low-cable-triceps-extension', 'Low Cable Triceps Extension', 'triceps', '{}', 'cable', 'reps', 'Low_Cable_Triceps_Extension', array['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.','Grab the outside of the rope ends with your palms facing each other (neutral grip).','Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.','As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.','As you breathe in slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('low-pulley-row-to-neck', 'Low Pulley Row To Neck', 'shoulders', '{biceps,middle_back,traps}', 'cable', 'reps', 'Low_Pulley_Row_To_Neck', array['Sit on a low pulley row machine with a rope attachment.','Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.','While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.','After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lunge-pass-through', 'Lunge Pass Through', 'hamstrings', '{calves,glutes,quadriceps}', 'kettlebells', 'reps', 'Lunge_Pass_Through', array['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.','Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.','As you lunge, pass the kettlebell under your front leg to your opposite hand.','Pressing through the heel of your foot, return to the starting position.','Repeat the movement for the recommended amount of repetitions, alternating legs.']::text[]),
  ('lunge-sprint', 'Lunge Sprint', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Lunge_Sprint', array['Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.','Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.','At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-cable-curl', 'Lying Cable Curl', 'biceps', '{}', 'cable', 'reps', 'Lying_Cable_Curl', array['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.','Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.','With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.','While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.','After a second squeeze at the top of the movement, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-cambered-barbell-row', 'Lying Cambered Barbell Row', 'middle_back', '{biceps,lats,traps}', 'barbell', 'reps', 'Lying_Cambered_Barbell_Row', array['Place a cambered bar underneath an exercise bench.','Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.','As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.','After a second hold at the top, lower back down to the starting position slowly as you inhale.']::text[]),
  ('lying-close-grip-bar-curl-on-high-pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'biceps', '{}', 'cable', 'reps', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley', array['Place a flat bench in front of a high pulley or lat pulldown machine.','Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.','Lie on your back with your head over the end of the bench.','Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.','As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.','Return to starting position slowly.']::text[]),
  ('lying-close-grip-barbell-triceps-extension-behind-the-head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'triceps', '{}', 'barbell', 'reps', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.','Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.','As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.','As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-close-grip-barbell-triceps-press-to-chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'triceps', '{}', 'ez_curl_bar', 'reps', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', array['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.','Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.','As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.','As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-dumbbell-tricep-extension', 'Lying Dumbbell Tricep Extension', 'triceps', '{chest,shoulders}', 'dumbbell', 'reps', 'Lying_Dumbbell_Tricep_Extension', array['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.','As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.','At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-face-down-plate-neck-resistance', 'Lying Face Down Plate Neck Resistance', 'neck', '{}', 'other', 'reps', 'Lying_Face_Down_Plate_Neck_Resistance', array['Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.','While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in.','Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-face-up-plate-neck-resistance', 'Lying Face Up Plate Neck Resistance', 'neck', '{}', 'other', 'reps', 'Lying_Face_Up_Plate_Neck_Resistance', array['Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.','While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.','Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-high-bench-barbell-curl', 'Lying High Bench Barbell Curl', 'biceps', '{}', 'barbell', 'reps', 'Lying_High_Bench_Barbell_Curl', array['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.','While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.','As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-machine-squat', 'Lying Machine Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Lying_Machine_Squat', array['Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.','Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.','Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.','While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.','Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-one-arm-lateral-raise', 'Lying One-Arm Lateral Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Lying_One-Arm_Lateral_Raise', array['While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.','Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.','Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbell to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('lying-rear-delt-raise', 'Lying Rear Delt Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Lying_Rear_Delt_Raise', array['While holding a dumbbell in each hand, lay with your chest down on a flat bench.','Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.','Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.','Slowly lower the dumbbells to the starting position as you inhale.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[]),
  ('lying-supine-dumbbell-curl', 'Lying Supine Dumbbell Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Lying_Supine_Dumbbell_Curl', array['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.','Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).','While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.','As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.','Return back to the starting position very slowly.']::text[]),
  ('lying-t-bar-row', 'Lying T-Bar Row', 'middle_back', '{biceps,lats}', 'machine', 'reps', 'Lying_T-Bar_Row', array['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.','Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.','Lift the bar off the rack and extend your arms in front of you. This will be your starting position.','As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.','After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('machine-bench-press', 'Machine Bench Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Machine_Bench_Press', array['Sit down on the Chest Press Machine and select the weight.','Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.','Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.','Now bring the handles back towards you as you breathe in.','Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.','Repeat for the recommended amount of reps.']::text[]),
  ('machine-bicep-curl', 'Machine Bicep Curl', 'biceps', '{}', 'machine', 'reps', 'Machine_Bicep_Curl', array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.','Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.','Pause at the top of the movement, and then slowly return the weight to the starting position.','Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[]),
  ('machine-preacher-curls', 'Machine Preacher Curls', 'biceps', '{}', 'machine', 'reps', 'Machine_Preacher_Curls', array['Sit down on the Preacher Curl Machine and select the weight.','Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.','Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.','Lower the handles slowly back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('machine-triceps-extension', 'Machine Triceps Extension', 'triceps', '{}', 'machine', 'reps', 'Machine_Triceps_Extension', array['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.','Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.','Pause at the completion of the movement, and then slowly return the weight to the starting position.','Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[]),
  ('medicine-ball-chest-pass', 'Medicine Ball Chest Pass', 'chest', '{shoulders,triceps}', 'medicine_ball', 'reps', 'Medicine_Ball_Chest_Pass', array['You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.','Begin facing your partner holding the medicine ball at your torso with both hands.','Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.','Your partner should catch the ball, and throw it back to you.','Receive the throw with both hands at chest height.']::text[]),
  ('medicine-ball-full-twist', 'Medicine Ball Full Twist', 'abdominals', '{shoulders}', 'medicine_ball', 'reps', 'Medicine_Ball_Full_Twist', array['For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.','Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.','For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.','Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.']::text[]),
  ('medicine-ball-scoop-throw', 'Medicine Ball Scoop Throw', 'shoulders', '{abdominals,hamstrings,quadriceps}', 'medicine_ball', 'reps', 'Medicine_Ball_Scoop_Throw', array['Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.','Begin by thrusting the hips forward as you extend through the legs, jumping up.','As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.']::text[]),
  ('middle-back-shrug', 'Middle Back Shrug', 'middle_back', '{}', 'dumbbell', 'reps', 'Middle_Back_Shrug', array['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.','As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.','As you inhale go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('mixed-grip-chin', 'Mixed Grip Chin', 'middle_back', '{biceps,lats}', 'other', 'reps', 'Mixed_Grip_Chin', array['Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.','Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.','After a second contraction at the top, start to slowly come down as you inhale.','Repeat for the recommended amount of repetitions.','On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.']::text[]),
  ('monster-walk', 'Monster Walk', 'abductors', '{}', 'bands', 'reps', 'Monster_Walk', array['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.','To begin, take short steps forward alternating your left and right foot.','After several steps, do just the opposite and walk backward to where you started.']::text[]),
  ('mountain-climbers', 'Mountain Climbers', 'quadriceps', '{chest,hamstrings,shoulders}', 'body_only', 'reps', 'Mountain_Climbers', array['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.','Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[]),
  ('moving-claw-series', 'Moving Claw Series', 'hamstrings', '{calves,quadriceps}', 'body_only', 'reps', 'Moving_Claw_Series', array['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.','Reload the quad as the leg moves back forward, attacking the ground on the next step.','Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.']::text[]),
  ('muscle-snatch', 'Muscle Snatch', 'hamstrings', '{glutes,lower_back,quadriceps,shoulders,triceps}', 'barbell', 'reps', 'Muscle_Snatch', array['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.','Continue raising the bar to the overhead position, without rebending the knees.']::text[]),
  ('muscle-up', 'Muscle Up', 'lats', '{abdominals,biceps,forearms,middle_back,shoulders,traps,triceps}', 'other', 'reps', 'Muscle_Up', array['Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.','As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.','Maintaining control and stability, extend through the elbow to complete the motion.','Use care when lowering yourself to the ground.']::text[]),
  ('narrow-stance-hack-squats', 'Narrow Stance Hack Squats', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Narrow_Stance_Hack_Squats', array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.','Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.','Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).','Now straighten your legs without locking the knees. This will be your starting position.','Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.','Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.']::text[]),
  ('narrow-stance-leg-press', 'Narrow Stance Leg Press', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Narrow_Stance_Leg_Press', array['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.','Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[]),
  ('narrow-stance-squats', 'Narrow Stance Squats', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Narrow_Stance_Squats', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('natural-glute-ham-raise', 'Natural Glute Ham Raise', 'hamstrings', '{calves,glutes,lower_back}', 'body_only', 'reps', 'Natural_Glute_Ham_Raise', array['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.','This will be your starting position. Lower yourself under control until your knees are almost completely straight.','Remaining in control, raise yourself back up to the starting position.','If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.']::text[]),
  ('neck-press', 'Neck Press', 'chest', '{shoulders,triceps}', 'barbell', 'reps', 'Neck_Press', array['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your neck.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('oblique-crunches', 'Oblique Crunches', 'abdominals', '{}', 'body_only', 'reps', 'Oblique_Crunches', array['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.','Make sure your feet are elevated and resting on a flat surface.','Now lift the shoulder in which your hand is touching your head.','Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.','After your knee touches your elbow, lower your body until you have reached the starting position.','Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.']::text[]),
  ('oblique-crunches-on-the-floor', 'Oblique Crunches - On The Floor', 'abdominals', '{}', 'body_only', 'reps', 'Oblique_Crunches_-_On_The_Floor', array['Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.','Place your left hand behind your head.','Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.','Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.','Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.']::text[]),
  ('olympic-squat', 'Olympic Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Olympic_Squat', array['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.','Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.','At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.']::text[]),
  ('one-arm-flat-bench-dumbbell-flye', 'One-Arm Flat Bench Dumbbell Flye', 'chest', '{}', 'dumbbell', 'reps', 'One-Arm_Flat_Bench_Dumbbell_Flye', array['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.','By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.','Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.','Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.','Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('one-arm-high-pulley-cable-side-bends', 'One-Arm High-Pulley Cable Side Bends', 'abdominals', '{}', 'cable', 'reps', 'One-Arm_High-Pulley_Cable_Side_Bends', array['Connect a standard handle to a tower. Move cable to highest pulley position.','Stand with side to cable. With one hand, reach up and grab handle with underhand grip.','Pull down cable until elbow touches your side and the handle is by your shoulder.','Position feet hip-width apart. Place free hand on hip to help gauge pivot point.','Keep arm in static position. Contract oblique to bring the weight down in a side crunch.','Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.']::text[]),
  ('one-arm-incline-lateral-raise', 'One-Arm Incline Lateral Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'One-Arm_Incline_Lateral_Raise', array['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.','Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.','While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.','While inhaling lower the weight across your body back into the starting position.','Repeat the movement for the prescribed amount of repetitions.','Switch arms and repeat the movement.']::text[]),
  ('one-arm-kettlebell-clean', 'One-Arm Kettlebell Clean', 'hamstrings', '{glutes,lower_back,shoulders,traps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Clean', array['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.','Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.','Return the weight to the starting position.']::text[]),
  ('one-arm-kettlebell-clean-and-jerk', 'One-Arm Kettlebell Clean and Jerk', 'shoulders', '{}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Clean_and_Jerk', array['Hold a kettlebell by the handle.','Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.','Receive the weight overhead by returning to a squat position underneath the weight.','Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.']::text[]),
  ('one-arm-kettlebell-floor-press', 'One-Arm Kettlebell Floor Press', 'chest', '{triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Floor_Press', array['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.','Press the kettlebell straight up toward the ceiling, rotating your wrist.','Lower the kettlebell back to the starting position and repeat.']::text[]),
  ('one-arm-kettlebell-jerk', 'One-Arm Kettlebell Jerk', 'shoulders', '{calves,quadriceps,triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Jerk', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.','Lower the weight to perform the next repetition.']::text[]),
  ('one-arm-kettlebell-military-press-to-the-side', 'One-Arm Kettlebell Military Press To The Side', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Military_Press_To_The_Side', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.','Look at the kettlebell and press it up and out until it is locked out overhead.','Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
  ('one-arm-kettlebell-para-press', 'One-Arm Kettlebell Para Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Para_Press', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.','Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[]),
  ('one-arm-kettlebell-push-press', 'One-Arm Kettlebell Push Press', 'shoulders', '{calves,quadriceps,triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Push_Press', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition.']::text[]),
  ('one-arm-kettlebell-row', 'One-Arm Kettlebell Row', 'middle_back', '{biceps,lats}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Row', array['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[]),
  ('one-arm-kettlebell-snatch', 'One-Arm Kettlebell Snatch', 'shoulders', '{calves,glutes,hamstrings,lower_back,traps,triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Snatch', array['Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.','Look straight ahead and swing the kettlebell back between your legs.','Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.']::text[]),
  ('one-arm-kettlebell-split-jerk', 'One-Arm Kettlebell Split Jerk', 'shoulders', '{glutes,hamstrings,quadriceps,triceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Split_Jerk', array['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.','Dip your body by bending the knees, keeping your torso upright.','Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.','Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.','Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.']::text[]),
  ('one-arm-kettlebell-split-snatch', 'One-Arm Kettlebell Split Snatch', 'shoulders', '{hamstrings,quadriceps}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Split_Snatch', array['Hold a kettlebell in one hand by the handle.','Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.','After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.','Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.']::text[]),
  ('one-arm-kettlebell-swings', 'One-Arm Kettlebell Swings', 'hamstrings', '{calves,glutes,lower_back,shoulders}', 'kettlebells', 'reps', 'One-Arm_Kettlebell_Swings', '{}'::text[]),
  ('one-arm-long-bar-row', 'One-Arm Long Bar Row', 'middle_back', '{biceps,lats}', 'barbell', 'reps', 'One-Arm_Long_Bar_Row', array['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.','Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.','Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.','Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.','After a brief pause, return to the starting position.']::text[]),
  ('one-arm-medicine-ball-slam', 'One-Arm Medicine Ball Slam', 'abdominals', '{lats,shoulders}', 'medicine_ball', 'reps', 'One-Arm_Medicine_Ball_Slam', array['Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.','Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.','At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.','Catch the ball on the bounce and continue for the desired number of repetitions.']::text[]),
  ('one-arm-open-palm-kettlebell-clean', 'One-Arm Open Palm Kettlebell Clean', 'hamstrings', '{forearms,glutes,lower_back,quadriceps,shoulders}', 'kettlebells', 'reps', 'One-Arm_Open_Palm_Kettlebell_Clean', array['Place one kettlebell between your feet.','Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.','Throw the kettlebell out in front of you and catch the handle with one hand.','Take the kettlebell to the floor and repeat. Make sure to work both arms.']::text[]),
  ('one-arm-overhead-kettlebell-squats', 'One-Arm Overhead Kettlebell Squats', 'quadriceps', '{calves,glutes,hamstrings,shoulders}', 'kettlebells', 'reps', 'One-Arm_Overhead_Kettlebell_Squats', array['Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.','Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.','Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.']::text[]),
  ('one-arm-side-deadlift', 'One-Arm Side Deadlift', 'quadriceps', '{abdominals,calves,glutes,hamstrings,lower_back,traps}', 'barbell', 'reps', 'One-Arm_Side_Deadlift', array['Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.','Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.','Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.','Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[]),
  ('one-arm-side-laterals', 'One-Arm Side Laterals', 'shoulders', '{}', 'dumbbell', 'reps', 'One-Arm_Side_Laterals', array['Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.','Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbell back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('one-legged-cable-kickback', 'One-Legged Cable Kickback', 'glutes', '{hamstrings}', 'cable', 'reps', 'One-Legged_Cable_Kickback', array['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.','Face the weight stack from a distance of about two feet, grasping the steel frame for support.','While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.','Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.','Repeat for the recommended amount of repetitions.','Switch legs and repeat the movement for the other side.']::text[]),
  ('one-arm-chin-up', 'One Arm Chin-Up', 'middle_back', '{biceps,forearms,lats}', 'other', 'reps', 'One_Arm_Chin-Up', array['For this exercise, start out by placing a towel around a chin up bar.','Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.','Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('one-arm-dumbbell-bench-press', 'One Arm Dumbbell Bench Press', 'chest', '{shoulders,triceps}', 'dumbbell', 'reps', 'One_Arm_Dumbbell_Bench_Press', array['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.','By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.','Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.','Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.','As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
  ('one-arm-dumbbell-preacher-curl', 'One Arm Dumbbell Preacher Curl', 'biceps', '{}', 'dumbbell', 'reps', 'One_Arm_Dumbbell_Preacher_Curl', array['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.','Switch arms and repeat the movement.']::text[]),
  ('one-arm-floor-press', 'One Arm Floor Press', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'One_Arm_Floor_Press', array['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.','Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).','Make sure the hand you are not using to lift the weight is placed by your side.','Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).','Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your recommended repetitions.']::text[]),
  ('one-arm-lat-pulldown', 'One Arm Lat Pulldown', 'lats', '{biceps,middle_back}', 'cable', 'reps', 'One_Arm_Lat_Pulldown', array['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.','Pull the handle down, squeezing your elbow to your side as you flex the elbow.','Pause at the bottom of the motion, and then slowly return the handle to the starting position.','For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[]),
  ('one-arm-pronated-dumbbell-triceps-extension', 'One Arm Pronated Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'One_Arm_Pronated_Dumbbell_Triceps_Extension', array['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.','Place your non lifting hand on your bicep for support.','Slowly begin to lower the dumbbell down as you breathe in.','Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your set repetitions.','Switch arms and repeat the movement.']::text[]),
  ('one-arm-supinated-dumbbell-triceps-extension', 'One Arm Supinated Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'One_Arm_Supinated_Dumbbell_Triceps_Extension', array['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.','Place your non lifting hand on your bicep for support.','Slowly begin to lower the dumbbell down as you breathe in.','Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).','Repeat until you have performed your set repetitions.','Switch arms and repeat the movement.']::text[]),
  ('one-leg-barbell-squat', 'One Leg Barbell Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'One_Leg_Barbell_Squat', array['Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.','Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.','Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.','As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.','Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('open-palm-kettlebell-clean', 'Open Palm Kettlebell Clean', 'hamstrings', '{glutes,lower_back,quadriceps,shoulders}', 'kettlebells', 'reps', 'Open_Palm_Kettlebell_Clean', array['Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.','Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.','Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.']::text[]),
  ('otis-up', 'Otis-Up', 'abdominals', '{chest,shoulders,triceps}', 'other', 'reps', 'Otis-Up', array['Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.','Initiate the movement by flexing the hips and spine to raise your torso up from the ground.','As you move up, press the weight up so that it is above your head at the top of the movement.','Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.']::text[]),
  ('overhead-cable-curl', 'Overhead Cable Curl', 'biceps', '{}', 'cable', 'reps', 'Overhead_Cable_Curl', array['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.','Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.','Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.','While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.','While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
  ('overhead-slam', 'Overhead Slam', 'lats', '{}', 'medicine_ball', 'reps', 'Overhead_Slam', array['Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.','Initiate the countermovement by raising the ball above your head and fully extending your body.','Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.','Receive the ball with both hands on the bounce and repeat the movement.']::text[]),
  ('overhead-squat', 'Overhead Squat', 'quadriceps', '{abdominals,calves,glutes,hamstrings,lower_back,shoulders,triceps}', 'barbell', 'reps', 'Overhead_Squat', array['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.','Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.','Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.','Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.','Now use your feet and legs to help bring the weight back up to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('pallof-press', 'Pallof Press', 'abdominals', '{chest,shoulders,triceps}', 'cable', 'reps', 'Pallof_Press', array['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.','With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.','Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.','Hold the repetition for several seconds before returning to the starting position.','At the conclusion of the set, repeat facing the other direction.']::text[]),
  ('pallof-press-with-rotation', 'Pallof Press With Rotation', 'abdominals', '{chest,shoulders,triceps}', 'cable', 'reps', 'Pallof_Press_With_Rotation', array['Connect a standard handle to a tower, and position the cable to shoulder height.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.','With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.','Facing forward, press the cable away from your chest. You core should be tight and engaged.','Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.','Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.']::text[]),
  ('palms-down-dumbbell-wrist-curl-over-a-bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'forearms', '{}', 'dumbbell', 'reps', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', array['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[]),
  ('palms-down-wrist-curl-over-a-bench', 'Palms-Down Wrist Curl Over A Bench', 'forearms', '{}', 'barbell', 'reps', 'Palms-Down_Wrist_Curl_Over_A_Bench', array['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[]),
  ('palms-up-barbell-wrist-curl-over-a-bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'forearms', '{}', 'barbell', 'reps', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', array['Start out by placing a barbell on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[]),
  ('palms-up-dumbbell-wrist-curl-over-a-bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'forearms', '{}', 'dumbbell', 'reps', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', array['Start out by placing two dumbbells on one side of a flat bench.','Kneel down on both of your knees so that your body is facing the flat bench.','Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.']::text[]),
  ('parallel-bar-dip', 'Parallel Bar Dip', 'triceps', '{chest,shoulders}', 'other', 'reps', 'Parallel_Bar_Dip', array['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.','Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.','Reverse the motion by extending the elbow, pushing yourself back up into the starting position.','Repeat for the desired number of repetitions.']::text[]),
  ('physioball-hip-bridge', 'Physioball Hip Bridge', 'glutes', '{hamstrings}', 'exercise_ball', 'reps', 'Physioball_Hip_Bridge', array['Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.','Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.','Pause at the top of the motion and return to the starting position.']::text[]),
  ('pin-presses', 'Pin Presses', 'triceps', '{chest,forearms,lats,middle_back,shoulders}', 'barbell', 'reps', 'Pin_Presses', array['Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.','The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.','Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.','You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.','Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.','Return the bar to the pins, pausing before beginning the next repetition.']::text[]),
  ('plate-pinch', 'Plate Pinch', 'forearms', '{}', 'other', 'time', 'Plate_Pinch', array['Grab two wide-rimmed plates and put them together with the smooth sides facing outward','Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.','Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.','Repeat for the recommended amount of sets prescribed in your program.','Switch arms and repeat the movements.']::text[]),
  ('plate-twist', 'Plate Twist', 'abdominals', '{}', 'other', 'reps', 'Plate_Twist', array['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.','Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.','Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.','Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.','Repeat for the recommended amount of repetitions.']::text[]),
  ('platform-hamstring-slides', 'Platform Hamstring Slides', 'hamstrings', '{glutes}', 'other', 'reps', 'Platform_Hamstring_Slides', array['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.','Begin the movement by flexing the knee, keeping your other leg straight.','Continue bringing the heel closer to you, sliding it on the floor.','At full knee flexion, reverse the movement to return to the starting position.']::text[]),
  ('plie-dumbbell-squat', 'Plie Dumbbell Squat', 'quadriceps', '{abdominals,calves,glutes,hamstrings}', 'dumbbell', 'reps', 'Plie_Dumbbell_Squat', array['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.','Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.','Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.','Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('plyo-kettlebell-pushups', 'Plyo Kettlebell Pushups', 'chest', '{shoulders,triceps}', 'kettlebells', 'reps', 'Plyo_Kettlebell_Pushups', array['Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.','Begin by lowering yourself as low as you can, keeping your back straight.','Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.']::text[]),
  ('plyo-push-up', 'Plyo Push-up', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Plyo_Push-up', array['Move into a prone position on the floor, supporting your weight on your hands and toes.','Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','Descend by flexing at the elbow, lowering your chest towards the ground.','At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.','Return to the starting position and repeat the exercise.','For added difficulty, add claps into the movement while you are air borne.']::text[]),
  ('power-clean', 'Power Clean', 'hamstrings', '{calves,forearms,glutes,lower_back,middle_back,quadriceps,shoulders,traps,triceps}', 'barbell', 'reps', 'Power_Clean', array['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.','Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.','Place the bar about 1 inch in front of your shins and over the balls of your feet.','Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.','Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.','Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.']::text[]),
  ('power-clean-from-blocks', 'Power Clean from Blocks', 'hamstrings', '{quadriceps}', 'barbell', 'reps', 'Power_Clean_from_Blocks', array['With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.','In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes.']::text[]),
  ('power-jerk', 'Power Jerk', 'quadriceps', '{abdominals,calves,glutes,hamstrings,shoulders,triceps}', 'barbell', 'reps', 'Power_Jerk', array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.','Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.','Receive the bar with the arms locked out overhead.','Return to a standing position.']::text[]),
  ('power-partials', 'Power Partials', 'shoulders', '{}', 'dumbbell', 'reps', 'Power_Partials', array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.','Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.','Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.','Repeat for the recommended amount of repetitions.']::text[]),
  ('power-snatch', 'Power Snatch', 'hamstrings', '{calves,glutes,lower_back,quadriceps,shoulders,traps,triceps}', 'barbell', 'reps', 'Power_Snatch', array['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.','Return to a standing position with the weight over head.']::text[]),
  ('power-snatch-from-blocks', 'Power Snatch from Blocks', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back,shoulders,traps,triceps}', 'barbell', 'reps', 'Power_Snatch_from_Blocks', array['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the boxes.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.','Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[]),
  ('power-stairs', 'Power Stairs', 'hamstrings', '{adductors,calves,glutes,lower_back,quadriceps,shoulders,traps}', 'other', 'reps', 'Power_Stairs', array['In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.','Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.','As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.','Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.']::text[]),
  ('preacher-hammer-dumbbell-curl', 'Preacher Hammer Dumbbell Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Preacher_Hammer_Dumbbell_Curl', array['Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).','As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
  ('press-sit-up', 'Press Sit-Up', 'abdominals', '{chest,shoulders,triceps}', 'barbell', 'reps', 'Press_Sit-Up', array['To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.','While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.','Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.','Repeat for the recommended amount of repetitions.']::text[]),
  ('prone-manual-hamstring', 'Prone Manual Hamstring', 'hamstrings', '{}', 'body_only', 'reps', 'Prone_Manual_Hamstring', array['You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.','To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.','Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.']::text[]),
  ('prowler-sprint', 'Prowler Sprint', 'hamstrings', '{calves,chest,glutes,quadriceps,shoulders}', 'other', 'cardio', 'Prowler_Sprint', array['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.','You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.','With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[]),
  ('pull-through', 'Pull Through', 'glutes', '{hamstrings,lower_back}', 'cable', 'reps', 'Pull_Through', array['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.','Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[]),
  ('push-up-wide', 'Push-Up Wide', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Push-Up_Wide', array['With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.','To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.','After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('push-ups-close-triceps-position', 'Push-Ups - Close Triceps Position', 'triceps', '{chest,shoulders}', 'body_only', 'reps', 'Push-Ups_-_Close_Triceps_Position', array['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.','Lower yourself until your chest almost touches the floor as you inhale.','Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('push-ups-with-feet-elevated', 'Push-Ups With Feet Elevated', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Push-Ups_With_Feet_Elevated', array['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.','Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('push-ups-with-feet-on-an-exercise-ball', 'Push-Ups With Feet On An Exercise Ball', 'chest', '{shoulders,triceps}', 'exercise_ball', 'reps', 'Push-Ups_With_Feet_On_An_Exercise_Ball', array['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.','Place your toes on top of an exercise ball. This will allow your body to be elevated.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('push-press', 'Push Press', 'shoulders', '{quadriceps,triceps}', 'barbell', 'reps', 'Push_Press', '{}'::text[]),
  ('push-press-behind-the-neck', 'Push Press - Behind the Neck', 'shoulders', '{calves,quadriceps,triceps}', 'barbell', 'reps', 'Push_Press_-_Behind_the_Neck', array['Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.','Using the momentum generated, finish pressing the weight overhead be extending through the arms.','Return to the starting position, using your legs to absorb the impact.']::text[]),
  ('push-up-to-side-plank', 'Push Up to Side Plank', 'chest', '{abdominals,shoulders,triceps}', 'body_only', 'reps', 'Push_Up_to_Side_Plank', array['Get into pushup position on the toes with your hands just outside of shoulder width.','Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.','Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.','Lower the arm back to the floor for another pushup and then twist to the other side.','Repeat the series, alternating each side, for 10 or more reps.']::text[]),
  ('pushups-close-and-wide-hand-positions', 'Pushups (Close and Wide Hand Positions)', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Pushups_Close_and_Wide_Hand_Positions', array['Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.','Lower yourself until your chest almost touches the floor as you inhale.','Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.','After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('quick-leap', 'Quick Leap', 'quadriceps', '{calves,hamstrings}', 'other', 'reps', 'Quick_Leap', array['You will need a box for this exerise.','Begin facing the box standing 1-2 feet from its edge.','By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.','Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.']::text[]),
  ('rack-delivery', 'Rack Delivery', 'shoulders', '{forearms,traps}', 'barbell', 'reps', 'Rack_Delivery', array['This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.','Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.','It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further.']::text[]),
  ('rack-pull-with-bands', 'Rack Pull with Bands', 'lower_back', '{forearms,glutes,hamstrings,quadriceps,traps}', 'barbell', 'reps', 'Rack_Pull_with_Bands', array['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.','Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.','With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.']::text[]),
  ('recumbent-bike', 'Recumbent Bike', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'cardio', 'Recumbent_Bike', array['To begin, seat yourself on the bike and adjust the seat to your height.','Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.','Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.']::text[]),
  ('return-push-from-stance', 'Return Push from Stance', 'shoulders', '{chest,triceps}', 'medicine_ball', 'reps', 'Return_Push_from_Stance', array['You will need a partner for this drill.','Begin in an athletic 2 or 3 point stance.','At the signal, move into a position to receive the pass from your partner.','Catch the medicine ball with both hands and immediately throw it back to your partner.','You can modify this drill by running different routes.']::text[]),
  ('reverse-band-bench-press', 'Reverse Band Bench Press', 'triceps', '{chest,forearms,lats,middle_back,shoulders}', 'barbell', 'reps', 'Reverse_Band_Bench_Press', array['Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.','Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.','Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.','Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[]),
  ('reverse-band-box-squat', 'Reverse Band Box Squat', 'quadriceps', '{abductors,adductors,calves,forearms,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Reverse_Band_Box_Squat', array['Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[]),
  ('reverse-band-deadlift', 'Reverse Band Deadlift', 'lower_back', '{abductors,adductors,calves,glutes,hamstrings,quadriceps}', 'barbell', 'reps', 'Reverse_Band_Deadlift', array['Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.','Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','Lower the bar by bending at the hips and guiding it to the floor.']::text[]),
  ('reverse-band-power-squat', 'Reverse Band Power Squat', 'quadriceps', '{adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Reverse_Band_Power_Squat', array['Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.','Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.','Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[]),
  ('reverse-band-sumo-deadlift', 'Reverse Band Sumo Deadlift', 'hamstrings', '{abductors,adductors,calves,forearms,glutes,lower_back,quadriceps,traps}', 'barbell', 'reps', 'Reverse_Band_Sumo_Deadlift', array['Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.','Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
  ('reverse-barbell-curl', 'Reverse Barbell Curl', 'biceps', '{forearms}', 'barbell', 'reps', 'Reverse_Barbell_Curl', array['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-barbell-preacher-curls', 'Reverse Barbell Preacher Curls', 'biceps', '{forearms}', 'ez_curl_bar', 'reps', 'Reverse_Barbell_Preacher_Curls', array['Grab an EZ-bar using a shoulder width and palms down (pronated) grip.','Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.','As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.','As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-cable-curl', 'Reverse Cable Curl', 'biceps', '{forearms}', 'cable', 'reps', 'Reverse_Cable_Curl', array['Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-crunch', 'Reverse Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Reverse_Crunch', array['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.','Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.','While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-flyes', 'Reverse Flyes', 'shoulders', '{}', 'dumbbell', 'reps', 'Reverse_Flyes', array['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).','Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.','Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.','The arms should be elevated until they are parallel to the floor.','Feel the contraction and slowly lower the weights back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-flyes-with-external-rotation', 'Reverse Flyes With External Rotation', 'shoulders', '{}', 'dumbbell', 'reps', 'Reverse_Flyes_With_External_Rotation', array['To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.','Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.','Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.','As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.','The arms should be elevated until they are level with the head.','Feel the contraction and slowly lower the weights back down to the starting position while inhaling.']::text[]),
  ('reverse-grip-bent-over-rows', 'Reverse Grip Bent-Over Rows', 'middle_back', '{biceps,lats,shoulders}', 'barbell', 'reps', 'Reverse_Grip_Bent-Over_Rows', array['Stand erect while holding a barbell with a supinated grip (palms facing up).','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-hyperextension', 'Reverse Hyperextension', 'hamstrings', '{calves,glutes}', 'machine', 'reps', 'Reverse_Hyperextension', array['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.','To begin the movement, flex the hips, pulling the legs forward.','Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.','Return by again flexing the hip, pulling the carriage forward as far as you can.','Repeat for the desired number of repetitions.']::text[]),
  ('reverse-plate-curls', 'Reverse Plate Curls', 'biceps', '{forearms}', 'other', 'reps', 'Reverse_Plate_Curls', array['Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.','Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.','Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.','Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling','Repeat for the recommended amount of repetitions.']::text[]),
  ('reverse-triceps-bench-press', 'Reverse Triceps Bench Press', 'triceps', '{chest,shoulders}', 'barbell', 'reps', 'Reverse_Triceps_Bench_Press', array['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('rickshaw-carry', 'Rickshaw Carry', 'forearms', '{abdominals,calves,glutes,hamstrings,lower_back,quadriceps,traps}', 'other', 'time', 'Rickshaw_Carry', array['Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.','Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.']::text[]),
  ('rickshaw-deadlift', 'Rickshaw Deadlift', 'quadriceps', '{forearms,glutes,hamstrings,lower_back,traps}', 'other', 'reps', 'Rickshaw_Deadlift', array['Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.','With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.','Lower the weight by bending at the hips and guiding it to the ground.']::text[]),
  ('ring-dips', 'Ring Dips', 'triceps', '{chest,shoulders}', 'other', 'reps', 'Ring_Dips', array['Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.','Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.','Reverse the motion by extending the elbow, pushing yourself back up into the starting position.','Repeat for the desired number of repetitions.']::text[]),
  ('rocket-jump', 'Rocket Jump', 'quadriceps', '{calves,hamstrings}', 'body_only', 'reps', 'Rocket_Jump', array['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.','To initiate the move, squat down halfway and explode back up as high as possible.','Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.']::text[]),
  ('rocking-standing-calf-raise', 'Rocking Standing Calf Raise', 'calves', '{}', 'barbell', 'reps', 'Rocking_Standing_Calf_Raise', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.']::text[]),
  ('rocky-pull-ups-pulldowns', 'Rocky Pull-Ups/Pulldowns', 'lats', '{biceps,middle_back,shoulders}', 'other', 'reps', 'Rocky_Pull-Ups_Pulldowns', array['Grab the pull-up bar with the palms facing forward using a wide grip.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.','Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program.']::text[]),
  ('romanian-deadlift-from-deficit', 'Romanian Deadlift from Deficit', 'hamstrings', '{forearms,glutes,lower_back,traps}', 'barbell', 'reps', 'Romanian_Deadlift_from_Deficit', array['Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.','Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.','Reverse the motion to return to the starting position.']::text[]),
  ('rope-climb', 'Rope Climb', 'lats', '{biceps,forearms,middle_back,shoulders}', 'other', 'reps', 'Rope_Climb', array['Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.','Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.','Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.','Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.','To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.']::text[]),
  ('rope-crunch', 'Rope Crunch', 'abdominals', '{}', 'cable', 'reps', 'Rope_Crunch', array['Kneel 1-2 feet in front of a cable system with a rope attached.','After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.','To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.','Pause at the bottom of the motion, and then slowly return to the starting position.','These can be done with twists or to the side to hit the obliques.']::text[]),
  ('rope-straight-arm-pulldown', 'Rope Straight-Arm Pulldown', 'lats', '{}', 'cable', 'reps', 'Rope_Straight-Arm_Pulldown', array['Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.','Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.','Pause at the bottom of the motion, squeezing your lats.','Return to the starting position without allowing the weight to fully rest on the stack.']::text[]),
  ('sandbag-load', 'Sandbag Load', 'quadriceps', '{abdominals,biceps,calves,forearms,glutes,hamstrings,lower_back,middle_back,shoulders,traps}', 'other', 'reps', 'Sandbag_Load', array['To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.','Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.','Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.','Return to the starting position to retrieve the next sandbag, and repeat until the event is completed.']::text[]),
  ('scapular-pull-up', 'Scapular Pull-Up', 'traps', '{lats,middle_back}', 'body_only', 'reps', 'Scapular_Pull-Up', array['Take a pronated grip on a pull-up bar.','From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.','Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.']::text[]),
  ('scissors-jump', 'Scissors Jump', 'quadriceps', '{glutes,hamstrings}', 'body_only', 'reps', 'Scissors_Jump', array['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.','Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.','As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.','As you land, absorb the impact through the legs by adopting the lunge position, and repeat.']::text[]),
  ('seated-band-hamstring-curl', 'Seated Band Hamstring Curl', 'hamstrings', '{}', 'other', 'reps', 'Seated_Band_Hamstring_Curl', array['Secure a band close to the ground and place a bench a couple feet away from it.','Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.','Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.','Pause at the completion of the movement, and then slowly return to the starting position.']::text[]),
  ('seated-barbell-military-press', 'Seated Barbell Military Press', 'shoulders', '{triceps}', 'barbell', 'reps', 'Seated_Barbell_Military_Press', array['Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.','Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','Lower the bar down to the collarbone slowly as you inhale.','Lift the bar back up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-barbell-twist', 'Seated Barbell Twist', 'abdominals', '{}', 'barbell', 'reps', 'Seated_Barbell_Twist', array['Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.','Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.','Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.','While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.','Remember to breathe out while twisting your body to the side and in when moving back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-bent-over-one-arm-dumbbell-triceps-extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', array['Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.','The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.','Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.','After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('seated-bent-over-rear-delt-raise', 'Seated Bent-Over Rear Delt Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Seated_Bent-Over_Rear_Delt_Raise', array['Place a couple of dumbbells looking forward in front of a flat bench.','Sit on the end of the bench with your legs together and the dumbbells behind your calves.','Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.','Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)','After a one second contraction at the top, slowly lower the dumbbells back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-bent-over-two-arm-dumbbell-triceps-extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', array['Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.','The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.','Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.','After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('seated-cable-shoulder-press', 'Seated Cable Shoulder Press', 'shoulders', '{triceps}', 'cable', 'reps', 'Seated_Cable_Shoulder_Press', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.','Begin by extending through the elbow, pressing the handles together above your head.','After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.','You can also execute this movement with your back off the pad and alternate hands.']::text[]),
  ('seated-close-grip-concentration-barbell-curl', 'Seated Close-Grip Concentration Barbell Curl', 'biceps', '{}', 'barbell', 'reps', 'Seated_Close-Grip_Concentration_Barbell_Curl', array['Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.','Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the barbell back to starting position as your breathe in. Tip: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-dumbbell-curl', 'Seated Dumbbell Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Seated_Dumbbell_Curl', array['Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','Rotate the palms of the hands so that they are facing your torso. This will be your starting position.','While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-dumbbell-inner-biceps-curl', 'Seated Dumbbell Inner Biceps Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Seated_Dumbbell_Inner_Biceps_Curl', array['Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.','While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:','Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate your arms as you lower the dumbbells so that you can switch back to a neutral grip.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-dumbbell-palms-down-wrist-curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'forearms', '{}', 'dumbbell', 'reps', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', array['Start out by placing two dumbbells on the floor in front of a flat bench.','Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.','Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-dumbbell-palms-up-wrist-curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'forearms', '{}', 'dumbbell', 'reps', 'Seated_Dumbbell_Palms-Up_Wrist_Curl', array['Start out by placing two dumbbells on the floor in front of a flat bench.','Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.','Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.','Start out by curling your wrist upwards and exhaling.','Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-flat-bench-leg-pull-in', 'Seated Flat Bench Leg Pull-In', 'abdominals', '{}', 'body_only', 'reps', 'Seated_Flat_Bench_Leg_Pull-In', array['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.','Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.','After a second pause, go back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-good-mornings', 'Seated Good Mornings', 'lower_back', '{glutes}', 'barbell', 'reps', 'Seated_Good_Mornings', array['Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.','Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.','Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.','Pause just above the pins and reverse the motion until your torso it upright.']::text[]),
  ('seated-head-harness-neck-resistance', 'Seated Head Harness Neck Resistance', 'neck', '{}', 'other', 'reps', 'Seated_Head_Harness_Neck_Resistance', array['Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.','Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.','Now place both hands on top of your knees. This is the starting position.','Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.','While exhaling, bring your neck back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-leg-tucks', 'Seated Leg Tucks', 'abdominals', '{}', 'body_only', 'reps', 'Seated_Leg_Tucks', array['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.','Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.','After a second pause, go back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-one-arm-dumbbell-palms-down-wrist-curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'forearms', '{}', 'dumbbell', 'reps', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', array['Sit on a flat bench with a dumbbell in your right hand.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.','Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.','Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.','Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.','Perform for the recommended amount of repetitions, switch arms and repeat the movement.']::text[]),
  ('seated-one-arm-dumbbell-palms-up-wrist-curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'forearms', '{}', 'dumbbell', 'reps', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', array['Sit on a flat bench with a dumbbell in your right hand.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.','Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.','Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.','Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.','Perform for the recommended amount of repetitions, switch arms and repeat the movement.']::text[]),
  ('seated-one-arm-cable-pulley-rows', 'Seated One-arm Cable Pulley Rows', 'middle_back', '{biceps,lats,traps}', 'cable', 'reps', 'Seated_One-arm_Cable_Pulley_Rows', array['To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.','With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.','Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.','Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.','Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.']::text[]),
  ('seated-palm-up-barbell-wrist-curl', 'Seated Palm-Up Barbell Wrist Curl', 'forearms', '{}', 'barbell', 'reps', 'Seated_Palm-Up_Barbell_Wrist_Curl', array['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.','Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.','Lower the bar as far as possible while inhaling and keeping a tight grip.','Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.']::text[]),
  ('seated-palms-down-barbell-wrist-curl', 'Seated Palms-Down Barbell Wrist Curl', 'forearms', '{}', 'barbell', 'reps', 'Seated_Palms-Down_Barbell_Wrist_Curl', array['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.','Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.','Lower the bar as far as possible while inhaling and keeping a tight grip.','Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.']::text[]),
  ('seated-side-lateral-raise', 'Seated Side Lateral Raise', 'shoulders', '{}', 'dumbbell', 'reps', 'Seated_Side_Lateral_Raise', array['Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbells back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-triceps-press', 'Seated Triceps Press', 'triceps', '{}', 'dumbbell', 'reps', 'Seated_Triceps_Press', array['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.','Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('seated-two-arm-palms-up-low-pulley-wrist-curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'forearms', '{}', 'cable', 'reps', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', array['Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.','Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.','Now hold the handle with both hands, palms up, using a shoulder-width grip.','Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.','Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.','Lower the bar as far as possible, while inhaling and keeping a tight grip.']::text[]),
  ('see-saw-press-alternating-side-press', 'See-Saw Press (Alternating Side Press)', 'shoulders', '{abdominals,triceps}', 'dumbbell', 'reps', 'See-Saw_Press_Alternating_Side_Press', array['Grab a dumbbell with each hand and stand up erect.','Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.','Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.','Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.','Repeat for the recommended amount of repetitions.']::text[]),
  ('shotgun-row', 'Shotgun Row', 'lats', '{biceps,middle_back}', 'cable', 'reps', 'Shotgun_Row', array['Attach a single handle to a low cable.','After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.','Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.','After a brief pause, return to the starting position.']::text[]),
  ('shoulder-press-with-bands', 'Shoulder Press - With Bands', 'shoulders', '{triceps}', 'bands', 'reps', 'Shoulder_Press_-_With_Bands', array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.','Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.','As you exhale, lift the handles up until your arms are fully extended overhead.']::text[]),
  ('side-hop-sprint', 'Side Hop-Sprint', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Side_Hop-Sprint', array['Stand to the side of a cone or hurdle.','Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.','Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.']::text[]),
  ('side-jackknife', 'Side Jackknife', 'abdominals', '{}', 'body_only', 'reps', 'Side_Jackknife', '{}'::text[]),
  ('side-laterals-to-front-raise', 'Side Laterals to Front Raise', 'shoulders', '{traps}', 'dumbbell', 'reps', 'Side_Laterals_to_Front_Raise', array['In a standing position, hold a pair of dumbbells at your side. This will be your starting position.','Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.','At the top of the exercise move the weights out in front of you, keeping your arms extended.','Lower the weights with a controlled motion.','On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.','Lower the weights to the starting position.']::text[]),
  ('side-standing-long-jump', 'Side Standing Long Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Side_Standing_Long_Jump', array['Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.','Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.','Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.']::text[]),
  ('side-to-side-chins', 'Side To Side Chins', 'lats', '{biceps,forearms,middle_back,shoulders}', 'other', 'reps', 'Side_To_Side_Chins', array['Grab the pull-up bar with the palms facing forward using a wide grip.','As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.','After a second of contraction, inhale as you go back to the starting position.','Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second of contraction, inhale as you go back to the starting position.']::text[]),
  ('side-to-side-box-shuffle', 'Side to Side Box Shuffle', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Side_to_Side_Box_Shuffle', array['Stand to one side of the box with your left foot resting on the middle of it.','To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.','Continue shuffling back and forth across the box.']::text[]),
  ('single-arm-cable-crossover', 'Single-Arm Cable Crossover', 'chest', '{}', 'cable', 'reps', 'Single-Arm_Cable_Crossover', array['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.','Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.','Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.','Return your arm back to the starting position by pulling your hand back to the midline of the body.','Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.']::text[]),
  ('single-arm-linear-jammer', 'Single-Arm Linear Jammer', 'shoulders', '{chest,triceps}', 'barbell', 'reps', 'Single-Arm_Linear_Jammer', array['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.','Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.','Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.','Return to the starting position.']::text[]),
  ('single-arm-push-up', 'Single-Arm Push-Up', 'chest', '{shoulders,triceps}', 'body_only', 'reps', 'Single-Arm_Push-Up', array['Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.','Maintain good posture, and place your free hand behind your back. This will be your starting position.','Lower yourself by allowing the elbow to flex until you touch the ground.','Descend slowly, and reverse direction be extending the arm to return to the starting position.']::text[]),
  ('single-cone-sprint-drill', 'Single-Cone Sprint Drill', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'reps', 'Single-Cone_Sprint_Drill', array['This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.','Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.','Rest after three trips around the cone.']::text[]),
  ('single-leg-high-box-squat', 'Single-Leg High Box Squat', 'quadriceps', '{glutes,hamstrings}', 'other', 'reps', 'Single-Leg_High_Box_Squat', array['Position a box in a rack. Secure a band or rope in place above the box.','Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance','. Continue stepping up and down on the same leg before switching to the opposite side.']::text[]),
  ('single-leg-hop-progression', 'Single-Leg Hop Progression', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Single-Leg_Hop_Progression', array['Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.','Hop forward, jumping and landing with the same leg over the cone.','Use a countermovement jump to hop from cone to cone.','At the end, turn around and go back on the other leg.']::text[]),
  ('single-leg-lateral-hop', 'Single-Leg Lateral Hop', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Single-Leg_Lateral_Hop', array['Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.','To begin, execute a counterjump to hop sideways over the cone.','Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.','Continue hopping back and forth.']::text[]),
  ('single-leg-leg-extension', 'Single-Leg Leg Extension', 'quadriceps', '{}', 'machine', 'reps', 'Single-Leg_Leg_Extension', array['Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.','Maintaining good posture, fully extend one leg, pausing at the top of the motion.','Return to the starting position without letting the weight stop, keeping tension on the muscle.','Repeat for the desired number of repetitions.']::text[]),
  ('single-leg-stride-jump', 'Single-Leg Stride Jump', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Single-Leg_Stride_Jump', array['Stand to the side of a box with your inside foot on top of it, close to the edge.','Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.','Land in the same position that you started, using your inside leg to decelerate the impact.']::text[]),
  ('single-dumbbell-raise', 'Single Dumbbell Raise', 'shoulders', '{forearms,traps}', 'dumbbell', 'reps', 'Single_Dumbbell_Raise', array['With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.','Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.','Return to the starting position and repeat for the recommended amount of repetitions.']::text[]),
  ('single-leg-butt-kick', 'Single Leg Butt Kick', 'quadriceps', '{calves,hamstrings}', 'body_only', 'reps', 'Single_Leg_Butt_Kick', array['Begin by standing on one leg, with the bent knee raised. This will be your start position.','Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.','Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.','Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.']::text[]),
  ('single-leg-glute-bridge', 'Single Leg Glute Bridge', 'glutes', '{hamstrings}', 'body_only', 'reps', 'Single_Leg_Glute_Bridge', array['Lay on the floor with your feet flat and knees bent.','Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.','Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.','Extend as far as possible, pause and then return to the starting position.']::text[]),
  ('single-leg-push-off', 'Single Leg Push-off', 'quadriceps', '{calves,hamstrings}', 'other', 'reps', 'Single_Leg_Push-off', array['Stand on the ground with one foot resting on the box, heel close to the edge.','Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.','Land with the same foot on top of the box, returning your other foot back to the start position.']::text[]),
  ('sit-up', 'Sit-Up', 'abdominals', '{}', 'body_only', 'reps', 'Sit-Up', array['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.','Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('skating', 'Skating', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'other', 'cardio', 'Skating', array['Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.','You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking.']::text[]),
  ('sled-drag-harness', 'Sled Drag - Harness', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'time', 'Sled_Drag_-_Harness', array['To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.','Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.']::text[]),
  ('sled-overhead-backward-walk', 'Sled Overhead Backward Walk', 'shoulders', '{calves,middle_back,quadriceps}', 'other', 'time', 'Sled_Overhead_Backward_Walk', array['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.','Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.','Walk backwards, keeping your arms raised above your head. Avoid jerky movements.']::text[]),
  ('sled-overhead-triceps-extension', 'Sled Overhead Triceps Extension', 'triceps', '{}', 'other', 'reps', 'Sled_Overhead_Triceps_Extension', array['Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.','Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.','Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.','Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability.']::text[]),
  ('sled-push', 'Sled Push', 'quadriceps', '{calves,chest,glutes,hamstrings,triceps}', 'other', 'time', 'Sled_Push', array['Load your pushing sled with the desired weight.','Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.']::text[]),
  ('sled-reverse-flye', 'Sled Reverse Flye', 'shoulders', '{}', 'other', 'reps', 'Sled_Reverse_Flye', array['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.','Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.','Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.','Return to the starting position, taking a couple steps back to take the slack out of the line.']::text[]),
  ('sled-row', 'Sled Row', 'middle_back', '{biceps,lats}', 'other', 'reps', 'Sled_Row', array['Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.','With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.','To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.','Take a step or two back to get tension in the line and repeat.']::text[]),
  ('sledgehammer-swings', 'Sledgehammer Swings', 'abdominals', '{calves,forearms,lats,middle_back,shoulders}', 'other', 'reps', 'Sledgehammer_Swings', array['You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.','If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.','As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.','Repeat on the other side.']::text[]),
  ('smith-incline-shoulder-raise', 'Smith Incline Shoulder Raise', 'shoulders', '{chest}', 'barbell', 'reps', 'Smith_Incline_Shoulder_Raise', array['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.','Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.','As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.','After a second pause, bring the bar back down to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('smith-machine-behind-the-back-shrug', 'Smith Machine Behind the Back Shrug', 'traps', '{shoulders}', 'machine', 'reps', 'Smith_Machine_Behind_the_Back_Shrug', array['With the bar at thigh level, load an appropriate weight.','Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.','Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.','After a brief pause return the weight to the starting position.','Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[]),
  ('smith-machine-bench-press', 'Smith Machine Bench Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Smith_Machine_Bench_Press', array['Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, lock the bar back in the rack.']::text[]),
  ('smith-machine-bent-over-row', 'Smith Machine Bent Over Row', 'middle_back', '{biceps,lats,shoulders}', 'machine', 'reps', 'Smith_Machine_Bent_Over_Row', array['Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.','Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.','Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-machine-close-grip-bench-press', 'Smith Machine Close-Grip Bench Press', 'triceps', '{chest,shoulders}', 'machine', 'reps', 'Smith_Machine_Close-Grip_Bench_Press', array['Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, lock the bar back in the rack.']::text[]),
  ('smith-machine-decline-press', 'Smith Machine Decline Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Smith_Machine_Decline_Press', array['Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.','Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.','Begin the movement by flexing your arms, lowering the bar to your chest.','Pause briefly, and then extend your arms to push the weight back to the starting position.','After completing the desired number of repetitions, rotate the bar to rack the weight.']::text[]),
  ('smith-machine-hang-power-clean', 'Smith Machine Hang Power Clean', 'hamstrings', '{glutes,lower_back,quadriceps,shoulders,traps}', 'machine', 'reps', 'Smith_Machine_Hang_Power_Clean', array['Position the bar at knee height and load it to an appropriate weight.','Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.','Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.','Upon full extension, rebend the hips and knees to lower your receiving position.','Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.','Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement.']::text[]),
  ('smith-machine-hip-raise', 'Smith Machine Hip Raise', 'abdominals', '{}', 'machine', 'reps', 'Smith_Machine_Hip_Raise', array['Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.','Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.','After a brief pause, return the hips to the bench.','Repeat for the desired number of repetitions.']::text[]),
  ('smith-machine-incline-bench-press', 'Smith Machine Incline Bench Press', 'chest', '{shoulders,triceps}', 'machine', 'reps', 'Smith_Machine_Incline_Bench_Press', array['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your upper chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.','When you are done, place the bar back in the rack.']::text[]),
  ('smith-machine-leg-press', 'Smith Machine Leg Press', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Smith_Machine_Leg_Press', array['Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.','Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.','At the top of the motion, pause briefly before returning to the starting position.']::text[]),
  ('smith-machine-one-arm-upright-row', 'Smith Machine One-Arm Upright Row', 'shoulders', '{biceps,traps}', 'machine', 'reps', 'Smith_Machine_One-Arm_Upright_Row', array['With the bar at thigh level, load an appropriate weight.','Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.','Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.','After a brief pause, return the weight to the starting position.','Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[]),
  ('smith-machine-overhead-shoulder-press', 'Smith Machine Overhead Shoulder Press', 'shoulders', '{triceps}', 'machine', 'reps', 'Smith_Machine_Overhead_Shoulder_Press', array['To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.','Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.','Slowly begin to lower the barbell until it is level with your chin while inhaling.','Then lift the barbell back to the starting position using your shoulders while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-machine-pistol-squat', 'Smith Machine Pistol Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Smith_Machine_Pistol_Squat', array['To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.','Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3','Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.','Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.','Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip.']::text[]),
  ('smith-machine-reverse-calf-raises', 'Smith Machine Reverse Calf Raises', 'calves', '{}', 'machine', 'reps', 'Smith_Machine_Reverse_Calf_Raises', array['Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.','Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.','Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.','Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.','Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-machine-squat', 'Smith Machine Squat', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'machine', 'reps', 'Smith_Machine_Squat', array['To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-machine-stiff-legged-deadlift', 'Smith Machine Stiff-Legged Deadlift', 'hamstrings', '{glutes,lower_back}', 'machine', 'reps', 'Smith_Machine_Stiff-Legged_Deadlift', array['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.','Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.','Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement','Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-machine-upright-row', 'Smith Machine Upright Row', 'traps', '{biceps,middle_back,shoulders}', 'machine', 'reps', 'Smith_Machine_Upright_Row', array['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.','Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.','Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('smith-single-leg-split-squat', 'Smith Single-Leg Split Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'reps', 'Smith_Single-Leg_Split_Squat', array['To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position','Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('snatch', 'Snatch', 'quadriceps', '{biceps,glutes,hamstrings,lower_back,shoulders,traps,triceps}', 'barbell', 'reps', 'Snatch', array['Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.','With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.','Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.','As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.','Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.','Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.']::text[]),
  ('snatch-balance', 'Snatch Balance', 'quadriceps', '{calves,glutes,hamstrings,shoulders,triceps}', 'barbell', 'reps', 'Snatch_Balance', array['Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.','Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.','Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.','Continue to descend to full depth, and return to a standing position. Carefully lower the weight.']::text[]),
  ('snatch-deadlift', 'Snatch Deadlift', 'hamstrings', '{forearms,glutes,lower_back,quadriceps,traps}', 'barbell', 'reps', 'Snatch_Deadlift', array['The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.','Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.','At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.']::text[]),
  ('snatch-pull', 'Snatch Pull', 'hamstrings', '{calves,glutes,lower_back,quadriceps,traps}', 'barbell', 'reps', 'Snatch_Pull', array['With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.','There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[]),
  ('snatch-shrug', 'Snatch Shrug', 'traps', '{forearms,shoulders}', 'barbell', 'reps', 'Snatch_Shrug', array['Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.','Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.']::text[]),
  ('snatch-from-blocks', 'Snatch from Blocks', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back,shoulders,traps,triceps}', 'barbell', 'reps', 'Snatch_from_Blocks', array['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the boxes.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.','Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[]),
  ('speed-band-overhead-triceps', 'Speed Band Overhead Triceps', 'triceps', '{}', 'bands', 'reps', 'Speed_Band_Overhead_Triceps', array['For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.','To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.','To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.','Pause, and then return to the starting position.']::text[]),
  ('speed-box-squat', 'Speed Box Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Speed_Box_Squat', array['Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.','Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.','Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.','Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.','Pause briefly, and explode off of the box, extending through the hips and knees.']::text[]),
  ('speed-squats', 'Speed Squats', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Speed_Squats', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.','Repeat for the recommended amount of repetitions.']::text[]),
  ('spell-caster', 'Spell Caster', 'abdominals', '{glutes,shoulders}', 'dumbbell', 'reps', 'Spell_Caster', array['Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.','Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.','Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.','Continue alternating, rotating from one side to the other until the set is complete.']::text[]),
  ('spider-crawl', 'Spider Crawl', 'abdominals', '{chest,shoulders,triceps}', 'body_only', 'reps', 'Spider_Crawl', array['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.','Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.','Return this leg to the starting position and repeat on the opposite side.']::text[]),
  ('spider-curl', 'Spider Curl', 'biceps', '{}', 'ez_curl_bar', 'reps', 'Spider_Curl', array['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.','Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.','Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.','Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.','Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the barbell back to the starting position as your breathe in. .']::text[]),
  ('split-clean', 'Split Clean', 'quadriceps', '{calves,forearms,glutes,hamstrings,lower_back,shoulders,traps}', 'barbell', 'reps', 'Split_Clean', array['With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.','Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.','Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up.']::text[]),
  ('split-jerk', 'Split Jerk', 'quadriceps', '{glutes,hamstrings,shoulders,triceps}', 'barbell', 'reps', 'Split_Jerk', array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.','Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.','In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.','Return to a standing position, bringing the feet together.']::text[]),
  ('split-jump', 'Split Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Split_Jump', array['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.','Ensure that the front knee is over the midline of the foot.','Extending through both legs, jump as high as possible, swinging your arms to gain lift.','As you jump, bring your feet together, and move them back to their initial positions as you land.','Absorb the impact by reverting back to the starting position.']::text[]),
  ('split-snatch', 'Split Snatch', 'hamstrings', '{calves,forearms,glutes,lower_back,quadriceps,shoulders,traps,triceps}', 'barbell', 'reps', 'Split_Snatch', array['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.','Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.','Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.','Carefully return the weight to floor.']::text[]),
  ('squat-jerk', 'Squat Jerk', 'quadriceps', '{calves,glutes,hamstrings,shoulders,triceps}', 'barbell', 'reps', 'Squat_Jerk', array['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.','At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.','Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position. Carefully return the weight to floor.']::text[]),
  ('squat-with-bands', 'Squat with Bands', 'quadriceps', '{adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Squat_with_Bands', array['Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.','Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[]),
  ('squat-with-chains', 'Squat with Chains', 'quadriceps', '{adductors,calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Squat_with_Chains', array['To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.','Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.','With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.','Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[]),
  ('squat-with-plate-movers', 'Squat with Plate Movers', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'barbell', 'reps', 'Squat_with_Plate_Movers', array['To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.','Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.','Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.','Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.','Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.','At the top of the movement, side step, bringing your feet together on the opposite side of the plate.']::text[]),
  ('squats-with-bands', 'Squats - With Bands', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'bands', 'reps', 'Squats_-_With_Bands', array['To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.','When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.','Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.','Use the heel of your feet to push your body up to the starting position as you exhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-alternating-dumbbell-press', 'Standing Alternating Dumbbell Press', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Standing_Alternating_Dumbbell_Press', array['Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.','Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.','After a brief pause, return the weight to the starting position.','Repeat for the opposite side, continuing to alternate between arms.']::text[]),
  ('standing-barbell-calf-raise', 'Standing Barbell Calf Raise', 'calves', '{}', 'barbell', 'reps', 'Standing_Barbell_Calf_Raise', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.','Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-barbell-press-behind-neck', 'Standing Barbell Press Behind Neck', 'shoulders', '{triceps}', 'barbell', 'reps', 'Standing_Barbell_Press_Behind_Neck', array['This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.','Elevate the barbell overhead by fully extending your arms while breathing out.','Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-bent-over-one-arm-dumbbell-triceps-extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'triceps', '{shoulders}', 'dumbbell', 'reps', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', array['With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.','The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position.','Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.','After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.','Repeat the movement for the prescribed amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('standing-bent-over-two-arm-dumbbell-triceps-extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', array['With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.','Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves.','After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('standing-biceps-cable-curl', 'Standing Biceps Cable Curl', 'biceps', '{}', 'cable', 'reps', 'Standing_Biceps_Cable_Curl', array['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the curl bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-bradford-press', 'Standing Bradford Press', 'shoulders', '{triceps}', 'barbell', 'reps', 'Standing_Bradford_Press', array['Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.','Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.','Lower the bar down to the back of the head until your elbow forms a right angle.','Lift the bar back over your head by extending the elbows','Lower the bar down to the starting position.','Alternate in this manner until you complete the recommended amount of repetitions.']::text[]),
  ('standing-cable-chest-press', 'Standing Cable Chest Press', 'chest', '{shoulders,triceps}', 'cable', 'reps', 'Standing_Cable_Chest_Press', array['Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.','Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.','Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.','Pause at the top of the motion, and return to the starting position.']::text[]),
  ('standing-cable-lift', 'Standing Cable Lift', 'abdominals', '{shoulders}', 'cable', 'reps', 'Standing_Cable_Lift', array['Connect a standard handle on a tower, and move the cable to the lowest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.','Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.','Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.']::text[]),
  ('standing-cable-wood-chop', 'Standing Cable Wood Chop', 'abdominals', '{shoulders}', 'cable', 'reps', 'Standing_Cable_Wood_Chop', array['Connect a standard handle to a tower, and move the cable to the highest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle down and across your body to your front knee while rotating your torso.','Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.','Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.']::text[]),
  ('standing-concentration-curl', 'Standing Concentration Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Standing_Concentration_Curl', array['Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.','Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.','Lower the dumbbell back to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('standing-dumbbell-calf-raise', 'Standing Dumbbell Calf Raise', 'calves', '{}', 'dumbbell', 'reps', 'Standing_Dumbbell_Calf_Raise', array['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.','With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.','As you inhale, go back to the starting position by slowly lowering the heels.','Repeat for the recommended amount of times.']::text[]),
  ('standing-dumbbell-press', 'Standing Dumbbell Press', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Standing_Dumbbell_Press', array['Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.','Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.','Pause, and slowly return the weight to the starting position.']::text[]),
  ('standing-dumbbell-reverse-curl', 'Standing Dumbbell Reverse Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Standing_Dumbbell_Reverse_Curl', array['To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.','While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-dumbbell-straight-arm-front-delt-raise-above-head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'shoulders', '{}', 'dumbbell', 'reps', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', array['Hold the dumbbells in front of your thighs, palms facing your thighs.','Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.','Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.','Slowly return to the starting position using the same path as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-dumbbell-triceps-extension', 'Standing Dumbbell Triceps Extension', 'triceps', '{}', 'dumbbell', 'reps', 'Standing_Dumbbell_Triceps_Extension', array['To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.','The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.','Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-dumbbell-upright-row', 'Standing Dumbbell Upright Row', 'traps', '{biceps,shoulders}', 'dumbbell', 'reps', 'Standing_Dumbbell_Upright_Row', array['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-front-barbell-raise-over-head', 'Standing Front Barbell Raise Over Head', 'shoulders', '{}', 'barbell', 'reps', 'Standing_Front_Barbell_Raise_Over_Head', array['To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.','Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.','Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.','Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-inner-biceps-curl', 'Standing Inner-Biceps Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Standing_Inner-Biceps_Curl', array['Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other.','Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.','While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).','Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.','Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.']::text[]),
  ('standing-long-jump', 'Standing Long Jump', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'reps', 'Standing_Long_Jump', array['This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.','Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.','Attempt to land with your feet out in front you, reaching as far as possible with your legs.','Measure the distance from your landing point to the starting point and track results.']::text[]),
  ('standing-low-pulley-deltoid-raise', 'Standing Low-Pulley Deltoid Raise', 'shoulders', '{forearms}', 'cable', 'reps', 'Standing_Low-Pulley_Deltoid_Raise', array['Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.','Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.','Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.','Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('standing-low-pulley-one-arm-triceps-extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'triceps', '{chest,shoulders}', 'cable', 'reps', 'Standing_Low-Pulley_One-Arm_Triceps_Extension', array['Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.','Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('standing-olympic-plate-hand-squeeze', 'Standing Olympic Plate Hand Squeeze', 'forearms', '{biceps}', 'other', 'reps', 'Standing_Olympic_Plate_Hand_Squeeze', array['To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.','Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.','Now raise the plates back to the starting position as you exhale by closing your hands.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
  ('standing-one-arm-cable-curl', 'Standing One-Arm Cable Curl', 'biceps', '{}', 'cable', 'reps', 'Standing_One-Arm_Cable_Curl', array['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.','Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.','Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.','Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.','Switch arms while performing this exercise.']::text[]),
  ('standing-one-arm-dumbbell-curl-over-incline-bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'biceps', '{}', 'dumbbell', 'reps', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', array['Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.','Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.','While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.','Switch arms while performing this exercise.']::text[]),
  ('standing-one-arm-dumbbell-triceps-extension', 'Standing One-Arm Dumbbell Triceps Extension', 'triceps', '{chest,shoulders}', 'dumbbell', 'reps', 'Standing_One-Arm_Dumbbell_Triceps_Extension', array['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.','This will be your starting position.','Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.','Switch arms and repeat the exercise.']::text[]),
  ('standing-overhead-barbell-triceps-extension', 'Standing Overhead Barbell Triceps Extension', 'triceps', '{shoulders}', 'barbell', 'reps', 'Standing_Overhead_Barbell_Triceps_Extension', array['To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.','Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.','Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-palm-in-one-arm-dumbbell-press', 'Standing Palm-In One-Arm Dumbbell Press', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Standing_Palm-In_One-Arm_Dumbbell_Press', array['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.','Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.','Slowly lift the dumbbell up until your arm is fully extended. This the starting position.','While inhaling lower the weight down until your arm is at a 90 degree angle again.','Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-palms-in-dumbbell-press', 'Standing Palms-In Dumbbell Press', 'shoulders', '{triceps}', 'dumbbell', 'reps', 'Standing_Palms-In_Dumbbell_Press', array['Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.','Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.','While inhaling lower the weights down until your arm is at a 90 degree angle again.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-palms-up-barbell-behind-the-back-wrist-curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'forearms', '{}', 'barbell', 'reps', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', array['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.','You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.','While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.','Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.','When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.']::text[]),
  ('standing-rope-crunch', 'Standing Rope Crunch', 'abdominals', '{}', 'cable', 'reps', 'Standing_Rope_Crunch', array['Attach a rope to a high pulley and select an appropriate weight.','Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.','Perform the movement by flexing the spine, crunching the weight down as far as you can.','Hold the peak contraction for a moment before returning to the starting position.']::text[]),
  ('standing-towel-triceps-extension', 'Standing Towel Triceps Extension', 'triceps', '{}', 'body_only', 'reps', 'Standing_Towel_Triceps_Extension', array['To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.','Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('standing-two-arm-overhead-throw', 'Standing Two-Arm Overhead Throw', 'shoulders', '{chest,lats}', 'medicine_ball', 'reps', 'Standing_Two-Arm_Overhead_Throw', array['Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.','Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.','The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.']::text[]),
  ('star-jump', 'Star Jump', 'quadriceps', '{calves,glutes,hamstrings,shoulders}', 'body_only', 'reps', 'Star_Jump', array['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.','To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.','As you land, bring your limbs back in and absorb your impact through the legs.']::text[]),
  ('step-up-with-knee-raise', 'Step-up with Knee Raise', 'glutes', '{hamstrings,quadriceps}', 'body_only', 'reps', 'Step-up_with_Knee_Raise', array['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.','Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.','Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[]),
  ('step-mill', 'Step Mill', 'quadriceps', '{calves,glutes,hamstrings}', 'machine', 'cardio', 'Step_Mill', array['To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.','Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[]),
  ('stiff-legged-barbell-deadlift', 'Stiff-Legged Barbell Deadlift', 'hamstrings', '{glutes,lower_back}', 'barbell', 'reps', 'Stiff-Legged_Barbell_Deadlift', array['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.','Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.','Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.','Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('stiff-legged-dumbbell-deadlift', 'Stiff-Legged Dumbbell Deadlift', 'hamstrings', '{glutes,lower_back}', 'dumbbell', 'reps', 'Stiff-Legged_Dumbbell_Deadlift', array['Grasp a couple of dumbbells holding them by your side at arm''s length.','Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.','Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement','Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('stiff-leg-barbell-good-morning', 'Stiff Leg Barbell Good Morning', 'lower_back', '{glutes,hamstrings}', 'barbell', 'reps', 'Stiff_Leg_Barbell_Good_Morning', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.','Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.','Begin to raise the bar as you exhale by elevating your torso back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('straight-arm-dumbbell-pullover', 'Straight-Arm Dumbbell Pullover', 'chest', '{lats,shoulders,triceps}', 'dumbbell', 'reps', 'Straight-Arm_Dumbbell_Pullover', array['Place a dumbbell standing up on a flat bench.','Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
  ('straight-arm-pulldown', 'Straight-Arm Pulldown', 'lats', '{}', 'cable', 'reps', 'Straight-Arm_Pulldown', array['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.','Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.','While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.','While keeping the arms straight, go back to the starting position while breathing in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('straight-bar-bench-mid-rows', 'Straight Bar Bench Mid Rows', 'middle_back', '{biceps,lats}', 'barbell', 'reps', 'Straight_Bar_Bench_Mid_Rows', array['Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.','Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.','After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.']::text[]),
  ('straight-raises-on-incline-bench', 'Straight Raises on Incline Bench', 'shoulders', '{traps}', 'barbell', 'reps', 'Straight_Raises_on_Incline_Bench', array['Place a bar on the ground behind the head of an incline bench.','Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.','To begin, raise the barbell out in front of your head while keeping your arms extended.','Return to the starting position.']::text[]),
  ('stride-jump-crossover', 'Stride Jump Crossover', 'quadriceps', '{abductors,adductors,calves,hamstrings}', 'other', 'reps', 'Stride_Jump_Crossover', array['Stand to the side of a box with your inside foot on top of it, close to the edge.','Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.','Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.','Repeat the movement, crossing back over to the other side.']::text[]),
  ('sumo-deadlift', 'Sumo Deadlift', 'hamstrings', '{adductors,forearms,glutes,lower_back,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Sumo_Deadlift', array['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
  ('sumo-deadlift-with-bands', 'Sumo Deadlift with Bands', 'hamstrings', '{adductors,forearms,glutes,lower_back,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Sumo_Deadlift_with_Bands', array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.','Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.','Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
  ('sumo-deadlift-with-chains', 'Sumo Deadlift with Chains', 'hamstrings', '{abductors,adductors,forearms,glutes,lower_back,middle_back,quadriceps,traps}', 'barbell', 'reps', 'Sumo_Deadlift_with_Chains', array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.','Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
  ('supine-chest-throw', 'Supine Chest Throw', 'triceps', '{chest,shoulders}', 'medicine_ball', 'reps', 'Supine_Chest_Throw', array['This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.','Begin with the ball on your chest, held with both hands on the bottom.','Explode up, extending through the elbow to throw the ball directly above you as high as possible.','Catch the ball with both hands as it comes down.']::text[]),
  ('supine-one-arm-overhead-throw', 'Supine One-Arm Overhead Throw', 'abdominals', '{chest,lats,shoulders}', 'medicine_ball', 'reps', 'Supine_One-Arm_Overhead_Throw', array['Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.','Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.','The ball can be thrown to a partner or bounced off of a wall.']::text[]),
  ('supine-two-arm-overhead-throw', 'Supine Two-Arm Overhead Throw', 'abdominals', '{chest,lats,shoulders}', 'medicine_ball', 'reps', 'Supine_Two-Arm_Overhead_Throw', array['Lay on the ground on your back with your knees bent.','Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.','Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.','The ball can be thrown to a partner or bounced off of a wall.']::text[]),
  ('suspended-fallout', 'Suspended Fallout', 'abdominals', '{chest,lower_back,shoulders}', 'other', 'reps', 'Suspended_Fallout', array['Adjust the straps so the handles are at an appropriate height, below waist level.','Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.','Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.','Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.','Pause during the peak contraction, and then return to the starting position.']::text[]),
  ('suspended-push-up', 'Suspended Push-Up', 'chest', '{shoulders,triceps}', 'other', 'reps', 'Suspended_Push-Up', array['Anchor your suspension straps securely to the top of a rack or other object.','Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.','Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.','Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.']::text[]),
  ('suspended-reverse-crunch', 'Suspended Reverse Crunch', 'abdominals', '{}', 'other', 'reps', 'Suspended_Reverse_Crunch', array['Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.','Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.','Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.','At the top of the controlled motion, return to the starting position.']::text[]),
  ('suspended-row', 'Suspended Row', 'middle_back', '{biceps,lats}', 'other', 'reps', 'Suspended_Row', array['Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.','Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.','At the completion of the motion pause, and then return to the starting position.']::text[]),
  ('suspended-split-squat', 'Suspended Split Squat', 'quadriceps', '{abductors,adductors,calves,glutes,hamstrings}', 'other', 'reps', 'Suspended_Split_Squat', array['Suspend your straps so the handles are 18-30 inches from the floor.','Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.','Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.','At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position.']::text[]),
  ('svend-press', 'Svend Press', 'chest', '{forearms,shoulders,triceps}', 'other', 'reps', 'Svend_Press', array['Begin in a standing position.','Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.','Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.','Pause at the top of the motion, and then slowly return to the starting position.']::text[]),
  ('tate-press', 'Tate Press', 'triceps', '{chest,shoulders}', 'dumbbell', 'reps', 'Tate_Press', array['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.','By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.','Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.','As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
  ('thigh-abductor', 'Thigh Abductor', 'abductors', '{glutes}', 'machine', 'reps', 'Thigh_Abductor', array['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.','Slowly press against the machine with your legs to move them away from each other while exhaling.','Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.','Repeat for the recommended amount of repetitions.']::text[]),
  ('thigh-adductor', 'Thigh Adductor', 'adductors', '{glutes,hamstrings}', 'machine', 'reps', 'Thigh_Adductor', array['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.','Slowly press against the machine with your legs to move them towards each other while exhaling.','Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.','Repeat for the recommended amount of repetitions.']::text[]),
  ('tire-flip', 'Tire Flip', 'quadriceps', '{calves,chest,forearms,glutes,hamstrings,lower_back,shoulders,traps,triceps}', 'other', 'reps', 'Tire_Flip', array['Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.','To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.','As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.']::text[]),
  ('trail-running-walking', 'Trail Running/Walking', 'quadriceps', '{calves,glutes,hamstrings}', 'body_only', 'cardio', 'Trail_Running_Walking', array['Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.','A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes.']::text[]),
  ('trap-bar-deadlift', 'Trap Bar Deadlift', 'quadriceps', '{glutes,hamstrings}', 'other', 'reps', 'Trap_Bar_Deadlift', array['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.','Lower your hips, look forward with your head and keep your chest up.','Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.','At the completion of the movement, lower the weight back to the ground under control.']::text[]),
  ('tricep-dumbbell-kickback', 'Tricep Dumbbell Kickback', 'triceps', '{}', 'dumbbell', 'reps', 'Tricep_Dumbbell_Kickback', array['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.','Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.','After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('triceps-overhead-extension-with-rope', 'Triceps Overhead Extension with Rope', 'triceps', '{}', 'cable', 'reps', 'Triceps_Overhead_Extension_with_Rope', array['Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.','Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.','To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.','Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.']::text[]),
  ('triceps-pushdown-rope-attachment', 'Triceps Pushdown - Rope Attachment', 'triceps', '{}', 'cable', 'reps', 'Triceps_Pushdown_-_Rope_Attachment', array['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).','Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.','Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('triceps-pushdown-v-bar-attachment', 'Triceps Pushdown - V-Bar Attachment', 'triceps', '{}', 'cable', 'reps', 'Triceps_Pushdown_-_V-Bar_Attachment', array['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.','Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.','Repeat for the recommended amount of repetitions.']::text[]),
  ('tuck-crunch', 'Tuck Crunch', 'abdominals', '{}', 'body_only', 'reps', 'Tuck_Crunch', array['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.','Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.','Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.','While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.','Slowly begin to lower your torso back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('two-arm-dumbbell-preacher-curl', 'Two-Arm Dumbbell Preacher Curl', 'biceps', '{}', 'dumbbell', 'reps', 'Two-Arm_Dumbbell_Preacher_Curl', array['Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.','As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.','Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
  ('two-arm-kettlebell-clean', 'Two-Arm Kettlebell Clean', 'shoulders', '{calves,glutes,hamstrings,lower_back,traps}', 'kettlebells', 'reps', 'Two-Arm_Kettlebell_Clean', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.','Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.','Lower the kettlebells back to the starting position and repeat.']::text[]),
  ('two-arm-kettlebell-jerk', 'Two-Arm Kettlebell Jerk', 'shoulders', '{calves,quadriceps,triceps}', 'kettlebells', 'reps', 'Two-Arm_Kettlebell_Jerk', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.']::text[]),
  ('two-arm-kettlebell-military-press', 'Two-Arm Kettlebell Military Press', 'shoulders', '{triceps}', 'kettlebells', 'reps', 'Two-Arm_Kettlebell_Military_Press', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.','Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.']::text[]),
  ('two-arm-kettlebell-row', 'Two-Arm Kettlebell Row', 'middle_back', '{biceps,lats}', 'kettlebells', 'reps', 'Two-Arm_Kettlebell_Row', array['Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.','Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.']::text[]),
  ('underhand-cable-pulldowns', 'Underhand Cable Pulldowns', 'lats', '{biceps,middle_back,shoulders}', 'cable', 'reps', 'Underhand_Cable_Pulldowns', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('upright-cable-row', 'Upright Cable Row', 'traps', '{shoulders}', 'cable', 'reps', 'Upright_Cable_Row', array['Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('upright-row-with-bands', 'Upright Row - With Bands', 'traps', '{shoulders}', 'bands', 'reps', 'Upright_Row_-_With_Bands', array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.','Repeat for the recommended amount of repetitions.']::text[]),
  ('v-bar-pulldown', 'V-Bar Pulldown', 'lats', '{biceps,middle_back,shoulders}', 'cable', 'reps', 'V-Bar_Pulldown', array['Sit down on a pull-down machine with a V-Bar attached to the top pulley.','Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.','Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.','After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.','Repeat for the prescribed number of repetitions.']::text[]),
  ('v-bar-pullup', 'V-Bar Pullup', 'lats', '{biceps,middle_back,shoulders}', 'body_only', 'reps', 'V-Bar_Pullup', array['Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.','Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.','Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.','After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.','Repeat for the prescribed number of repetitions.']::text[]),
  ('vertical-swing', 'Vertical Swing', 'hamstrings', '{glutes,quadriceps,shoulders}', 'dumbbell', 'reps', 'Vertical_Swing', array['Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.','Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.','Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.','As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.']::text[]),
  ('weighted-ball-hyperextension', 'Weighted Ball Hyperextension', 'lower_back', '{glutes,hamstrings,middle_back}', 'exercise_ball', 'reps', 'Weighted_Ball_Hyperextension', array['To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.','Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.','Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
  ('weighted-ball-side-bend', 'Weighted Ball Side Bend', 'abdominals', '{}', 'exercise_ball', 'reps', 'Weighted_Ball_Side_Bend', array['To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.','Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.','Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.','Raise the side of your torso up by laterally flexing at the waist while exhaling.','Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('weighted-bench-dip', 'Weighted Bench Dip', 'triceps', '{chest,shoulders}', 'other', 'reps', 'Weighted_Bench_Dip', array['For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.','The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('weighted-crunches', 'Weighted Crunches', 'abdominals', '{}', 'medicine_ball', 'reps', 'Weighted_Crunches', array['Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.','Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.','Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.','At the top of the movement, flex your abdominals and hold for a brief pause.','Then inhale and slowly lower yourself back down to the starting position.']::text[]),
  ('weighted-jump-squat', 'Weighted Jump Squat', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Weighted_Jump_Squat', array['Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.','The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.','Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.','As you return to the ground, absorb the impact through your legs.']::text[]),
  ('weighted-pull-ups', 'Weighted Pull Ups', 'lats', '{biceps,middle_back}', 'other', 'reps', 'Weighted_Pull_Ups', array['Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.','You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.','Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.','After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.']::text[]),
  ('weighted-sissy-squat', 'Weighted Sissy Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Weighted_Sissy_Squat', array['Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.','As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.','After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.','Repeat for the recommended amount of times.']::text[]),
  ('weighted-sit-ups-with-bands', 'Weighted Sit-Ups - With Bands', 'abdominals', '{}', 'other', 'reps', 'Weighted_Sit-Ups_-_With_Bands', array['Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.','Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.','Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[]),
  ('weighted-squat', 'Weighted Squat', 'quadriceps', '{calves,glutes,hamstrings}', 'other', 'reps', 'Weighted_Squat', array['Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.','Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.','Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.','Repeat for the recommended amount of repetitions.']::text[]),
  ('wide-grip-barbell-bench-press', 'Wide-Grip Barbell Bench Press', 'chest', '{shoulders,triceps}', 'barbell', 'reps', 'Wide-Grip_Barbell_Bench_Press', array['Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your middle chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('wide-grip-decline-barbell-bench-press', 'Wide-Grip Decline Barbell Bench Press', 'chest', '{shoulders,triceps}', 'barbell', 'reps', 'Wide-Grip_Decline_Barbell_Bench_Press', array['Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.','As you breathe in, come down slowly until you feel the bar on your lower chest.','After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.','Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('wide-grip-decline-barbell-pullover', 'Wide-Grip Decline Barbell Pullover', 'chest', '{shoulders,triceps}', 'barbell', 'reps', 'Wide-Grip_Decline_Barbell_Pullover', array['Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.','When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.','Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.','Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.','Repeat the movement for the prescribed amount of repetitions of your training program.','When finished with your set, slowly lower the barbell back down until it is level with your head and release it.']::text[]),
  ('wide-grip-pulldown-behind-the-neck', 'Wide-Grip Pulldown Behind The Neck', 'lats', '{biceps,middle_back,shoulders}', 'cable', 'reps', 'Wide-Grip_Pulldown_Behind_The_Neck', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.','As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.','After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('wide-grip-rear-pull-up', 'Wide-Grip Rear Pull-Up', 'lats', '{biceps,middle_back,shoulders}', 'body_only', 'reps', 'Wide-Grip_Rear_Pull-Up', array['Grab the pull-up bar with the palms facing forward using a wide grip.','As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.','Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('wide-grip-standing-barbell-curl', 'Wide-Grip Standing Barbell Curl', 'biceps', '{}', 'barbell', 'reps', 'Wide-Grip_Standing_Barbell_Curl', array['Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[]),
  ('wide-stance-barbell-squat', 'Wide Stance Barbell Squat', 'quadriceps', '{calves,glutes,hamstrings,lower_back}', 'barbell', 'reps', 'Wide_Stance_Barbell_Squat', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.','Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('wide-stance-stiff-legs', 'Wide Stance Stiff Legs', 'hamstrings', '{adductors,glutes,lower_back}', 'barbell', 'reps', 'Wide_Stance_Stiff_Legs', array['Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.','Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor.']::text[]),
  ('wind-sprints', 'Wind Sprints', 'abdominals', '{}', 'body_only', 'reps', 'Wind_Sprints', array['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.','Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3','Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.','Continue alternating between legs until the set is complete.']::text[]),
  ('wrist-rotations-with-straight-bar', 'Wrist Rotations with Straight Bar', 'forearms', '{}', 'barbell', 'reps', 'Wrist_Rotations_with_Straight_Bar', array['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.','Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.','Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.']::text[]),
  ('yoke-walk', 'Yoke Walk', 'quadriceps', '{abdominals,abductors,adductors,calves,glutes,hamstrings,lower_back}', 'other', 'time', 'Yoke_Walk', array['The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.','Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.','Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.']::text[]),
  ('zercher-squats', 'Zercher Squats', 'quadriceps', '{calves,glutes,hamstrings}', 'barbell', 'reps', 'Zercher_Squats', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.','Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.','Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).','Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[]),
  ('zottman-curl', 'Zottman Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Zottman_Curl', array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','Make sure the palms of the hands are facing each other. This will be your starting position.','While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.','Hold the contracted position for a second as you squeeze the biceps.','Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.','Slowly begin to bring the dumbbells back down using the pronated grip.']::text[]),
  ('zottman-preacher-curl', 'Zottman Preacher Curl', 'biceps', '{forearms}', 'dumbbell', 'reps', 'Zottman_Preacher_Curl', array['Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.','As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.','Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.','As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.','Repeat for the recommended amount of repetitions.']::text[])
) as v (slug, name, primary_muscle, secondary_muscles, equipment, tracking, photos, how_to)
on conflict (slug) do nothing;


-- ========================================================================
-- 20261020000034_admin.sql
-- ========================================================================

-- JLIKA Gym — the operator dashboard and invite-only signup.
--
-- PRIVACY BOUNDARY. The app promises that nobody can read anyone else's data,
-- and the operator is not an exception. Everything the dashboard can see goes
-- through the admin_* functions below, and they return account-level facts and
-- counts only:
--
--   email, signup date, last sign-in, disabled or not
--   number of finished sessions, date of the last one
--   whether a session is open right now, and since when
--
-- Never weights, sets, exercises, weigh-ins, photos, nutrition or notes. The
-- boundary is the functions' return types, not the screen: a dashboard bug can
-- only show what these functions hand back.
--
-- app_settings        One row of instance-wide switches. Today only
--                     invite_only. Kept in the database rather than in the
--                     app's environment because the signup trigger below is the
--                     one place a direct auth.signUp() with the publishable key
--                     can be stopped, and it cannot read the app's environment.
-- signup_invites      Codes an operator hands out while signup is invite-only.
--                     Each has a number of uses and an optional expiry, and can
--                     be revoked.
--
-- Neither table is readable or writable by anon or authenticated: RLS is on
-- with no policies, and the table grants are revoked as well. The dashboard
-- manages them with the server's secret key; signup reaches them only through
-- the trigger and signup_invite_required().

-- ------------------------------------------------------------- app settings

create table if not exists public.app_settings (
  -- A single row: the check makes a second one impossible.
  id smallint primary key default 1 check (id = 1),
  invite_only boolean not null default false,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users on delete set null
);

insert into public.app_settings (id) values (1) on conflict (id) do nothing;

alter table public.app_settings enable row level security;
revoke all on table public.app_settings from anon, authenticated;
grant select, update on table public.app_settings to service_role;

-- ----------------------------------------------------------- signup invites

create table if not exists public.signup_invites (
  -- JLIKA-XXXX-XXXX-XXXX from a 32-letter alphabet with no I, O, 0 or 1:
  -- 60 bits, so not worth guessing. lib/admin/invite-code.ts generates them.
  code text primary key
    check (code ~ '^JLIKA-[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}$'),
  max_uses int not null default 1 check (max_uses between 1 and 100),
  uses int not null default 0 check (uses >= 0 and uses <= max_uses),
  -- Null = never expires.
  expires_at timestamptz,
  -- Who it was for, in the operator's words. Shown only on the dashboard.
  note text check (note is null or char_length(note) <= 60),
  created_by uuid references auth.users on delete set null,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

alter table public.signup_invites enable row level security;
revoke all on table public.signup_invites from anon, authenticated;
grant select, insert, update on table public.signup_invites to service_role;

-- ------------------------------------------------------ invite-only signup

/**
 * Whether signup currently needs an invite code. The signup form asks before
 * it renders the field; it reveals one boolean and nothing about any code.
 */
create or replace function public.signup_invite_required()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select s.invite_only from public.app_settings s where s.id = 1), false);
$$;

/**
 * Refuses a new account while signup is invite-only, unless it carries a valid
 * code in raw_user_meta_data.signup_code — and consumes one use of it.
 *
 * A trigger on auth.users rather than a check in the app, because anyone can
 * call Supabase's signUp directly with the publishable key from the browser
 * bundle; only the database sees every new account.
 *
 *   * Existing accounts are untouched: this runs on insert only, so signing in,
 *     confirming an email or changing a password never reaches it.
 *   * Google and other OAuth signups carry no code, so while invite-only is on
 *     a first-time OAuth sign-in is refused. Someone who already has an
 *     account can still link Google to it, because that inserts no user.
 *   * The single UPDATE is the check and the consumption at once: the row lock
 *     means two signups racing for a code's last use cannot both get it.
 *   * Raising aborts the insert. Recent GoTrue passes this message through;
 *     older versions say "Database error saving new user". The signUp action
 *     recognises both.
 *   * The code stays in the account's own metadata (GoTrue writes metadata
 *     back after the insert, so it cannot be stripped here). It is spent, and
 *     only that account can see it.
 */
create or replace function public.enforce_signup_invite()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text := upper(trim(coalesce(new.raw_user_meta_data ->> 'signup_code', '')));
begin
  if not coalesce((select s.invite_only from public.app_settings s where s.id = 1), false) then
    return new;
  end if;

  update public.signup_invites i
     set uses = i.uses + 1,
         last_used_at = now()
   where i.code = v_code
     and i.revoked_at is null
     and (i.expires_at is null or i.expires_at > now())
     and i.uses < i.max_uses;

  if not found then
    raise exception 'Signups are invite-only: a valid, unexpired invite code is required.';
  end if;

  return new;
end;
$$;

drop trigger if exists enforce_signup_invite on auth.users;
create trigger enforce_signup_invite
  before insert on auth.users
  for each row execute function public.enforce_signup_invite();

-- ------------------------------------------------- operator aggregates
--
-- All four are SECURITY DEFINER because they read auth.users, and all four are
-- executable by service_role only — the server's secret key, after it has
-- checked that the signed-in user is on ADMIN_EMAILS. Every column they return
-- is listed in the boundary at the top of this file.

/**
 * The dashboard's totals. "Active" is an account that signed in or started a
 * session in the window — the only two activity signals inside the boundary.
 */
create or replace function public.admin_overview(p_week_start date)
returns table (
  accounts bigint,
  active_7d bigint,
  active_30d bigint,
  sessions_this_week bigint,
  disabled bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with trained as (
    select ws.user_id, max(ws.started_at) as last_started
    from public.workout_sessions ws
    where ws.started_at > now() - interval '30 days'
    group by ws.user_id
  ),
  seen as (
    select
      greatest(u.last_sign_in_at, t.last_started) as last_seen,
      coalesce(u.banned_until > now(), false) as is_disabled
    from auth.users u
    left join trained t on t.user_id = u.id
  )
  select
    count(*),
    count(*) filter (where seen.last_seen > now() - interval '7 days'),
    count(*) filter (where seen.last_seen > now() - interval '30 days'),
    (select count(*) from public.workout_sessions ws
      where ws.started_at >= p_week_start::timestamptz),
    count(*) filter (where seen.is_disabled)
  from seen;
$$;

/**
 * One page of accounts, newest first, optionally narrowed to emails containing
 * p_search. total is the number of matches across all pages.
 */
create or replace function public.admin_accounts(p_search text, p_limit int, p_offset int)
returns table (
  user_id uuid,
  email text,
  created_at timestamptz,
  last_sign_in_at timestamptz,
  disabled boolean,
  finished_sessions bigint,
  last_trained_at timestamptz,
  open_session_since timestamptz,
  total bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with matched as (
    select
      u.id,
      u.email::text as email,
      u.created_at,
      u.last_sign_in_at,
      coalesce(u.banned_until > now(), false) as is_disabled,
      count(*) over () as total
    from auth.users u
    where coalesce(trim(p_search), '') = ''
       or u.email ilike '%' || replace(replace(replace(trim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
    order by u.created_at desc, u.id
    limit least(greatest(coalesce(p_limit, 20), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select
    m.id,
    m.email,
    m.created_at,
    m.last_sign_in_at,
    m.is_disabled,
    coalesce(f.finished, 0),
    f.last_started,
    o.started_at,
    m.total
  from matched m
  left join lateral (
    select count(*) as finished, max(ws.started_at) as last_started
    from public.workout_sessions ws
    where ws.user_id = m.id and ws.ended_at is not null
  ) f on true
  left join lateral (
    select ws.started_at
    from public.workout_sessions ws
    where ws.user_id = m.id and ws.ended_at is null
    order by ws.started_at desc
    limit 1
  ) o on true
  order by m.created_at desc, m.id;
$$;

/**
 * Who is training right now: an open session started in the last four hours,
 * on an account that is not disabled. Email and start time, nothing else —
 * not the day, the exercise or how far through they are.
 */
create or replace function public.admin_training_now()
returns table (email text, started_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select u.email::text, ws.started_at
  from public.workout_sessions ws
  join auth.users u on u.id = ws.user_id
  where ws.ended_at is null
    and ws.started_at > now() - interval '4 hours'
    and not coalesce(u.banned_until > now(), false)
  order by ws.started_at;
$$;

/**
 * Ends every session of one account, so disabling it signs it out now.
 *
 * Banning (done through the Auth admin API) stops new sign-ins and refreshes,
 * but leaves current sessions alive. Deleting them makes the next getUser()
 * fail with session_not_found, which the middleware treats as signed out.
 * Refresh tokens go with them (ON DELETE CASCADE).
 */
create or replace function public.admin_end_sessions(p_user uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  delete from auth.sessions s where s.user_id = p_user;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ------------------------------------------------------------------ grants
--
-- Supabase's default privileges grant EXECUTE on new functions to anon and
-- authenticated explicitly, so revoking from public alone is not enough.

revoke all on function public.signup_invite_required() from public, anon, authenticated;
grant execute on function public.signup_invite_required() to anon, authenticated, service_role;

-- A trigger function; nothing should call it directly.
revoke all on function public.enforce_signup_invite() from public, anon, authenticated;

revoke all on function public.admin_overview(date) from public, anon, authenticated;
revoke all on function public.admin_accounts(text, int, int) from public, anon, authenticated;
revoke all on function public.admin_training_now() from public, anon, authenticated;
revoke all on function public.admin_end_sessions(uuid) from public, anon, authenticated;

grant execute on function public.admin_overview(date) to service_role;
grant execute on function public.admin_accounts(text, int, int) to service_role;
grant execute on function public.admin_training_now() to service_role;
grant execute on function public.admin_end_sessions(uuid) to service_role;


-- ========================================================================
-- 20261020000035_accent.sql
-- ========================================================================

-- JLIKA Gym — an accent colour per account.
--
-- Lime stays the default and the brand. The others are all light enough that
-- the dark label every accent button already uses keeps its contrast, so a
-- choice here never makes a button unreadable. The surfaces stay dark: the
-- design is dark-only, and this changes the highlight, not the room.

alter table public.profiles
  add column if not exists accent text not null default 'lime';

alter table public.profiles
  drop constraint if exists profiles_accent_check;
alter table public.profiles
  add constraint profiles_accent_check
  check (accent in ('lime', 'orange', 'yellow', 'coral', 'pink', 'violet', 'sky', 'mint'));
